input.content:
:root {
  --bg: #f4f5f8; --card: #ffffff; --text: #1f2433; --muted: #5d667a; --border: #dde1ea;
  --primary: #1e3a5f; --on-primary: #ffffff; --accent: #0f9488;
  --ok: #059669; --ok-bg: #e6f7f0; --warn: #b45309; --warn-bg: #fff4e0; --bad: #c62828; --bad-bg: #fdeaea;
  --page: #fffdf7;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #1c1f26; --card: #262a33; --text: #eceef3; --muted: #a7aebd; --border: #3a3f4b;
    --primary: #5b8dd6; --on-primary: #0f1420; --accent: #2dd4bf;
    --ok: #34d399; --ok-bg: #163a2e; --warn: #fbbf24; --warn-bg: #3d2f10; --bad: #f87171; --bad-bg: #40201f;
    --page: #2d2f36;
  }
}
:root[data-theme="dark"] {
  --bg: #1c1f26; --card: #262a33; --text: #eceef3; --muted: #a7aebd; --border: #3a3f4b;
  --primary: #5b8dd6; --on-primary: #0f1420; --accent: #2dd4bf;
  --ok: #34d399; --ok-bg: #163a2e; --warn: #fbbf24; --warn-bg: #3d2f10; --bad: #f87171; --bad-bg: #40201f;
  --page: #2d2f36;
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 16px/1.5 Inter, Roboto, system-ui, -apple-system, "Segoe UI", sans-serif;
  padding-bottom: 72px;
}
header.top {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 10px 16px; background: var(--primary); color: var(--on-primary);
}
header.top b { font-size: 17px; }
header.top .tools { display: flex; gap: 8px; }
main { max-width: 640px; margin: 0 auto; padding: 16px; }
h1 { font-size: 22px; margin: 4px 0 12px; }
h2 { font-size: 17px; margin: 20px 0 8px; }
.muted { color: var(--muted); font-size: 14px; }
.card {
  background: var(--card); border: 1px solid var(--border); border-radius: 10px;
  padding: 14px; margin: 10px 0;
}
.banner { padding: 10px 14px; border-radius: 8px; margin: 0 0 10px; font-size: 14px; }
.banner.off { background: var(--warn-bg); color: var(--warn); border: 1px solid var(--warn); }
.banner.demo { background: var(--card); border: 1px dashed var(--border); color: var(--muted); }
button, .btn {
  min-height: 48px; min-width: 48px; padding: 10px 16px; font: inherit; font-weight: 600;
  border-radius: 8px; border: 1px solid var(--border); background: var(--card); color: var(--text);
  cursor: pointer;
}
button.primary { background: var(--primary); color: var(--on-primary); border-color: var(--primary); }
button.ok { background: var(--ok); color: #fff; border-color: var(--ok); }
button.sm { min-height: 40px; padding: 6px 12px; font-size: 14px; }
button.link { border: none; background: none; color: var(--muted); text-decoration: underline; font-weight: 400; min-height: 40px; }
button:disabled { opacity: .45; cursor: not-allowed; }
button:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
button.tool { min-height: 36px; padding: 4px 10px; font-size: 13px; background: transparent; color: var(--on-primary); border-color: rgba(255,255,255,.5); }
input[type=text], input[type=tel], select {
  width: 100%; min-height: 48px; padding: 8px 12px; font: inherit; border-radius: 8px;
  border: 1px solid var(--border); background: var(--card); color: var(--text);
}
.row { display: flex; gap: 8px; align-items: center; }
.row.between { justify-content: space-between; }
.grow { flex: 1; }
.seg { display: flex; gap: 8px; margin-bottom: 12px; }
.seg button[aria-pressed=true] { background: var(--primary); color: var(--on-primary); border-color: var(--primary); }
.badge { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 13px; font-weight: 600; }
.badge.ok { background: var(--ok-bg); color: var(--ok); }
.badge.pend { background: var(--bad-bg); color: var(--bad); }
.badge.warn { background: var(--warn-bg); color: var(--warn); }
.bar { height: 8px; background: var(--border); border-radius: 4px; overflow: hidden; }
.bar > i { display: block; height: 100%; width: 0; background: var(--accent); }
.pending-card { border-color: var(--warn); background: var(--warn-bg); }
.lesson-item { display: flex; align-items: center; gap: 12px; }
.lesson-item .grow { min-width: 0; }
/* textbook page */
.book {
  background: var(--page); border: 1px solid var(--border); border-radius: 6px; padding: 18px 16px 12px;
  font-family: Georgia, "Times New Roman", serif; line-height: 1.6;
}
.book h3 { margin: 0 0 10px; font-size: 19px; }
.book p { margin: 8px 0; }
.book .eq { text-align: center; font-style: italic; margin: 10px 0; padding: 6px; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.book .pn { text-align: center; color: var(--muted); font-size: 13px; margin-top: 12px; }
.book img { width: 100%; height: auto; display: block; }
.sample { font: 12px Inter, sans-serif; color: var(--muted); text-align: center; margin-top: 6px; }
details.transcript { margin: 10px 0; }
details.transcript summary { cursor: pointer; padding: 10px 0; font-weight: 600; }
.seg-line { padding: 6px 8px; border-radius: 6px; }
.seg-line.on { background: var(--ok-bg); }
.player {
  position: sticky; bottom: 60px; background: var(--card); border: 1px solid var(--border);
  border-radius: 12px; padding: 12px; margin-top: 12px;
}
.player .controls { display: flex; gap: 8px; align-items: center; justify-content: center; margin: 10px 0 4px; }
.player .play { min-width: 64px; }
/* quiz */
.opt { display: block; width: 100%; text-align: left; margin: 8px 0; }
.opt[aria-checked=true] { border-color: var(--primary); background: var(--primary); color: var(--on-primary); }
.bigtick { font-size: 64px; text-align: center; color: var(--ok); line-height: 1; }
.bigsoft { font-size: 48px; text-align: center; color: var(--warn); line-height: 1; }
/* attendance */
.att { display: flex; align-items: center; gap: 8px; }
.att .name { flex: 1; min-width: 0; }
.att button[aria-pressed=true].p { background: var(--ok); color: #fff; border-color: var(--ok); }
.att button[aria-pressed=true].a { background: var(--bad); color: #fff; border-color: var(--bad); }
/* whatsapp */
.chat { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 8px; }
.bubble { background: var(--ok-bg); border-radius: 10px 10px 10px 2px; padding: 8px 12px; margin: 8px 0; max-width: 92%; }
.bubble .meta { font-size: 12px; color: var(--muted); }
.bubble a { color: var(--accent); word-break: break-all; }
nav.bottom {
  position: fixed; left: 0; right: 0; bottom: 0; display: flex; background: var(--card);
  border-top: 1px solid var(--border); z-index: 5;
}
nav.bottom a {
  flex: 1; text-align: center; padding: 14px 4px; min-height: 56px; color: var(--muted);
  text-decoration: none; font-weight: 600; font-size: 14px;
}
nav.bottom a[aria-current=page] { color: var(--primary); border-top: 3px solid var(--primary); padding-top: 11px; }
@media (max-width: 360px) { main { padding: 12px; } }

