(function () {
  'use strict';

  var LS = 'edusaas_demo_v1';
  var LESSONS = window.LESSONS, STUDENTS = window.STUDENTS, MISSED = window.MISSED_LESSON;
  var PASS = 4; // 4 of 5 = 80%
  var app = document.getElementById('app');

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function fresh() {
    return { role: null, offline: false, att: {}, submitted: false, clear: {}, msgs: [], listened: {} };
  }
  function load() {
    try { var x = JSON.parse(localStorage.getItem(LS)); if (x) return Object.assign(fresh(), x); } catch (e) {}
    return fresh();
  }
  var S = load();
  function save() { try { localStorage.setItem(LS, JSON.stringify(S)); } catch (e) {} }
  function lesson(id) { return LESSONS.filter(function (l) { return l.id === id; })[0]; }
  function student(id) { return STUDENTS.filter(function (s) { return s.id === id; })[0]; }
  function hm(t) { return new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
  function addMsg(to, text) { S.msgs.push({ t: Date.now(), to: to, text: text }); }
  var ME = 's1'; // the student who logs in during the demo

  /* ---------- top tools ---------- */
  var tOff = document.getElementById('t-offline');
  function syncTools() {
    tOff.textContent = 'Offline: ' + (S.offline ? 'on' : 'off');
    tOff.setAttribute('aria-pressed', S.offline);
  }
  tOff.onclick = function () { S.offline = !S.offline; save(); syncTools(); route(); };
  document.getElementById('t-theme').onclick = function () {
    var r = document.documentElement, cur = r.getAttribute('data-theme');
    var dark = cur ? cur === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    r.setAttribute('data-theme', dark ? 'light' : 'dark');
  };
  document.getElementById('t-reset').onclick = function () {
    stopAudio(); S = fresh(); save(); syncTools(); location.hash = '#/login'; route();
  };

  /* ---------- navigation ---------- */
  function nav() {
    var n = document.getElementById('nav');
    if (!S.role) { n.innerHTML = ''; return; }
    var items = S.role === 'student'
      ? [['#/home', 'Home'], ['#/msgs', 'Parent WhatsApp']]
      : [['#/teacher', 'Attendance'], ['#/msgs', 'WhatsApp log']];
    var h = location.hash.split('?')[0];
    n.innerHTML = items.map(function (i) {
      return '<a href="' + i[0] + '"' + (h === i[0] ? ' aria-current="page"' : '') + '>' + i[1] + '</a>';
    }).join('') + '<a href="#/logout">Log out</a>';
  }
  function banner() {
    var off = S.offline || !navigator.onLine;
    return off ? '<div class="banner off" role="status">You are offline. Using cached lessons. Progress will sync when you reconnect.</div>' : '';
  }

  var routes = {};
  function route() {
    var h = location.hash || '#/login';
    var parts = h.split('/'); // ['#', name, arg]
    var name = parts[1] || 'login', arg = parts[2];
    if (name !== 'lesson') stopAudio();
    if (!S.role && name !== 'login') { location.hash = '#/login'; return; }
    (routes[name] || routes.login)(arg);
    nav();
    window.scrollTo(0, 0);
  }
  window.addEventListener('hashchange', route);

  /* ---------- login ---------- */
  routes.login = function () {
    var role = 'student', step = 'phone';
    function draw() {
      var isS = role === 'student';
      var hint = isS ? '+92 300 0000001 (Ali Raza)' : '+92 300 0000099 (Mr. Tariq)';
      app.innerHTML =
        '<h1>Welcome</h1>' +
        '<div class="banner demo">Demo mode. Any number works. The OTP is <b>1234</b>. Data lives only in this browser.</div>' +
        '<div class="seg" role="group" aria-label="Role">' +
        '<button id="r-s" aria-pressed="' + isS + '">Student</button>' +
        '<button id="r-t" aria-pressed="' + !isS + '">Teacher</button></div>' +
        (step === 'phone'
          ? '<label for="ph">Phone number</label><input id="ph" type="tel" inputmode="numeric" value="+92" autocomplete="tel">' +
            '<p class="muted">Try: ' + hint + '</p><button class="primary" id="go" style="width:100%">Send OTP</button>'
          : '<label for="otp">Enter the 4-digit OTP</label><input id="otp" type="text" inputmode="numeric" maxlength="4" autocomplete="one-time-code">' +
            '<p class="muted" id="err" role="alert"></p><p class="muted">Resend in <span id="cd">30</span>s</p>');
      document.getElementById('r-s').onclick = function () { role = 'student'; draw(); };
      document.getElementById('r-t').onclick = function () { role = 'teacher'; draw(); };
      if (step === 'phone') {
        document.getElementById('go').onclick = function () {
          var v = document.getElementById('ph').value.replace(/\s/g, '');
          if (!/^\+923\d{9}$/.test(v)) { alert('Enter a number like +923001234567 (E.164 format).'); return; }
          step = 'otp'; draw();
        };
      } else {
        var o = document.getElementById('otp'), cd = document.getElementById('cd'), n = 30;
        var iv = setInterval(function () { if (!document.body.contains(cd)) { clearInterval(iv); return; } n = Math.max(0, n - 1); cd.textContent = n; }, 1000);
        o.focus();
        o.oninput = function () {
          if (o.value.length === 4) {
            if (o.value === '1234') {
              S.role = role; save(); clearInterval(iv);
              var dest = (location.hash.indexOf('lesson') > -1) ? location.hash : (role === 'student' ? '#/home' : '#/teacher');
              location.hash = role === 'student' ? '#/home' : '#/teacher'; if (dest !== location.hash) location.hash = dest;
              route();
            } else document.getElementById('err').textContent = 'Wrong or expired OTP. Please try again.';
          }
        };
      }
    }
    draw();
  };
  routes.logout = function () { S.role = null; save(); location.hash = '#/login'; };

  /* ---------- student home ---------- */
  function statusOf(sid) { return S.clear[sid]; }
  routes.home = function () {
    if (S.role !== 'student') { location.hash = '#/teacher'; return; }
    var me = student(ME), c = statusOf(ME), pending = c && !c.cleared;
    var html = banner() + '<h1>Assalam o alaikum, ' + esc(me.name.split(' ')[0]) + '</h1>';
    if (pending) {
      var l = lesson(MISSED);
      html += '<div class="card pending-card"><b>Pending clearance</b><p>You were marked absent. Complete <b>' +
        esc(l.subject + ' \u2013 ' + l.title) + '</b> and pass the quiz (' + PASS + '/5) to be cleared for class.</p>' +
        '<a href="#/lesson/' + l.id + '"><button class="primary" style="width:100%">View missed lesson</button></a></div>';
    } else if (c && c.cleared) {
      html += '<div class="card"><span class="badge ok">\u2714 Cleared for class</span> <span class="muted">Your teacher can see the green tick.</span></div>';
    } else {
      html += '<div class="card"><b>No missed classes today!</b><p class="muted">In the demo, log in as the teacher, mark Ali absent and submit. Then return here.</p></div>';
    }
    html += '<h2>Today\u2019s syllabus</h2>';
    LESSONS.forEach(function (l) {
      var done = S.listened[l.id];
      html += '<a href="#/lesson/' + l.id + '" style="text-decoration:none;color:inherit"><div class="card lesson-item"><div class="grow"><b>' +
        esc(l.subject) + ' \u2013 ' + esc(l.chapter) + '</b><div>' + esc(l.title) + '</div><div class="muted">Page ' + l.pageNumber +
        ' \u00B7 ' + l.minutes + ' min</div><div class="bar" style="margin-top:8px"><i style="width:' + (done ? 100 : 0) + '%"></i></div></div>' +
        (done ? '<span class="badge ok">Done</span>' : '') + '</div></a>';
    });
    app.innerHTML = html;
  };

  /* ---------- audio player (browser speech) ---------- */
  var P = null;
  function stopAudio() {
    if (!P) return;
    P.token++; P.playing = false; clearTimeout(P.timer);
    try { window.speechSynthesis && speechSynthesis.cancel(); } catch (e) {}
    try { P.lock && P.lock.release(); } catch (e) {}
  }
  function pickVoice() {
    var vs = window.speechSynthesis ? speechSynthesis.getVoices() : [];
    var pref = ['ur', 'hi', 'en-IN', 'en-GB', 'en'];
    for (var i = 0; i < pref.length; i++) {
      for (var j = 0; j < vs.length; j++) if (vs[j].lang.indexOf(pref[i]) === 0) return vs[j];
    }
    return vs[0] || null;
  }
  routes.lesson = function (id) {
    var l = lesson(id);
    if (!l) { location.hash = '#/home'; return; }
    var total = l.script.join('').length;
    P = { l: l, i: 0, playing: false, rate: 1, token: 0, heard: {}, voice: pickVoice(), timer: null };
    var unlocked = !!S.listened[id];
    var rate = 1;

    var pageHtml = l.image
      ? '<img src="' + esc(l.image) + '" alt="Textbook page ' + l.pageNumber + '">'
      : l.page.map(function (b) {
          return b.t === 'h' ? '<h3>' + esc(b.x) + '</h3>' : b.t === 'eq' ? '<div class="eq">' + esc(b.x) + '</div>' : '<p>' + esc(b.x) + '</p>';
        }).join('') + '<div class="pn">\u2014 ' + l.pageNumber + ' \u2014</div>';

    app.innerHTML = banner() +
      '<a href="#/home" class="muted">\u2190 Back</a><h1>' + esc(l.subject + ' \u2013 ' + l.chapter) + '</h1>' +
      '<div class="muted">' + esc(l.title) + ' \u00B7 Page ' + l.pageNumber + '</div>' +
      '<div class="card book" style="margin-top:10px">' + pageHtml + '</div>' +
      (l.image ? '' : '<div class="sample">Sample page written for the demo. Your textbook page appears here.</div>') +
      '<details class="transcript"><summary>Transcript</summary>' +
      l.script.map(function (s, k) { return '<div class="seg-line" id="sg' + k + '">' + esc(s) + '</div>'; }).join('') + '</details>' +
      '<div class="player" role="group" aria-label="Audio player">' +
      '<div class="bar" aria-hidden="true"><i id="pb"></i></div>' +
      '<div class="row between muted"><span id="pt">0%</span><span id="ps"></span></div>' +
      '<div class="controls">' +
      '<button id="pv" aria-label="Previous section">\u23EE</button>' +
      '<button id="pp" class="primary play" aria-label="Play">\u25B6</button>' +
      '<button id="pn" aria-label="Next section">\u23ED</button>' +
      '<button id="pr" aria-label="Speed">1x</button></div>' +
      '<div class="row"><select id="vs" aria-label="Voice"></select></div>' +
      '<p class="muted" id="vh">Demo audio uses this device\u2019s built-in voice. Final product uses pre-generated AI narration.</p>' +
      '<button class="primary" id="qz" style="width:100%" ' + (unlocked ? '' : 'disabled') + '>' + (unlocked ? 'Start quiz' : 'Quiz unlocks after you listen (90%)') + '</button>' +
      '<div style="text-align:center"><button class="link" id="ml">Mark as listened (demo shortcut)</button></div></div>';

    var pb = document.getElementById('pb'), pt = document.getElementById('pt'), pp = document.getElementById('pp');
    var hasTTS = 'speechSynthesis' in window;
    function heardChars() {
      var n = 0; for (var k in P.heard) n += l.script[k].length; return n;
    }
    function ui() {
      var pct = Math.min(100, Math.round(heardChars() / total * 100));
      pb.style.width = pct + '%'; pt.textContent = pct + '% heard';
      document.getElementById('ps').textContent = 'Section ' + Math.min(P.i + 1, l.script.length) + ' of ' + l.script.length;
      pp.textContent = P.playing ? '\u23F8' : '\u25B6'; pp.setAttribute('aria-label', P.playing ? 'Pause' : 'Play');
      l.script.forEach(function (s, k) {
        var e = document.getElementById('sg' + k); if (e) e.className = 'seg-line' + (P.playing && k === P.i ? ' on' : '');
      });
      if (pct >= 90) unlock();
    }
    function unlock() {
      S.listened[id] = true; save();
      var q = document.getElementById('qz'); q.disabled = false; q.textContent = 'Start quiz';
    }
    function step() {
      if (!P.playing) return;
      if (P.i >= l.script.length) { P.playing = false; ui(); return; }
      var my = ++P.token, k = P.i;
      function next() { if (my !== P.token) return; P.heard[k] = true; P.i = k + 1; ui(); step(); }
      ui();
      if (!hasTTS || !P.voice) { P.timer = setTimeout(next, l.script[k].length * 55 / rate); return; }
      var u = new SpeechSynthesisUtterance(l.script[k]);
      u.voice = P.voice; u.lang = P.voice.lang; u.rate = rate;
      u.onend = next;
      u.onerror = function () { if (my === P.token) P.timer = setTimeout(next, 800); };
      speechSynthesis.speak(u);
    }
    function halt() { P.token++; P.playing = false; clearTimeout(P.timer); if (hasTTS) speechSynthesis.cancel(); ui(); }
    pp.onclick = function () {
      if (P.playing) { halt(); return; }
      if (P.i >= l.script.length) P.i = 0;
      P.playing = true;
      try { if (navigator.wakeLock) navigator.wakeLock.request('screen').then(function (w) { P.lock = w; }, function () {}); } catch (e) {}
      if (hasTTS) speechSynthesis.cancel();
      step();
    };
    function jump(d) {
      var was = P.playing; halt();
      P.i = Math.max(0, Math.min(l.script.length - 1, P.i + d)); ui();
      if (was) { P.playing = true; step(); }
    }
    document.getElementById('pv').onclick = function () { jump(-1); };
    document.getElementById('pn').onclick = function () { jump(1); };
    document.getElementById('pr').onclick = function () {
      rate = rate === 1 ? 1.25 : rate === 1.25 ? 1.5 : 1;
      this.textContent = rate + 'x';
      if (P.playing) { var was = P.playing; halt(); P.playing = was; step(); }
    };
    document.getElementById('ml').onclick = function () { unlock(); };
    document.getElementById('qz').onclick = function () { location.hash = '#/quiz/' + id; };

    var sel = document.getElementById('vs');
    function fillVoices() {
      var vs = hasTTS ? speechSynthesis.getVoices() : [];
      sel.innerHTML = vs.length ? vs.map(function (v, k) { return '<option value="' + k + '">' + esc(v.name + ' (' + v.lang + ')') + '</option>'; }).join('')
        : '<option>No voices found (simulated timing)</option>';
      P.voice = P.voice && vs.indexOf(P.voice) > -1 ? P.voice : pickVoice();
      var ix = vs.indexOf(P.voice); if (ix > -1) sel.value = ix;
    }
    sel.onchange = function () { var vs = speechSynthesis.getVoices(); P.voice = vs[+sel.value] || P.voice; };
    if (hasTTS) speechSynthesis.onvoiceschanged = fillVoices;
    fillVoices(); ui();
  };

  /* ---------- quiz ---------- */
  var Q = null;
  function shuffle(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  routes.quiz = function (id) {
    var l = lesson(id);
    if (!l) { location.hash = '#/home'; return; }
    if (!S.listened[id]) { location.hash = '#/lesson/' + id; return; }
    Q = { id: id, items: shuffle(l.quiz).slice(0, 5), i: 0, ans: [], sel: null };
    drawQ();
  };
  function drawQ() {
    var it = Q.items[Q.i], last = Q.i === Q.items.length - 1;
    app.innerHTML = banner() + '<div class="row between"><b>Question ' + (Q.i + 1) + ' of ' + Q.items.length + '</b><span class="muted">' + PASS + ' correct to pass</span></div>' +
      '<div class="bar" style="margin:8px 0 16px"><i style="width:' + (Q.i / Q.items.length * 100) + '%"></i></div>' +
      '<div class="card"><p style="margin-top:0"><b>' + esc(it.q) + '</b></p><div role="radiogroup" aria-label="Options">' +
      it.o.map(function (o, k) { return '<button class="opt" role="radio" aria-checked="false" data-k="' + k + '">' + esc(o) + '</button>'; }).join('') +
      '</div></div><button class="primary" id="nx" style="width:100%" disabled>' + (last ? 'Submit' : 'Next') + '</button>';
    var opts = app.querySelectorAll('.opt'), nx = document.getElementById('nx');
    Array.prototype.forEach.call(opts, function (b) {
      b.onclick = function () {
        Q.sel = +b.getAttribute('data-k');
        Array.prototype.forEach.call(opts, function (x) { x.setAttribute('aria-checked', x === b); });
        nx.disabled = false;
      };
    });
    nx.onclick = function () {
      Q.ans.push(Q.sel); Q.sel = null;
      if (last) finishQuiz(); else { Q.i++; drawQ(); }
    };
  }
  function finishQuiz() {
    var score = 0;
    Q.items.forEach(function (it, k) { if (Q.ans[k] === it.a) score++; });
    var pass = score >= PASS, c = S.clear[ME], attempts = 1;
    if (c) {
      c.attempts = (c.attempts || 0) + 1; attempts = c.attempts; c.score = score; c.last = Date.now();
      if (pass && !c.cleared && Q.id === MISSED) {
        c.cleared = true; c.by = 'quiz';
        var me = student(ME), l = lesson(MISSED);
        addMsg('Parent of ' + me.name + ' (' + me.parent + ')', 'Dear Parent, ' + me.name + ' has completed the missed lecture (' + l.subject + ' \u2013 ' + l.title + ') and passed the assessment (' + score + '/5). Cleared for class entry.');
        addMsg('Teacher (Mr. Tariq)', me.name + ' has completed the missed lecture and passed the assessment (' + score + '/5). Cleared for class entry.');
      }
    }
    save();
    Q.result = { score: score, pass: pass, attempts: attempts };
    location.hash = '#/result';
  }
  routes.result = function () {
    if (!Q || !Q.result) { location.hash = '#/home'; return; }
    var r = Q.result, id = Q.id;
    app.innerHTML = banner() + (r.pass
      ? '<div class="bigtick" aria-hidden="true">\u2714</div><h1 style="text-align:center">Great job, you passed!</h1><p style="text-align:center">You scored ' + r.score + '/5. ' +
        (S.clear[ME] && S.clear[ME].cleared ? '<span class="badge ok">Cleared for class</span><br><span class="muted">Your parent and teacher have been notified on WhatsApp.</span>' : '') + '</p>' +
        '<a href="#/home"><button class="primary" style="width:100%">Back to home</button></a>'
      : '<div class="bigsoft" aria-hidden="true">\u21BB</div><h1 style="text-align:center">Almost there</h1><p style="text-align:center">You scored ' + r.score + '/5. You need ' + PASS + '/5 to pass. Let\u2019s try again!' +
        (r.attempts >= 3 ? '<br><b>Tip:</b> please review the lesson once more before retrying.' : '') + '</p>' +
        '<a href="#/lesson/' + id + '"><button style="width:100%;margin-bottom:8px">Review lesson</button></a>' +
        '<a href="#/quiz/' + id + '"><button class="primary" style="width:100%">Retry quiz</button></a>');
  };

  /* ---------- teacher ---------- */
  routes.teacher = function () {
    if (S.role !== 'teacher') { location.hash = '#/home'; return; }
    var html = '<h1>11th Pre-Medical A</h1><div class="muted">' + new Date().toDateString() + ' \u00B7 ' + esc(lesson(MISSED).subject) + ' period</div>';
    // clearance widget
    var pend = STUDENTS.filter(function (s) { return S.clear[s.id]; });
    if (S.submitted && pend.length) {
      html += '<h2>Class clearance</h2>';
      pend.forEach(function (s) {
        var c = S.clear[s.id];
        html += '<div class="card"><div class="row between"><b>' + esc(s.name) + '</b>' +
          (c.cleared ? '<span class="badge ok">\u2714 Cleared</span>' : '<span class="badge pend">\u2716 Pending</span>') + '</div>' +
          '<div class="muted">' + (c.last ? 'Last attempt ' + hm(c.last) + ' \u00B7 score ' + c.score + '/5 \u00B7 attempts ' + c.attempts
            : 'No attempt yet') + (c.by === 'teacher' ? ' \u00B7 cleared by teacher' : '') + '</div>' +
          (c.cleared ? '' : '<button class="sm" data-ov="' + s.id + '" style="margin-top:8px">Clear manually (teacher override)</button>') + '</div>';
      });
      html += '<p class="muted">Refresh happens automatically when the student passes in this same browser.</p>';
    }
    html += '<h2>Attendance</h2><div class="card">';
    STUDENTS.forEach(function (s) {
      var st = S.att[s.id] || 'present';
      html += '<div class="att" style="padding:6px 0"><div class="name"><b>' + esc(s.name) + '</b><div class="muted">' + s.roll + '</div></div>' +
        '<button class="p" data-a="' + s.id + '" data-v="present" aria-pressed="' + (st === 'present') + '">Present</button>' +
        '<button class="a" data-a="' + s.id + '" data-v="absent" aria-pressed="' + (st === 'absent') + '">Absent</button></div>';
    });
    html += '</div><div class="row"><button class="grow" id="allp">Mark all present</button><button class="primary grow" id="sub">Submit attendance</button></div>';
    app.innerHTML = html;

    Array.prototype.forEach.call(app.querySelectorAll('[data-a]'), function (b) {
      b.onclick = function () { S.att[b.getAttribute('data-a')] = b.getAttribute('data-v'); save(); routes.teacher(); };
    });
    document.getElementById('allp').onclick = function () { S.att = {}; save(); routes.teacher(); };
    document.getElementById('sub').onclick = function () {
      var l = lesson(MISSED), n = 0;
      STUDENTS.forEach(function (s) {
        if (S.att[s.id] === 'absent') {
          if (!S.clear[s.id]) {
            S.clear[s.id] = { cleared: false, attempts: 0 }; n++;
            addMsg('Parent of ' + s.name + ' (' + s.parent + ')', 'Dear Parent, ' + s.name + ' was marked absent today. Missed lecture: ' + l.subject + ' \u2013 ' + l.title +
              '. Please ensure he completes the digital backup lecture: https://demo.edusaas.example/l/' + l.id);
          }
        } else if (S.clear[s.id] && !S.clear[s.id].cleared) delete S.clear[s.id];
      });
      S.submitted = true; save(); routes.teacher();
      alert(n ? n + ' WhatsApp alert(s) sent. See the WhatsApp log tab.' : 'Attendance saved.');
    };
    Array.prototype.forEach.call(app.querySelectorAll('[data-ov]'), function (b) {
      b.onclick = function () {
        var s = student(b.getAttribute('data-ov')), c = S.clear[s.id];
        c.cleared = true; c.by = 'teacher';
        addMsg('Parent of ' + s.name + ' (' + s.parent + ')', 'Dear Parent, ' + s.name + ' has been cleared for class entry by the teacher.');
        save(); routes.teacher();
      };
    });
  };

  /* ---------- WhatsApp log ---------- */
  routes.msgs = function () {
    var html = '<h1>' + (S.role === 'teacher' ? 'WhatsApp log' : 'Parent\u2019s WhatsApp') + '</h1><div class="banner demo">Simulated. In the real product these are sent through the WhatsApp Business API, with SMS as a fallback.</div><div class="chat">';
    if (!S.msgs.length) html += '<p class="muted" style="padding:8px">No messages yet. Mark a student absent as the teacher to trigger one.</p>';
    S.msgs.forEach(function (m) {
      var text = esc(m.text).replace(/(https?:\/\/[^\s]+)/g, '<a href="#/lesson/' + MISSED + '">$1</a>');
      html += '<div class="bubble"><div class="meta">To: ' + esc(m.to) + ' \u00B7 ' + hm(m.t) + ' \u00B7 \u2713\u2713 Delivered</div>' + text + '</div>';
    });
    app.innerHTML = html + '</div>';
  };

  syncTools();
  if (!location.hash) location.hash = '#/login';
  route();
})();

toolUseResult.content:
(function () {
  'use strict';

  var LS = 'edusaas_demo_v1';
  var LESSONS = window.LESSONS, STUDENTS = window.STUDENTS, MISSED = window.MISSED_LESSON;
  var PASS = 4; // 4 of 5 = 80%
  var app = document.getElementById('app');

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function fresh() {
    return { role: null, offline: false, att: {}, submitted: false, clear: {}, msgs: [], listened: {} };
  }
  function load() {
    try { var x = JSON.parse(localStorage.getItem(LS)); if (x) return Object.assign(fresh(), x); } catch (e) {}
    return fresh();
  }
  var S = load();
  function save() { try { localStorage.setItem(LS, JSON.stringify(S)); } catch (e) {} }
  function lesson(id) { return LESSONS.filter(function (l) { return l.id === id; })[0]; }
  function student(id) { return STUDENTS.filter(function (s) { return s.id === id; })[0]; }
  function hm(t) { return new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
  function addMsg(to, text) { S.msgs.push({ t: Date.now(), to: to, text: text }); }
  var ME = 's1'; // the student who logs in during the demo

  /* ---------- top tools ---------- */
  var tOff = document.getElementById('t-offline');
  function syncTools() {
    tOff.textContent = 'Offline: ' + (S.offline ? 'on' : 'off');
    tOff.setAttribute('aria-pressed', S.offline);
  }
  tOff.onclick = function () { S.offline = !S.offline; save(); syncTools(); route(); };
  document.getElementById('t-theme').onclick = function () {
    var r = document.documentElement, cur = r.getAttribute('data-theme');
    var dark = cur ? cur === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    r.setAttribute('data-theme', dark ? 'light' : 'dark');
  };
  document.getElementById('t-reset').onclick = function () {
    stopAudio(); S = fresh(); save(); syncTools(); location.hash = '#/login'; route();
  };

  /* ---------- navigation ---------- */
  function nav() {
    var n = document.getElementById('nav');
    if (!S.role) { n.innerHTML = ''; return; }
    var items = S.role === 'student'
      ? [['#/home', 'Home'], ['#/msgs', 'Parent WhatsApp']]
      : [['#/teacher', 'Attendance'], ['#/msgs', 'WhatsApp log']];
    var h = location.hash.split('?')[0];
    n.innerHTML = items.map(function (i) {
      return '<a href="' + i[0] + '"' + (h === i[0] ? ' aria-current="page"' : '') + '>' + i[1] + '</a>';
    }).join('') + '<a href="#/logout">Log out</a>';
  }
  function banner() {
    var off = S.offline || !navigator.onLine;
    return off ? '<div class="banner off" role="status">You are offline. Using cached lessons. Progress will sync when you reconnect.</div>' : '';
  }

  var routes = {};
  function route() {
    var h = location.hash || '#/login';
    var parts = h.split('/'); // ['#', name, arg]
    var name = parts[1] || 'login', arg = parts[2];
    if (name !== 'lesson') stopAudio();
    if (!S.role && name !== 'login') { location.hash = '#/login'; return; }
    (routes[name] || routes.login)(arg);
    nav();
    window.scrollTo(0, 0);
  }
  window.addEventListener('hashchange', route);

  /* ---------- login ---------- */
  routes.login = function () {
    var role = 'student', step = 'phone';
    function draw() {
      var isS = role === 'student';
      var hint = isS ? '+92 300 0000001 (Ali Raza)' : '+92 300 0000099 (Mr. Tariq)';
      app.innerHTML =
        '<h1>Welcome</h1>' +
        '<div class="banner demo">Demo mode. Any number works. The OTP is <b>1234</b>. Data lives only in this browser.</div>' +
        '<div class="seg" role="group" aria-label="Role">' +
        '<button id="r-s" aria-pressed="' + isS + '">Student</button>' +
        '<button id="r-t" aria-pressed="' + !isS + '">Teacher</button></div>' +
        (step === 'phone'
          ? '<label for="ph">Phone number</label><input id="ph" type="tel" inputmode="numeric" value="+92" autocomplete="tel">' +
            '<p class="muted">Try: ' + hint + '</p><button class="primary" id="go" style="width:100%">Send OTP</button>'
          : '<label for="otp">Enter the 4-digit OTP</label><input id="otp" type="text" inputmode="numeric" maxlength="4" autocomplete="one-time-code">' +
            '<p class="muted" id="err" role="alert"></p><p class="muted">Resend in <span id="cd">30</span>s</p>');
      document.getElementById('r-s').onclick = function () { role = 'student'; draw(); };
      document.getElementById('r-t').onclick = function () { role = 'teacher'; draw(); };
      if (step === 'phone') {
        document.getElementById('go').onclick = function () {
          var v = document.getElementById('ph').value.replace(/\s/g, '');
          if (!/^\+923\d{9}$/.test(v)) { alert('Enter a number like +923001234567 (E.164 format).'); return; }
          step = 'otp'; draw();
        };
      } else {
        var o = document.getElementById('otp'), cd = document.getElementById('cd'), n = 30;
        var iv = setInterval(function () { if (!document.body.contains(cd)) { clearInterval(iv); return; } n = Math.max(0, n - 1); cd.textContent = n; }, 1000);
        o.focus();
        o.oninput = function () {
          if (o.value.length === 4) {
            if (o.value === '1234') {
              S.role = role; save(); clearInterval(iv);
              var dest = (location.hash.indexOf('lesson') > -1) ? location.hash : (role === 'student' ? '#/home' : '#/teacher');
              location.hash = role === 'student' ? '#/home' : '#/teacher'; if (dest !== location.hash) location.hash = dest;
              route();
            } else document.getElementById('err').textContent = 'Wrong or expired OTP. Please try again.';
          }
        };
      }
    }
    draw();
  };
  routes.logout = function () { S.role = null; save(); location.hash = '#/login'; };

  /* ---------- student home ---------- */
  function statusOf(sid) { return S.clear[sid]; }
  routes.home = function () {
    if (S.role !== 'student') { location.hash = '#/teacher'; return; }
    var me = student(ME), c = statusOf(ME), pending = c && !c.cleared;
    var html = banner() + '<h1>Assalam o alaikum, ' + esc(me.name.split(' ')[0]) + '</h1>';
    if (pending) {
      var l = lesson(MISSED);
      html += '<div class="card pending-card"><b>Pending clearance</b><p>You were marked absent. Complete <b>' +
        esc(l.subject + ' – ' + l.title) + '</b> and pass the quiz (' + PASS + '/5) to be cleared for class.</p>' +
        '<a href="#/lesson/' + l.id + '"><button class="primary" style="width:100%">View missed lesson</button></a></div>';
    } else if (c && c.cleared) {
      html += '<div class="card"><span class="badge ok">✔ Cleared for class</span> <span class="muted">Your teacher can see the green tick.</span></div>';
    } else {
      html += '<div class="card"><b>No missed classes today!</b><p class="muted">In the demo, log in as the teacher, mark Ali absent and submit. Then return here.</p></div>';
    }
    html += '<h2>Today’s syllabus</h2>';
    LESSONS.forEach(function (l) {
      var done = S.listened[l.id];
      html += '<a href="#/lesson/' + l.id + '" style="text-decoration:none;color:inherit"><div class="card lesson-item"><div class="grow"><b>' +
        esc(l.subject) + ' – ' + esc(l.chapter) + '</b><div>' + esc(l.title) + '</div><div class="muted">Page ' + l.pageNumber +
        ' · ' + l.minutes + ' min</div><div class="bar" style="margin-top:8px"><i style="width:' + (done ? 100 : 0) + '%"></i></div></div>' +
        (done ? '<span class="badge ok">Done</span>' : '') + '</div></a>';
    });
    app.innerHTML = html;
  };

  /* ---------- audio player (browser speech) ---------- */
  var P = null;
  function stopAudio() {
    if (!P) return;
    P.token++; P.playing = false; clearTimeout(P.timer);
    try { window.speechSynthesis && speechSynthesis.cancel(); } catch (e) {}
    try { P.lock && P.lock.release(); } catch (e) {}
  }
  function pickVoice() {
    var vs = window.speechSynthesis ? speechSynthesis.getVoices() : [];
    var pref = ['ur', 'hi', 'en-IN', 'en-GB', 'en'];
    for (var i = 0; i < pref.length; i++) {
      for (var j = 0; j < vs.length; j++) if (vs[j].lang.indexOf(pref[i]) === 0) return vs[j];
    }
    return vs[0] || null;
  }
  routes.lesson = function (id) {
    var l = lesson(id);
    if (!l) { location.hash = '#/home'; return; }
    var total = l.script.join('').length;
    P = { l: l, i: 0, playing: false, rate: 1, token: 0, heard: {}, voice: pickVoice(), timer: null };
    var unlocked = !!S.listened[id];
    var rate = 1;

    var pageHtml = l.image
      ? '<img src="' + esc(l.image) + '" alt="Textbook page ' + l.pageNumber + '">'
      : l.page.map(function (b) {
          return b.t === 'h' ? '<h3>' + esc(b.x) + '</h3>' : b.t === 'eq' ? '<div class="eq">' + esc(b.x) + '</div>' : '<p>' + esc(b.x) + '</p>';
        }).join('') + '<div class="pn">— ' + l.pageNumber + ' —</div>';

    app.innerHTML = banner() +
      '<a href="#/home" class="muted">← Back</a><h1>' + esc(l.subject + ' – ' + l.chapter) + '</h1>' +
      '<div class="muted">' + esc(l.title) + ' · Page ' + l.pageNumber + '</div>' +
      '<div class="card book" style="margin-top:10px">' + pageHtml + '</div>' +
      (l.image ? '' : '<div class="sample">Sample page written for the demo. Your textbook page appears here.</div>') +
      '<details class="transcript"><summary>Transcript</summary>' +
      l.script.map(function (s, k) { return '<div class="seg-line" id="sg' + k + '">' + esc(s) + '</div>'; }).join('') + '</details>' +
      '<div class="player" role="group" aria-label="Audio player">' +
      '<div class="bar" aria-hidden="true"><i id="pb"></i></div>' +
      '<div class="row between muted"><span id="pt">0%</span><span id="ps"></span></div>' +
      '<div class="controls">' +
      '<button id="pv" aria-label="Previous section">⏮</button>' +
      '<button id="pp" class="primary play" aria-label="Play">▶</button>' +
      '<button id="pn" aria-label="Next section">⏭</button>' +
      '<button id="pr" aria-label="Speed">1x</button></div>' +
      '<div class="row"><select id="vs" aria-label="Voice"></select></div>' +
      '<p class="muted" id="vh">Demo audio uses this device’s built-in voice. Final product uses pre-generated AI narration.</p>' +
      '<button class="primary" id="qz" style="width:100%" ' + (unlocked ? '' : 'disabled') + '>' + (unlocked ? 'Start quiz' : 'Quiz unlocks after you listen (90%)') + '</button>' +
      '<div style="text-align:center"><button class="link" id="ml">Mark as listened (demo shortcut)</button></div></div>';

    var pb = document.getElementById('pb'), pt = document.getElementById('pt'), pp = document.getElementById('pp');
    var hasTTS = 'speechSynthesis' in window;
    function heardChars() {
      var n = 0; for (var k in P.heard) n += l.script[k].length; return n;
    }
    function ui() {
      var pct = Math.min(100, Math.round(heardChars() / total * 100));
      pb.style.width = pct + '%'; pt.textContent = pct + '% heard';
      document.getElementById('ps').textContent = 'Section ' + Math.min(P.i + 1, l.script.length) + ' of ' + l.script.length;
      pp.textContent = P.playing ? '⏸' : '▶'; pp.setAttribute('aria-label', P.playing ? 'Pause' : 'Play');
      l.script.forEach(function (s, k) {
        var e = document.getElementById('sg' + k); if (e) e.className = 'seg-line' + (P.playing && k === P.i ? ' on' : '');
      });
      if (pct >= 90) unlock();
    }
    function unlock() {
      S.listened[id] = true; save();
      var q = document.getElementById('qz'); q.disabled = false; q.textContent = 'Start quiz';
    }
    function step() {
      if (!P.playing) return;
      if (P.i >= l.script.length) { P.playing = false; ui(); return; }
      var my = ++P.token, k = P.i;
      function next() { if (my !== P.token) return; P.heard[k] = true; P.i = k + 1; ui(); step(); }
      ui();
      if (!hasTTS || !P.voice) { P.timer = setTimeout(next, l.script[k].length * 55 / rate); return; }
      var u = new SpeechSynthesisUtterance(l.script[k]);
      u.voice = P.voice; u.lang = P.voice.lang; u.rate = rate;
      u.onend = next;
      u.onerror = function () { if (my === P.token) P.timer = setTimeout(next, 800); };
      speechSynthesis.speak(u);
    }
    function halt() { P.token++; P.playing = false; clearTimeout(P.timer); if (hasTTS) speechSynthesis.cancel(); ui(); }
    pp.onclick = function () {
      if (P.playing) { halt(); return; }
      if (P.i >= l.script.length) P.i = 0;
      P.playing = true;
      try { if (navigator.wakeLock) navigator.wakeLock.request('screen').then(function (w) { P.lock = w; }, function () {}); } catch (e) {}
      if (hasTTS) speechSynthesis.cancel();
      step();
    };
    function jump(d) {
      var was = P.playing; halt();
      P.i = Math.max(0, Math.min(l.script.length - 1, P.i + d)); ui();
      if (was) { P.playing = true; step(); }
    }
    document.getElementById('pv').onclick = function () { jump(-1); };
    document.getElementById('pn').onclick = function () { jump(1); };
    document.getElementById('pr').onclick = function () {
      rate = rate === 1 ? 1.25 : rate === 1.25 ? 1.5 : 1;
      this.textContent = rate + 'x';
      if (P.playing) { var was = P.playing; halt(); P.playing = was; step(); }
    };
    document.getElementById('ml').onclick = function () { unlock(); };
    document.getElementById('qz').onclick = function () { location.hash = '#/quiz/' + id; };

    var sel = document.getElementById('vs');
    function fillVoices() {
      var vs = hasTTS ? speechSynthesis.getVoices() : [];
      sel.innerHTML = vs.length ? vs.map(function (v, k) { return '<option value="' + k + '">' + esc(v.name + ' (' + v.lang + ')') + '</option>'; }).join('')
        : '<option>No voices found (simulated timing)</option>';
      P.voice = P.voice && vs.indexOf(P.voice) > -1 ? P.voice : pickVoice();
      var ix = vs.indexOf(P.voice); if (ix > -1) sel.value = ix;
    }
    sel.onchange = function () { var vs = speechSynthesis.getVoices(); P.voice = vs[+sel.value] || P.voice; };
    if (hasTTS) speechSynthesis.onvoiceschanged = fillVoices;
    fillVoices(); ui();
  };

  /* ---------- quiz ---------- */
  var Q = null;
  function shuffle(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  routes.quiz = function (id) {
    var l = lesson(id);
    if (!l) { location.hash = '#/home'; return; }
    if (!S.listened[id]) { location.hash = '#/lesson/' + id; return; }
    Q = { id: id, items: shuffle(l.quiz).slice(0, 5), i: 0, ans: [], sel: null };
    drawQ();
  };
  function drawQ() {
    var it = Q.items[Q.i], last = Q.i === Q.items.length - 1;
    app.innerHTML = banner() + '<div class="row between"><b>Question ' + (Q.i + 1) + ' of ' + Q.items.length + '</b><span class="muted">' + PASS + ' correct to pass</span></div>' +
      '<div class="bar" style="margin:8px 0 16px"><i style="width:' + (Q.i / Q.items.length * 100) + '%"></i></div>' +
      '<div class="card"><p style="margin-top:0"><b>' + esc(it.q) + '</b></p><div role="radiogroup" aria-label="Options">' +
      it.o.map(function (o, k) { return '<button class="opt" role="radio" aria-checked="false" data-k="' + k + '">' + esc(o) + '</button>'; }).join('') +
      '</div></div><button class="primary" id="nx" style="width:100%" disabled>' + (last ? 'Submit' : 'Next') + '</button>';
    var opts = app.querySelectorAll('.opt'), nx = document.getElementById('nx');
    Array.prototype.forEach.call(opts, function (b) {
      b.onclick = function () {
        Q.sel = +b.getAttribute('data-k');
        Array.prototype.forEach.call(opts, function (x) { x.setAttribute('aria-checked', x === b); });
        nx.disabled = false;
      };
    });
    nx.onclick = function () {
      Q.ans.push(Q.sel); Q.sel = null;
      if (last) finishQuiz(); else { Q.i++; drawQ(); }
    };
  }
  function finishQuiz() {
    var score = 0;
    Q.items.forEach(function (it, k) { if (Q.ans[k] === it.a) score++; });
    var pass = score >= PASS, c = S.clear[ME], attempts = 1;
    if (c) {
      c.attempts = (c.attempts || 0) + 1; attempts = c.attempts; c.score = score; c.last = Date.now();
      if (pass && !c.cleared && Q.id === MISSED) {
        c.cleared = true; c.by = 'quiz';
        var me = student(ME), l = lesson(MISSED);
        addMsg('Parent of ' + me.name + ' (' + me.parent + ')', 'Dear Parent, ' + me.name + ' has completed the missed lecture (' + l.subject + ' – ' + l.title + ') and passed the assessment (' + score + '/5). Cleared for class entry.');
        addMsg('Teacher (Mr. Tariq)', me.name + ' has completed the missed lecture and passed the assessment (' + score + '/5). Cleared for class entry.');
      }
    }
    save();
    Q.result = { score: score, pass: pass, attempts: attempts };
    location.hash = '#/result';
  }
  routes.result = function () {
    if (!Q || !Q.result) { location.hash = '#/home'; return; }
    var r = Q.result, id = Q.id;
    app.innerHTML = banner() + (r.pass
      ? '<div class="bigtick" aria-hidden="true">✔</div><h1 style="text-align:center">Great job, you passed!</h1><p style="text-align:center">You scored ' + r.score + '/5. ' +
        (S.clear[ME] && S.clear[ME].cleared ? '<span class="badge ok">Cleared for class</span><br><span class="muted">Your parent and teacher have been notified on WhatsApp.</span>' : '') + '</p>' +
        '<a href="#/home"><button class="primary" style="width:100%">Back to home</button></a>'
      : '<div class="bigsoft" aria-hidden="true">↻</div><h1 style="text-align:center">Almost there</h1><p style="text-align:center">You scored ' + r.score + '/5. You need ' + PASS + '/5 to pass. Let’s try again!' +
        (r.attempts >= 3 ? '<br><b>Tip:</b> please review the lesson once more before retrying.' : '') + '</p>' +
        '<a href="#/lesson/' + id + '"><button style="width:100%;margin-bottom:8px">Review lesson</button></a>' +
        '<a href="#/quiz/' + id + '"><button class="primary" style="width:100%">Retry quiz</button></a>');
  };

  /* ---------- teacher ---------- */
  routes.teacher = function () {
    if (S.role !== 'teacher') { location.hash = '#/home'; return; }
    var html = '<h1>11th Pre-Medical A</h1><div class="muted">' + new Date().toDateString() + ' · ' + esc(lesson(MISSED).subject) + ' period</div>';
    // clearance widget
    var pend = STUDENTS.filter(function (s) { return S.clear[s.id]; });
    if (S.submitted && pend.length) {
      html += '<h2>Class clearance</h2>';
      pend.forEach(function (s) {
        var c = S.clear[s.id];
        html += '<div class="card"><div class="row between"><b>' + esc(s.name) + '</b>' +
          (c.cleared ? '<span class="badge ok">✔ Cleared</span>' : '<span class="badge pend">✖ Pending</span>') + '</div>' +
          '<div class="muted">' + (c.last ? 'Last attempt ' + hm(c.last) + ' · score ' + c.score + '/5 · attempts ' + c.attempts
            : 'No attempt yet') + (c.by === 'teacher' ? ' · cleared by teacher' : '') + '</div>' +
          (c.cleared ? '' : '<button class="sm" data-ov="' + s.id + '" style="margin-top:8px">Clear manually (teacher override)</button>') + '</div>';
      });
      html += '<p class="muted">Refresh happens automatically when the student passes in this same browser.</p>';
    }
    html += '<h2>Attendance</h2><div class="card">';
    STUDENTS.forEach(function (s) {
      var st = S.att[s.id] || 'present';
      html += '<div class="att" style="padding:6px 0"><div class="name"><b>' + esc(s.name) + '</b><div class="muted">' + s.roll + '</div></div>' +
        '<button class="p" data-a="' + s.id + '" data-v="present" aria-pressed="' + (st === 'present') + '">Present</button>' +
        '<button class="a" data-a="' + s.id + '" data-v="absent" aria-pressed="' + (st === 'absent') + '">Absent</button></div>';
    });
    html += '</div><div class="row"><button class="grow" id="allp">Mark all present</button><button class="primary grow" id="sub">Submit attendance</button></div>';
    app.innerHTML = html;

    Array.prototype.forEach.call(app.querySelectorAll('[data-a]'), function (b) {
      b.onclick = function () { S.att[b.getAttribute('data-a')] = b.getAttribute('data-v'); save(); routes.teacher(); };
    });
    document.getElementById('allp').onclick = function () { S.att = {}; save(); routes.teacher(); };
    document.getElementById('sub').onclick = function () {
      var l = lesson(MISSED), n = 0;
      STUDENTS.forEach(function (s) {
        if (S.att[s.id] === 'absent') {
          if (!S.clear[s.id]) {
            S.clear[s.id] = { cleared: false, attempts: 0 }; n++;
            addMsg('Parent of ' + s.name + ' (' + s.parent + ')', 'Dear Parent, ' + s.name + ' was marked absent today. Missed lecture: ' + l.subject + ' – ' + l.title +
              '. Please ensure he completes the digital backup lecture: https://demo.edusaas.example/l/' + l.id);
          }
        } else if (S.clear[s.id] && !S.clear[s.id].cleared) delete S.clear[s.id];
      });
      S.submitted = true; save(); routes.teacher();
      alert(n ? n + ' WhatsApp alert(s) sent. See the WhatsApp log tab.' : 'Attendance saved.');
    };
    Array.prototype.forEach.call(app.querySelectorAll('[data-ov]'), function (b) {
      b.onclick = function () {
        var s = student(b.getAttribute('data-ov')), c = S.clear[s.id];
        c.cleared = true; c.by = 'teacher';
        addMsg('Parent of ' + s.name + ' (' + s.parent + ')', 'Dear Parent, ' + s.name + ' has been cleared for class entry by the teacher.');
        save(); routes.teacher();
      };
    });
  };

  /* ---------- WhatsApp log ---------- */
  routes.msgs = function () {
    var html = '<h1>' + (S.role === 'teacher' ? 'WhatsApp log' : 'Parent’s WhatsApp') + '</h1><div class="banner demo">Simulated. In the real product these are sent through the WhatsApp Business API, with SMS as a fallback.</div><div class="chat">';
    if (!S.msgs.length) html += '<p class="muted" style="padding:8px">No messages yet. Mark a student absent as the teacher to trigger one.</p>';
    S.msgs.forEach(function (m) {
      var text = esc(m.text).replace(/(https?:\/\/[^\s]+)/g, '<a href="#/lesson/' + MISSED + '">$1</a>');
      html += '<div class="bubble"><div class="meta">To: ' + esc(m.to) + ' · ' + hm(m.t) + ' · ✓✓ Delivered</div>' + text + '</div>';
    });
    app.innerHTML = html + '</div>';
  };

  syncTools();
  if (!location.hash) location.hash = '#/login';
  route();
})();

