169	.segbar { display: flex; gap: 3px; height: 10px; align-items: center; }
170	.segbar button { flex: 1; height: 8px; min-height: 0; padding: 0; border: 0; border-radius: 3px; background: var(--sunk); }
171	.segbar button.heard { background: var(--accent); }
172	.segbar button.on { background: var(--primary); height: 10px; }
173	.player .times { display: flex; justify-content: space-between; font-size: 12px; color: var(--muted); margin-top: 4px; }
174	.player .controls { display: flex; gap: 6px; align-items: center; justify-content: center; margin: 6px 0 8px; }
175	.player .controls button { min-width: 48px; padding: 0 10px; border-color: transparent; background: transparent; }
176	.player .controls .play { width: 56px; height: 56px; border-radius: 50%; background: var(--primary); color: var(--on-primary); }
177	.player .controls .rate { font-size: 14px; border: 1px solid var(--border); min-width: 56px; }
178	.player .controls .voice { max-width: 44px; }
179	
180	/* ---------- quiz ---------- */
181	.qhead { display: flex; justify-content: space-between; align-items: center; font-size: 14px; color: var(--muted); }
182	.qtext { font-size: 18px; font-weight: 600; margin: 4px 0 12px; }
183	.opt { display: flex; width: 100%; text-align: left; justify-content: flex-start; gap: 12px; margin: 8px 0; font-weight: 500; padding: 10px 12px; }
184	.opt .k { display: grid; place-items: center; width: 30px; height: 30px; flex: none; border-radius: 8px; background: var(--sunk); color: var(--muted); font-weight: 700; font-size: 14px; }
185	.opt[aria-checked=true] { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
186	.opt[aria-checked=true] .k { background: var(--primary); color: var(--on-primary); }
187	.result { text-align: center; padding: 18px 8px 6px; }
188	.result .icon { width: 84px; height: 84px; margin: 0 auto 8px; border-radius: 50%; display: grid; place-items: center; }
189	.result .icon svg { width: 48px; height: 48px; stroke-width: 3; }
190	.result.pass .icon { background: var(--ok-bg); color: var(--ok); }
191	.result.fail .icon { background: var(--warn-bg); color: var(--warn); }
192	.score { font-size: 34px; font-weight: 800; }
193	.review { border-left: 4px solid var(--border); }
194	.review.right { border-left-color: var(--ok); }
195	.review.wrong { border-left-color: var(--warn); }
196	.review .ans { font-size: 14px; margin-top: 4px; }
197	.confetti { position: fixed; inset: 0; pointer-events: none; z-index: 40; overflow: hidden; }
198	.confetti i { position: absolute; top: -12px; width: 8px; height: 12px; border-radius: 2px; animation: fall 1.6s ease-in forwards; }
199	@keyframes fall { to { transform: translateY(105vh) rotate(540deg); opacity: .7; } }
200	@media (prefers-reduced-motion: reduce) { .confetti { display: none; } }
201	
202	/* ---------- teacher ---------- */
203	.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 12px 0; }
204	.stat { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 10px; }
205	.stat b { display: block; font-size: 24px; line-height: 1.2; }
206	.stat span { font-size: 12px; color: var(--muted); }
207	.stat.warn b { color: var(--warn); }
208	.stat.ok b { color: var(--ok); }
209	.att { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--border); }
210	.att:last-child { border-bottom: 0; }
211	.avatar { width: 40px; height: 40px; border-radius: 50%; flex: none; display: grid; place-items: center; background: var(--sunk); color: var(--muted); font-weight: 700; font-size: 14px; }
212	.pa { display: flex; gap: 4px; }
213	.pa button { min-width: 48px; min-height: 44px; padding: 0 10px; font-size: 14px; }
214	.pa button[aria-pressed=true].p { background: var(--ok); color: #fff; border-color: var(--ok); }
215	.pa button[aria-pressed=true].a { background: var(--bad); color: #fff; border-color: var(--bad); }
216	.sticky-actions { position: sticky; bottom: 72px; display: flex; gap: 8px; padding: 8px 0; background: var(--bg); }
217	
218	/* ---------- WhatsApp ---------- */
219	.wa { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; background: var(--card); }
220	.wa .head { display: flex; gap: 10px; align-items: center; padding: 10px 12px; background: var(--wa-head); color: #fff; }
221	.wa .head .avatar { background: rgba(255,255,255,.2); color: #fff; }
222	.wa .body { padding: 10px; background: var(--sunk); min-height: 160px; }
223	.bubble { background: var(--wa); color: var(--text); border-radius: 12px 12px 12px 3px; padding: 8px 12px 6px; margin: 8px 0; max-width: 92%; border: 1px solid var(--border); }
224	.bubble .to { font-size: 12px; color: var(--accent); font-weight: 700; }
225	.bubble .foot { font-size: 11px; color: var(--muted); text-align: right; }
226	.bubble .cta { display: flex; margin: 8px -12px 0; padding-top: 6px; border-top: 1px solid var(--border); justify-content: center; }
227	.bubble .cta a { display: inline-flex; gap: 6px; align-items: center; min-height: 40px; font-weight: 600; color: var(--accent); text-decoration: none; }
228	
229	/* ---------- nav + toast ---------- */
230	nav.bottom {
231	  position: fixed; left: 0; right: 0; bottom: 0; z-index: 16; display: flex; background: var(--card);
232	  border-top: 1px solid var(--border); height: 64px;
233	}
234	nav.bottom a {
235	  flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
236	  color: var(--muted); text-decoration: none; font-weight: 600; font-size: 12px; position: relative;
237	}
238	nav.bottom a[aria-current=page] { color: var(--primary); }
239	nav.bottom a[aria-current=page]::before { content: ""; position: absolute; top: 0; left: 25%; right: 25%; height: 3px; border-radius: 0 0 3px 3px; background: var(--primary); }
240	nav.bottom .dot { position: absolute; top: 8px; left: calc(50% + 8px); width: 9px; height: 9px; border-radius: 50%; background: var(--bad); }
241	.toast {
242	  position: fixed; left: 50%; bottom: 84px; transform: translateX(-50%); z-index: 60; max-width: calc(100% - 32px);
243	  background: var(--text); color: var(--bg); padding: 12px 16px; border-radius: 10px; font-size: 14px; font-weight: 500;
244	}
245	@media (min-width: 720px) {
246	  h1 { font-size: 26px; }
247	}
248	.player .controls .skip { font-size: 13px; font-weight: 700; min-width: 48px; color: var(--muted); }
249	
250	/* ---------- multi-user demo additions ---------- */
251	.mark.big { width: 56px; height: 56px; border-radius: 16px; background: var(--primary); color: var(--on-primary); display: inline-grid; place-items: center; }
252	.err { color: var(--bad); min-height: 1.2em; margin: 8px 0; }
253	.acc { display: flex; width: 100%; justify-content: space-between; align-items: center; gap: 8px; text-align: left; font-weight: 500;
254	  min-height: 48px; padding: 8px 10px; margin: 4px 0; font-size: 14px; }
255	.acc code { font-size: 12px; color: var(--muted); white-space: nowrap; }
256	details.card summary { cursor: pointer; min-height: 32px; display: flex; align-items: center; }
257	.sms-preview { position: fixed; top: 64px; left: 50%; transform: translateX(-50%); z-index: 70; width: min(380px, calc(100% - 32px));
258	  display: flex; gap: 10px; align-items: flex-start; background: var(--card); color: var(--text); border: 1px solid var(--border);
259	  border-left: 4px solid var(--accent); border-radius: 12px; padding: 12px 14px; font-size: 14px; }
260	.skeleton-row { display: grid; gap: 10px; }
261	.skeleton-row i { display: block; height: 12px; border-radius: 6px; background: var(--sunk); animation: pulse 1.2s ease-in-out infinite; }
262	.bubble.failed { background: var(--bad-bg); }
263	button.inline { min-height: 32px; min-width: 32px; padding: 0 6px; vertical-align: middle; }
264	.attstrip { display: flex; gap: 6px; margin-top: 12px; flex-wrap: wrap; }
265	.attstrip span { min-width: 44px; text-align: center; font-size: 12px; padding: 4px 6px; border-radius: 8px; background: var(--ok-bg); color: var(--ok); font-weight: 600; line-height: 1.3; }
266	.attstrip span.absent { background: var(--bad-bg); color: var(--bad); }
267	@media (prefers-reduced-motion: reduce) { .skeleton-row i { animation: none; } }
268	.toast { pointer-events: none; }
269	body.has-player .toast { bottom: 250px; }
