file.content:
/* Brand tokens follow blueprint 4.3: deep navy primary, emerald accent, amber for pending,
   off-white / charcoal backgrounds, flat surfaces with 1px borders. */
:root {
  --bg: #f5f6f9; --card: #ffffff; --sunk: #eef0f5; --text: #1b2130; --muted: #5a6478; --border: #dde1ea;
  --primary: #1e3a5f; --primary-2: #2c5282; --on-primary: #ffffff;
  --accent: #0f8f83; --accent-bg: #e3f4f2;
  --ok: #047857; --ok-bg: #e3f5ec; --warn: #a55a06; --warn-bg: #fff3dc; --bad: #b42318; --bad-bg: #fdecea;
  --wa: #e7fbe0; --wa-head: #075e54; --page: #ffffff;
  --radius: 12px;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #171a21; --card: #21252e; --sunk: #1b1f27; --text: #eceef3; --muted: #a3abbb; --border: #353b47;
    --primary: #7aa7e8; --primary-2: #9bbdf0; --on-primary: #0e1522;
    --accent: #3cc9b8; --accent-bg: #143532;
    --ok: #4ade9b; --ok-bg: #133526; --warn: #f5b94a; --warn-bg: #3a2c0f; --bad: #f58a80; --bad-bg: #3d1f1d;
    --wa: #1f3a2c; --wa-head: #1f2c33; --page: #d9d9d6;
  }
}
:root[data-theme="dark"] {
  --bg: #171a21; --card: #21252e; --sunk: #1b1f27; --text: #eceef3; --muted: #a3abbb; --border: #353b47;
  --primary: #7aa7e8; --primary-2: #9bbdf0; --on-primary: #0e1522;
  --accent: #3cc9b8; --accent-bg: #143532;
  --ok: #4ade9b; --ok-bg: #133526; --warn: #f5b94a; --warn-bg: #3a2c0f; --bad: #f58a80; --bad-bg: #3d1f1d;
  --wa: #1f3a2c; --wa-head: #1f2c33; --page: #d9d9d6;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 16px/1.5 Inter, Roboto, system-ui, -apple-system, "Segoe UI", sans-serif;
}
a { color: var(--primary); }
svg.i { width: 22px; height: 22px; flex: none; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; vertical-align: middle; }
svg.i.sm { width: 18px; height: 18px; }
[hidden] { display: none !important; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* ---------- header ---------- */
header.top {
  position: sticky; top: 0; z-index: 20; display: flex; align-items: center; gap: 10px;
  padding: 8px 12px 8px 16px; background: var(--card); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 17px; color: var(--text); text-decoration: none; margin-right: auto; }
.brand .mark { width: 32px; height: 32px; border-radius: 9px; background: var(--primary); color: var(--on-primary); display: grid; place-items: center; }
.brand small { font-weight: 500; color: var(--muted); font-size: 12px; border: 1px solid var(--border); border-radius: 6px; padding: 0 6px; }
.iconbtn {
  width: 44px; height: 44px; display: grid; place-items: center; border-radius: 10px;
  border: 1px solid transparent; background: transparent; color: var(--muted); cursor: pointer; padding: 0;
}
.iconbtn:hover { background: var(--sunk); color: var(--text); }
.iconbtn[aria-pressed="true"] { background: var(--warn-bg); color: var(--warn); border-color: var(--warn); }

main { max-width: 680px; margin: 0 auto; padding: 16px 16px 96px; }
body.has-player main { padding-bottom: 230px; }
h1 { font-size: 22px; line-height: 1.25; margin: 4px 0 4px; }
h2 { font-size: 15px; margin: 22px 0 8px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; font-weight: 700; }
.muted { color: var(--muted); font-size: 14px; }
.small { font-size: 13px; }

/* ---------- surfaces ---------- */
.card { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px; margin: 10px 0; }
.card.tight { padding: 10px 12px; }
a.card { display: block; color: inherit; text-decoration: none; }
a.card:hover { border-color: var(--primary); }
.row { display: flex; gap: 10px; align-items: center; }
.row.between { justify-content: space-between; }
.row.wrap { flex-wrap: wrap; }
.grow { flex: 1; min-width: 0; }
.stack > * + * { margin-top: 8px; }

.banner { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border-radius: 10px; margin: 0 0 12px; font-size: 14px; }
.banner.off { background: var(--warn-bg); color: var(--warn); border: 1px solid var(--warn); }
.banner.info { background: var(--sunk); color: var(--muted); border: 1px dashed var(--border); }

/* ---------- buttons ---------- */
button, .btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 10px 18px; font: inherit; font-weight: 600; text-decoration: none;
  border-radius: 10px; border: 1px solid var(--border); background: var(--card); color: var(--text); cursor: pointer;
}
.btn.primary, button.primary { background: var(--primary); color: var(--on-primary); border-color: var(--primary); }
.btn.accent, button.accent { background: var(--accent); color: #fff; border-color: var(--accent); }
.btn.block, button.block { width: 100%; }
button.sm, .btn.sm { min-height: 40px; padding: 6px 12px; font-size: 14px; }
button.ghost { background: transparent; border-color: transparent; color: var(--muted); font-weight: 500; }
button:disabled { opacity: .5; cursor: not-allowed; }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

input[type=text], input[type=tel], select {
  width: 100%; min-height: 48px; padding: 8px 12px; font: inherit; border-radius: 10px;
  border: 1px solid var(--border); background: var(--card); color: var(--text);
}
label.field { display: block; font-weight: 600; font-size: 14px; margin: 14px 0 6px; }
.phone { display: flex; border: 1px solid var(--border); border-radius: 10px; background: var(--card); overflow: hidden; }
.phone span { display: grid; place-items: center; padding: 0 12px; background: var(--sunk); color: var(--muted); font-weight: 600; border-right: 1px solid var(--border); }
.phone input { border: 0; border-radius: 0; }
input.otp { font-size: 26px; letter-spacing: 14px; text-align: center; font-weight: 700; }

.seg { display: flex; padding: 4px; gap: 4px; background: var(--sunk); border-radius: 12px; border: 1px solid var(--border); }
.seg button { flex: 1; border: 0; background: transparent; min-height: 44px; color: var(--muted); }
.seg button[aria-pressed=true] { background: var(--card); color: var(--text); box-shadow: 0 0 0 1px var(--border); }

/* ---------- badges, bars, rings ---------- */
.badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: 999px; font-size: 13px; font-weight: 600; white-space: nowrap; }
.badge.ok { background: var(--ok-bg); color: var(--ok); }
.badge.pend { background: var(--bad-bg); color: var(--bad); }
.badge.warn { background: var(--warn-bg); color: var(--warn); }
.badge.neutral { background: var(--sunk); color: var(--muted); }
.chip { display: inline-grid; place-items: center; min-width: 44px; height: 44px; border-radius: 10px; background: var(--accent-bg); color: var(--accent); font-weight: 700; font-size: 15px; }
.bar { height: 6px; background: var(--sunk); border-radius: 4px; overflow: hidden; }
.bar > i { display: block; height: 100%; width: 0; background: var(--accent); transition: width .3s; }
.ring { width: 64px; height: 64px; flex: none; }
.ring circle { fill: none; stroke-width: 7; }
.ring .t { stroke: var(--sunk); }
.ring .v { stroke: var(--accent); stroke-linecap: round; transform: rotate(-90deg); transform-origin: 50% 50%; }
.ring text { fill: var(--text); font-size: 15px; font-weight: 700; text-anchor: middle; dominant-baseline: central; }

/* ---------- home ---------- */
.hero { display: flex; align-items: center; gap: 14px; }
.alert-card { border-color: var(--warn); background: var(--warn-bg); }
.alert-card .title { display: flex; gap: 8px; align-items: center; color: var(--warn); font-weight: 700; }
.ok-card { border-color: var(--ok); background: var(--ok-bg); }
.lesson-row { display: flex; gap: 12px; align-items: center; }
.meta { display: flex; gap: 12px; flex-wrap: wrap; color: var(--muted); font-size: 13px; margin-top: 2px; }
.meta span { display: inline-flex; align-items: center; gap: 4px; }
.locked { opacity: .6; }

/* ---------- lesson viewer ---------- */
.crumbs { display: flex; gap: 6px; align-items: center; color: var(--muted); font-size: 14px; }
.crumbs a { color: var(--muted); text-decoration: none; display: inline-flex; align-items: center; min-height: 40px; }
.pagetabs { display: flex; gap: 6px; align-items: center; margin: 12px 0 8px; flex-wrap: wrap; }
.pagetabs button { min-height: 40px; padding: 4px 12px; font-size: 14px; }
.pagetabs button[aria-current=true] { background: var(--primary); color: var(--on-primary); border-color: var(--primary); }
.pagetabs .follow { margin-left: auto; font-size: 13px; color: var(--muted); display: flex; gap: 6px; align-items: center; }
.pagetabs .follow input { width: 20px; height: 20px; accent-color: var(--accent); }
.pageframe {
  position: relative; background: var(--page); border: 1px solid var(--border); border-radius: 10px; overflow: hidden;
  aspect-ratio: 595 / 759; cursor: zoom-in;
}
.pageframe img { width: 100%; height: 100%; object-fit: contain; display: block; opacity: 0; transition: opacity .25s; }
.pageframe img.ready { opacity: 1; }
.pageframe .zoomhint { position: absolute; right: 8px; bottom: 8px; background: rgba(20,26,38,.75); color: #fff; border-radius: 8px; padding: 4px 8px; font-size: 12px; display: flex; gap: 4px; align-items: center; }
.skeleton { position: absolute; inset: 0; padding: 20px; display: grid; gap: 10px; align-content: start; }
.skeleton i { display: block; height: 12px; border-radius: 6px; background: var(--sunk); animation: pulse 1.2s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) { .skeleton i { animation: none; } .bar > i { transition: none; } }
.caption { border-left: 4px solid var(--accent); background: var(--card); border-radius: 0 10px 10px 0; padding: 10px 12px; margin: 12px 0; font-size: 15px; }
.caption .lbl { font-size: 12px; color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; margin-bottom: 2px; }
details.transcript { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 0 12px; }
details.transcript summary { cursor: pointer; min-height: 48px; display: flex; align-items: center; font-weight: 600; }
.seg-line { display: block; width: 100%; text-align: left; font-weight: 400; border: 0; border-radius: 8px; padding: 8px; min-height: 0; background: none; color: var(--text); font-size: 15px; }
.seg-line.on { background: var(--accent-bg); }
.seg-line.heard { color: var(--muted); }

/* zoom overlay */
.zoom { position: fixed; inset: 0; z-index: 50; background: rgba(10,12,18,.94); display: flex; flex-direction: column; }
.zoom .zbar { display: flex; gap: 8px; padding: 8px; justify-content: flex-end; }
.zoom .zbar button { background: rgba(255,255,255,.12); color: #fff; border-color: transparent; min-width: 48px; }
.zoom .zbody { flex: 1; overflow: auto; -webkit-overflow-scrolling: touch; touch-action: pan-x pan-y pinch-zoom; }
.zoom img { display: block; margin: 0 auto; background: #fff; }

/* docked player */
.player {
  position: fixed; left: 0; right: 0; bottom: 64px; z-index: 15; background: var(--card); border-top: 1px solid var(--border);
}
.player .in { max-width: 680px; margin: 0 auto; padding: 10px 16px 12px; }
.segbar { display: flex; gap: 3px; height: 10px; align-items: center; }
.segbar button { flex: 1; height: 8px; min-height: 0; padding: 0; border: 0; border-radius: 3px; background: var(--sunk); }
.segbar button.heard { background: var(--accent); }
.segbar button.on { background: var(--primary); height: 10px; }
.player .times { display: flex; justify-content: space-between; font-size: 12px; color: var(--muted); margin-top: 4px; }
.player .controls { display: flex; gap: 6px; align-items: center; justify-content: center; margin: 6px 0 8px; }
.player .controls button { min-width: 48px; padding: 0 10px; border-color: transparent; background: transparent; }
.player .controls .play { width: 56px; height: 56px; border-radius: 50%; background: var(--primary); color: var(--on-primary); }
.player .controls .rate { font-size: 14px; border: 1px solid var(--border); min-width: 56px; }
.player .controls .voice { max-width: 44px; }

/* ---------- quiz ---------- */
.qhead { display: flex; justify-content: space-between; align-items: center; font-size: 14px; color: var(--muted); }
.qtext { font-size: 18px; font-weight: 600; margin: 4px 0 12px; }
.opt { display: flex; width: 100%; text-align: left; justify-content: flex-start; gap: 12px; margin: 8px 0; font-weight: 500; padding: 10px 12px; }
.opt .k { display: grid; place-items: center; width: 30px; height: 30px; flex: none; border-radius: 8px; background: var(--sunk); color: var(--muted); font-weight: 700; font-size: 14px; }
.opt[aria-checked=true] { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
.opt[aria-checked=true] .k { background: var(--primary); color: var(--on-primary); }
.result { text-align: center; padding: 18px 8px 6px; }
.result .icon { width: 84px; height: 84px; margin: 0 auto 8px; border-radius: 50%; display: grid; place-items: center; }
.result .icon svg { width: 48px; height: 48px; stroke-width: 3; }
.result.pass .icon { background: var(--ok-bg); color: var(--ok); }
.result.fail .icon { background: var(--warn-bg); color: var(--warn); }
.score { font-size: 34px; font-weight: 800; }
.review { border-left: 4px solid var(--border); }
.review.right { border-left-color: var(--ok); }
.review.wrong { border-left-color: var(--warn); }
.review .ans { font-size: 14px; margin-top: 4px; }
.confetti { position: fixed; inset: 0; pointer-events: none; z-index: 40; overflow: hidden; }
.confetti i { position: absolute; top: -12px; width: 8px; height: 12px; border-radius: 2px; animation: fall 1.6s ease-in forwards; }
@keyframes fall { to { transform: translateY(105vh) rotate(540deg); opacity: .7; } }
@media (prefers-reduced-motion: reduce) { .confetti { display: none; } }

/* ---------- teacher ---------- */
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 12px 0; }
.stat { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 10px; }
.stat b { display: block; font-size: 24px; line-height: 1.2; }
.stat span { font-size: 12px; color: var(--muted); }
.stat.warn b { color: var(--warn); }
.stat.ok b { color: var(--ok); }
.att { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--border); }
.att:last-child { border-bottom: 0; }
.avatar { width: 40px; height: 40px; border-radius: 50%; flex: none; display: grid; place-items: center; background: var(--sunk); color: var(--muted); font-weight: 700; font-size: 14px; }
.pa { display: flex; gap: 4px; }
.pa button { min-width: 48px; min-height: 44px; padding: 0 10px; font-size: 14px; }
.pa button[aria-pressed=true].p { background: var(--ok); color: #fff; border-color: var(--ok); }
.pa button[aria-pressed=true].a { background: var(--bad); color: #fff; border-color: var(--bad); }
.sticky-actions { position: sticky; bottom: 72px; display: flex; gap: 8px; padding: 8px 0; background: var(--bg); }

/* ---------- WhatsApp ---------- */
.wa { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; background: var(--card); }
.wa .head { display: flex; gap: 10px; align-items: center; padding: 10px 12px; background: var(--wa-head); color: #fff; }
.wa .head .avatar { background: rgba(255,255,255,.2); color: #fff; }
.wa .body { padding: 10px; background: var(--sunk); min-height: 160px; }
.bubble { background: var(--wa); color: var(--text); border-radius: 12px 12px 12px 3px; padding: 8px 12px 6px; margin: 8px 0; max-width: 92%; border: 1px solid var(--border); }
.bubble .to { font-size: 12px; color: var(--accent); font-weight: 700; }
.bubble .foot { font-size: 11px; color: var(--muted); text-align: right; }
.bubble .cta { display: flex; margin: 8px -12px 0; padding-top: 6px; border-top: 1px solid var(--border); justify-content: center; }
.bubble .cta a { display: inline-flex; gap: 6px; align-items: center; min-height: 40px; font-weight: 600; color: var(--accent); text-decoration: none; }

/* ---------- nav + toast ---------- */
nav.bottom {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 16; display: flex; background: var(--card);
  border-top: 1px solid var(--border); height: 64px;
}
nav.bottom a {
  flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  color: var(--muted); text-decoration: none; font-weight: 600; font-size: 12px; position: relative;
}
nav.bottom a[aria-current=page] { color: var(--primary); }
nav.bottom a[aria-current=page]::before { content: ""; position: absolute; top: 0; left: 25%; right: 25%; height: 3px; border-radius: 0 0 3px 3px; background: var(--primary); }
nav.bottom .dot { position: absolute; top: 8px; left: calc(50% + 8px); width: 9px; height: 9px; border-radius: 50%; background: var(--bad); }
.toast {
  position: fixed; left: 50%; bottom: 84px; transform: translateX(-50%); z-index: 60; max-width: calc(100% - 32px);
  background: var(--text); color: var(--bg); padding: 12px 16px; border-radius: 10px; font-size: 14px; font-weight: 500;
}
@media (min-width: 720px) {
  h1 { font-size: 26px; }
}
.player .controls .skip { font-size: 13px; font-weight: 700; min-width: 48px; color: var(--muted); }

/* ---------- multi-user demo additions ---------- */
.mark.big { width: 56px; height: 56px; border-radius: 16px; background: var(--primary); color: var(--on-primary); display: inline-grid; place-items: center; }
.err { color: var(--bad); min-height: 1.2em; margin: 8px 0; }
.acc { display: flex; width: 100%; justify-content: space-between; align-items: center; gap: 8px; text-align: left; font-weight: 500;
  min-height: 48px; padding: 8px 10px; margin: 4px 0; font-size: 14px; }
.acc code { font-size: 12px; color: var(--muted); white-space: nowrap; }
details.card summary { cursor: pointer; min-height: 32px; display: flex; align-items: center; }
.sms-preview { position: fixed; top: 64px; left: 50%; transform: translateX(-50%); z-index: 70; width: min(380px, calc(100% - 32px));
  display: flex; gap: 10px; align-items: flex-start; background: var(--card); color: var(--text); border: 1px solid var(--border);
  border-left: 4px solid var(--accent); border-radius: 12px; padding: 12px 14px; font-size: 14px; }
.skeleton-row { display: grid; gap: 10px; }
.skeleton-row i { display: block; height: 12px; border-radius: 6px; background: var(--sunk); animation: pulse 1.2s ease-in-out infinite; }
.bubble.failed { background: var(--bad-bg); }
button.inline { min-height: 32px; min-width: 32px; padding: 0 6px; vertical-align: middle; }
.attstrip { display: flex; gap: 6px; margin-top: 12px; flex-wrap: wrap; }
.attstrip span { min-width: 44px; text-align: center; font-size: 12px; padding: 4px 6px; border-radius: 8px; background: var(--ok-bg); color: var(--ok); font-weight: 600; line-height: 1.3; }
.attstrip span.absent { background: var(--bad-bg); color: var(--bad); }
@media (prefers-reduced-motion: reduce) { .skeleton-row i { animation: none; } }
.toast { pointer-events: none; }
body.has-player .toast { bottom: 250px; }

