538	      : '<div class="result fail"><div class="icon">' + icon('refresh') + '</div><div class="score">' + r.score + '/' + r.size + '</div><h1>Almost there!</h1>' +
539	        '<p class="muted">You need ' + r.passMark + '/' + r.size + ' to pass. Review the lesson, then try again in ' + r.retryAfter + ' seconds.' +
540	        (r.attempts >= 3 ? '<br><b>Tip:</b> listen to the lesson once more before your next try.' : '') + '</p></div>' +
541	        '<div class="row"><a class="btn grow" href="#/lesson/' + esc(id) + '">Review lesson</a><a class="btn primary grow" href="#/quiz/' + esc(id) + '">Try again</a></div>') + review;
542	    window.scrollTo(0, 0);
543	    if (r.passed) confetti();
544	  }
545	
546	  /* ---------- teacher ---------- */
547	  var autoOpened = false;
548	  routes.teacher = function () {
549	    app.innerHTML = skeleton(2);
550	    get('teacher/assignments').then(function (list) {
551	      if (list.length === 1 && !autoOpened) { autoOpened = true; location.hash = '#/class/' + list[0].id; return; }
552	      app.innerHTML = banner() + '<p class="muted" style="margin:0">' + todayLong() + '</p><h1>' + esc(ME.name) + '</h1><p class="muted">' + esc(ME.college) + '</p><h2>My classes</h2>' +
553	        (list.length ? list.map(function (a) {
554	          return '<a class="card" href="#/class/' + a.id + '"><div class="lesson-row"><span class="avatar">' + esc(a.subject.slice(0, 2)) + '</span><div class="grow"><b>' +
555	            esc(a.class) + '</b><div class="meta"><span>' + esc(a.subject) + '</span><span>' + a.students + ' students</span></div></div></div></a>';
556	        }).join('') : '<div class="card muted">You are not assigned to any class yet. Please contact the college admin.</div>');
557	    }, function (e) { app.innerHTML = errorCard(e); });
558	  };
559	  routes.class = function (aid) {
560	    app.innerHTML = skeleton(3);
561	    get('teacher/assignments/' + encodeURIComponent(aid)).then(function (d) { renderClass(aid, d); }, function (e) {
562	      app.innerHTML = '<a class="crumbs" href="#/teacher">' + icon('back', 'sm') + 'My classes</a>' + errorCard(e);
563	    });
564	  };
565	  function renderClass(aid, d) {
566	    var marks = {}, topic = d.topic || (d.lessons[0] && d.lessons[0].id);
567	    d.students.forEach(function (s) { marks[s.id] = s.status || 'present'; });
568	    function draw() {
569	      var absent = d.students.filter(function (s) { return marks[s.id] === 'absent'; }).length;
570	      var pending = d.clearances.filter(function (c) { return c.status === 'pending'; });
571	      var html = banner() + '<div class="crumbs"><a href="#/teacher">' + icon('back', 'sm') + 'My classes</a></div>' +
572	        '<p class="muted" style="margin:0">' + todayLong() + ' · ' + esc(d.assignment.subject) + '</p><h1>' + esc(d.assignment.class) + '</h1>' +
573	        '<div class="stats"><div class="stat ok"><b>' + (d.students.length - absent) + '</b><span>Present</span></div><div class="stat"><b>' + absent + '</b><span>Absent</span></div>' +
574	        '<div class="stat' + (pending.length ? ' warn' : '') + '"><b>' + pending.length + '</b><span>Pending</span></div></div>';
575	      if (d.clearances.length) {
576	        html += '<h2>Class clearance</h2>' + d.clearances.map(function (c) {
577	          var ok = c.status === 'cleared';
578	          return '<div class="card tight"><div class="row"><span class="avatar">' + esc(initials(c.student)) + '</span><div class="grow"><b>' + esc(c.student) + '</b>' +
579	            '<div class="muted small">' + esc(c.lesson.topic + ' ' + c.lesson.title) + ' · absent ' + dayName(c.date) + '</div><div class="muted small">' +
580	            (ok ? (c.clearedBy === 'teacher' ? 'Cleared by teacher: ' + esc(c.overrideReason) : 'Passed ' + c.best + '/5, ' + when(c.clearedAt))
581	              : (c.lastAttempt ? 'Last attempt ' + when(c.lastAttempt) + ' · best ' + c.best + '/5 · ' + c.attempts + ' attempt' + (c.attempts > 1 ? 's' : '') : 'Not started yet')) +
582	            '</div></div>' + (ok ? '<span class="badge ok">' + icon('check', 'sm') + 'Cleared</span>' : '<span class="badge pend">' + icon('cross', 'sm') + 'Pending</span>') + '</div>' +
583	            (ok ? '' : '<div style="text-align:right"><button class="ghost sm" data-ov="' + c.id + '">Clear manually…</button></div>') + '</div>';
584	        }).join('');
585	      }
586	      html += '<h2>' + (d.submitted ? 'Today’s attendance (submitted)' : 'Take attendance') + '</h2>' +
587	        '<label class="field" for="tp" style="margin-top:0">Topic taught today</label><select id="tp">' + d.lessons.map(function (l) {
588	          return '<option value="' + esc(l.id) + '"' + (topic === l.id ? ' selected' : '') + '>' + esc(l.topic + ' ' + l.title) + '</option>';
589	        }).join('') + '</select><p class="muted small">Absent students get this topic as their missed lecture, and their parents get a WhatsApp alert.</p>' +
590	        '<div class="card" style="padding:4px 12px">' + d.students.map(function (s) {
591	          var st = marks[s.id];
592	          return '<div class="att"><span class="avatar">' + esc(initials(s.name)) + '</span><div class="grow"><b>' + esc(s.name) + '</b><div class="muted small">' + esc(s.roll) +
593	            ' · ' + esc(s.parent.name) + (s.whatsappFailed ? ' <span class="badge warn" title="WhatsApp failed; the alert went by SMS">SMS used</span>' : '') +
594	            ' <button class="ghost sm inline" data-ph="' + esc(s.id) + '" aria-label="Edit parent number for ' + esc(s.name) + '" title="Edit parent number">' + icon('edit', 'sm') + '</button></div></div>' +
595	            '<div class="pa" role="group" aria-label="' + esc(s.name) + '"><button class="p" data-a="' + esc(s.id) + '" data-v="present" aria-pressed="' + (st === 'present') + '">P</button>' +
596	            '<button class="a" data-a="' + esc(s.id) + '" data-v="absent" aria-pressed="' + (st === 'absent') + '">A</button></div></div>';
597	        }).join('') + '</div>' +
598	        '<div class="sticky-actions"><button id="allp">Mark all present</button><button class="primary grow" id="sub">' + (d.submitted ? 'Update attendance' : 'Submit attendance') + '</button></div>';
599	      app.innerHTML = html;
600	
601	      $('tp').onchange = function () { topic = this.value; };
602	      each('[data-a]', function (b) { b.onclick = function () { marks[b.getAttribute('data-a')] = b.getAttribute('data-v'); draw(); }; });
603	      $('allp').onclick = function () { Object.keys(marks).forEach(function (k) { marks[k] = 'present'; }); draw(); };
604	      $('sub').onclick = function () {
605	        var btn = this; btn.disabled = true; btn.textContent = 'Saving…';
606	        post('teacher/assignments/' + aid + '/attendance', { lesson: topic, statuses: marks }).then(function (r) {
607	          toast('Attendance saved.' + (r.alertsSent ? ' ' + r.alertsSent + ' WhatsApp alert' + (r.alertsSent > 1 ? 's' : '') + ' sent to parents.' : ''));
608	          routes.class(aid);
609	        }, function (e) { btn.disabled = false; btn.textContent = 'Submit attendance'; toast(e.message); });
610	      };
611	      each('[data-ov]', function (b) {
612	        b.onclick = function () {
613	          var reason = prompt('Why are you clearing this student manually? (e.g. medical certificate provided)');
614	          if (reason === null) return;
615	          post('teacher/clearances/' + b.getAttribute('data-ov') + '/override', { reason: reason }).then(function (c) {
616	            toast(c.student + ' cleared. Parent notified.'); routes.class(aid);
617	          }, function (e) { toast(e.message); });
618	        };
619	      });
620	      each('[data-ph]', function (b) {
621	        b.onclick = function () {
622	          var s = d.students.filter(function (x) { return x.id === b.getAttribute('data-ph'); })[0];
623	          var v = prompt('Correct mobile number for ' + s.parent.name + ' (parent of ' + s.name + '):', s.parent.phone.replace('+92', '0'));
624	          if (v === null) return;
625	          post('teacher/students/' + s.id + '/parent-phone', { phone: v }).then(function (r) {
626	            s.parent = r.parent; toast('Parent number updated to ' + prettyPhone(r.parent.phone)); draw();
627	          }, function (e) { toast(e.message); });
628	        };
629	      });
630	    }
631	    draw();
632	  }
633	
634	  /* ---------- parent ---------- */
635	  routes.parent = function () {
636	    app.innerHTML = skeleton(2);
637	    Promise.all([get('parent/home'), get('messages')]).then(function (res) {
638	      var d = res[0], msgs = res[1];
639	      var html = banner() + '<p class="muted" style="margin:0">' + todayLong() + '</p><h1>' + esc(d.me.name) + '</h1><p class="muted">' + esc(d.me.college) + '</p>';
640	      d.children.forEach(function (c) {
641	        var pending = c.clearances.filter(function (x) { return x.status === 'pending'; });
642	        html += '<div class="card"><div class="row"><span class="avatar">' + esc(initials(c.name)) + '</span><div class="grow"><b>' + esc(c.name) + '</b><div class="muted small">' +
643	          esc(c.class + ' · Roll ' + c.roll) + '</div></div>' +
644	          (pending.length ? '<span class="badge pend">' + icon('cross', 'sm') + 'Clearance pending</span>' : '<span class="badge ok">' + icon('check', 'sm') + 'Up to date</span>') + '</div>' +
645	          c.clearances.map(function (x) {
646	            return '<div class="small" style="margin-top:8px">' + (x.status === 'pending'
647	              ? icon('alert', 'sm') + ' Absent ' + dayName(x.date) + ': must complete <b>' + esc(x.lesson.topic + ' ' + x.lesson.title) + '</b>' +
648	                (x.attempts ? ' (' + x.attempts + ' attempt' + (x.attempts > 1 ? 's' : '') + ', best ' + x.best + '/5)' : ' (not started yet)')
649	              : icon('check', 'sm') + ' Cleared ' + esc(x.lesson.topic + ' ' + x.lesson.title) + ', ' + when(x.clearedAt)) + '</div>';
650	          }).join('') +
651	          (c.attendance.length ? '<div class="attstrip" aria-label="Recent attendance">' + c.attendance.slice(0, 7).reverse().map(function (a) {
652	            return '<span class="' + esc(a.status) + '" title="' + esc(dayName(a.date) + ': ' + a.status) + '">' + esc(new Date(a.date + 'T00:00:00').toLocaleDateString([], { weekday: 'short' })) + '<br>' + (a.status === 'absent' ? 'A' : 'P') + '</span>';
653	          }).join('') + '</div>' : '') + '</div>';
654	      });
655	      html += '<h2>WhatsApp from the college</h2>' + chat(msgs, false);
656	      app.innerHTML = html;
657	    }, function (e) { app.innerHTML = errorCard(e); });
658	  };
659	
660	  /* ---------- messages ---------- */
661	  function chat(list, isTeacher) {
662	    var html = '<div class="wa"><div class="head"><span class="avatar">' + icon('book', 'sm') + '</span><div><b>' + esc(ME.college || 'Your college') +
663	      '</b><div class="small" style="opacity:.8">Verified business account</div></div></div><div class="body">';
664	    if (!list.length) html += '<p class="muted" style="text-align:center;padding:30px 8px">No messages yet.</p>';
665	    list.forEach(function (m) {
666	      var bad = m.status === 'failed' || m.status === 'skipped';
667	      html += '<div class="bubble' + (bad ? ' failed' : '') + '">' +
668	        (isTeacher ? '<div class="to">To ' + esc(m.toRole) + ': ' + esc(m.to) + ' · ' + esc(prettyPhone(m.phone)) + '</div>' : '') +
669	        '<div>' + esc(m.body) + '</div><div class="foot">' + (m.channel === 'sms' ? 'SMS · ' : '') + when(m.at) + ' ' +
670	        (m.status === 'failed' ? '✖ ' + esc(m.channel) + ' failed: ' + esc(m.error) : m.status === 'skipped' ? 'not sent: ' + esc(m.error) : '✓✓') + '</div></div>';
671	    });
672	    return html + '</div></div>';
673	  }
674	  routes.msgs = function () {
675	    app.innerHTML = skeleton(2);
676	    get('messages').then(function (list) {
677	      var isT = ME.role === 'teacher';
678	      app.innerHTML = banner() + '<h1>' + (isT ? 'WhatsApp log' : 'Messages') + '</h1><p class="muted">' +
679	        (isT ? 'Every alert sent about students in your classes, including failures and SMS fallbacks.' : 'Messages sent to you by the college.') + '</p>' +
680	        chat(list, isT) + '<p class="muted small" style="margin-top:12px">Demo: delivery is simulated. The real product sends approved WhatsApp templates, with SMS as the fallback.</p>';
681	    }, function (e) { app.innerHTML = errorCard(e); });
682	  };
683	
684	  route();
685	})();
