    function ui() {
      if (!$('pt')) return; // the student has left the lesson page
      $('pt').textContent = Math.round(share() * 100) + '% heard · section ' + (idx + 1) + ' of ' + l.script.length;
      $('pl').textContent = A.ended ? 'Finished' : mmss(A.currentTime) + ' / ' + mmss(l.duration);
