      unsent = {}; sending = true;
      post('lessons/' + encodeURIComponent(l.id) + '/progress', { secs: secs }, { keepalive: keepalive }).then(function (p) {
        sending = false;
        if (p.unlocked && !unlocked) { unlocked = true; toast('Quiz unlocked'); }
