      }).join('') + '</div></div>' +
      '<div class="row">' + (Q.i ? '<button id="bk">Back</button>' : '') + '<button class="primary grow" id="nx"' + (sel === undefined ? ' disabled' : '') + '>' + (last ? 'Submit answers' : 'Next') + '</button></div>' +
      '<p class="muted small" style="text-align:center">You need ' + d.passMark + ' of ' + d.size + ' correct to pass.</p>';
    each('.opt', function (b) {
      b.onclick = function () {
        Q.ans[Q.i] = +b.getAttribute('data-k');
        each('.opt', function (x) { x.setAttribute('aria-checked', x === b); });
        $('nx').disabled = false;
      };
    });
    if ($('bk')) $('bk').onclick = function () { Q.i--; drawQ(); };
    $('nx').onclick = function () {
      if (!last) { Q.i++; drawQ(); return; }
      var btn = $('nx'); btn.disabled = true; btn.textContent = 'Checking…';
      post('quiz/' + Q.data.attempt + '/submit', { answers: Q.ans }).then(showResult, function (e) {
        btn.disabled = false; btn.textContent = 'Submit answers'; toast(e.message);
      });
    };
  }
  function confetti() {
    var d = document.createElement('div'), cols = ['#0f8f83', '#1e3a5f', '#f5b94a', '#4ade9b', '#7aa7e8'];
    d.className = 'confetti';
    for (var i = 0; i < 40; i++) d.innerHTML += '<i style="left:' + Math.random() * 100 + '%;background:' + cols[i % 5] + ';animation-delay:' + Math.random() * .5 + 's"></i>';
    document.body.appendChild(d); setTimeout(function () { d.remove(); }, 2400);
  }
  function showResult(r) {
    var id = Q.id;
    var review = '<h2>Review your answers</h2>' + r.review.map(function (it) {
      return '<div class="card review ' + (it.ok ? 'right' : 'wrong') + '"><div class="row" style="align-items:flex-start">' +
        '<span class="badge ' + (it.ok ? 'ok' : 'warn') + '">' + icon(it.ok ? 'check' : 'cross', 'sm') + '</span><div class="grow"><b>' + esc(it.question) + '</b>' +
        '<div class="ans">' + (it.ok ? 'Your answer: ' + esc(it.options[it.correct])
          : 'You chose: ' + esc(it.chosen == null ? '(none)' : it.options[it.chosen]) + '<br>Correct: <b>' + esc(it.options[it.correct]) + '</b>') + '</div>' +
        '<div class="muted small" style="margin-top:4px">' + esc(it.explanation) + '</div></div></div></div>';
    }).join('');
    app.innerHTML = banner() + (r.passed
      ? '<div class="result pass"><div class="icon">' + icon('check') + '</div><div class="score">' + r.score + '/' + r.size + '</div><h1>Great job, you passed!</h1>' +
        (r.cleared ? '<p><span class="badge ok">' + icon('check', 'sm') + ' Cleared for class</span></p><p class="muted">Your parent and your teacher have been notified on WhatsApp.</p>'
          : '<p class="muted">Topic complete.</p>') +
        '</div><a class="btn primary block" href="#/home">Back to home</a>'
      : '<div class="result fail"><div class="icon">' + icon('refresh') + '</div><div class="score">' + r.score + '/' + r.size + '</div><h1>Almost there!</h1>' +
        '<p class="muted">You need ' + r.passMark + '/' + r.size + ' to pass. Review the lesson, then try again in ' + r.retryAfter + ' seconds.' +
        (r.attempts >= 3 ? '<br><b>Tip:</b> listen to the lesson once more before your next try.' : '') + '</p></div>' +
        '<div class="row"><a class="btn grow" href="#/lesson/' + esc(id) + '">Review lesson</a><a class="btn primary grow" href="#/quiz/' + esc(id) + '">Try again</a></div>') + review;
    window.scrollTo(0, 0);
    if (r.passed) confetti();
  }

  /* ---------- teacher ---------- */
  var autoOpened = false;
  routes.teacher = function () {
    app.innerHTML = skeleton(2);
    get('teacher/assignments').then(function (list) {
      if (list.length === 1 && !autoOpened) { autoOpened = true; location.hash = '#/class/' + list[0].id; return; }
      app.innerHTML = banner() + '<p class="muted" style="margin:0">' + todayLong() + '</p><h1>' + esc(ME.name) + '</h1><p class="muted">' + esc(ME.college) + '</p><h2>My classes</h2>' +
        (list.length ? list.map(function (a) {
          return '<a class="card" href="#/class/' + a.id + '"><div class="lesson-row"><span class="avatar">' + esc(a.subject.slice(0, 2)) + '</span><div class="grow"><b>' +
            esc(a.class) + '</b><div class="meta"><span>' + esc(a.subject) + '</span><span>' + a.students + ' students</span></div></div></div></a>';
        }).join('') : '<div class="card muted">You are not assigned to any class yet. Please contact the college admin.</div>');
    }, function (e) { app.innerHTML = errorCard(e); });
  };
  routes.class = function (aid) {
    app.innerHTML = skeleton(3);
    get('teacher/assignments/' + encodeURIComponent(aid)).then(function (d) { renderClass(aid, d); }, function (e) {
      app.innerHTML = '<a class="crumbs" href="#/teacher">' + icon('back', 'sm') + 'My classes</a>' + errorCard(e);
    });
  };
  function renderClass(aid, d) {
    var marks = {}, topic = d.topic || (d.lessons[0] && d.lessons[0].id);
    d.students.forEach(function (s) { marks[s.id] = s.status || 'present'; });
    function draw() {
      var absent = d.students.filter(function (s) { return marks[s.id] === 'absent'; }).length;
      var pending = d.clearances.filter(function (c) { return c.status === 'pending'; });
      var html = banner() + '<div class="crumbs"><a href="#/teacher">' + icon('back', 'sm') + 'My classes</a></div>' +
        '<p class="muted" style="margin:0">' + todayLong() + ' · ' + esc(d.assignment.subject) + '</p><h1>' + esc(d.assignment.class) + '</h1>' +
        '<div class="stats"><div class="stat ok"><b>' + (d.students.length - absent) + '</b><span>Present</span></div><div class="stat"><b>' + absent + '</b><span>Absent</span></div>' +
        '<div class="stat' + (pending.length ? ' warn' : '') + '"><b>' + pending.length + '</b><span>Pending</span></div></div>';
      if (d.clearances.length) {
        html += '<h2>Class clearance</h2>' + d.clearances.map(function (c) {
          var ok = c.status === 'cleared';
          return '<div class="card tight"><div class="row"><span class="avatar">' + esc(initials(c.student)) + '</span><div class="grow"><b>' + esc(c.student) + '</b>' +
            '<div class="muted small">' + esc(c.lesson.topic + ' ' + c.lesson.title) + ' · absent ' + dayName(c.date) + '</div><div class="muted small">' +
            (ok ? (c.clearedBy === 'teacher' ? 'Cleared by teacher: ' + esc(c.overrideReason) : 'Passed ' + c.best + '/5, ' + when(c.clearedAt))
              : (c.lastAttempt ? 'Last attempt ' + when(c.lastAttempt) + ' · best ' + c.best + '/5 · ' + c.attempts + ' attempt' + (c.attempts > 1 ? 's' : '') : 'Not started yet')) +
            '</div></div>' + (ok ? '<span class="badge ok">' + icon('check', 'sm') + 'Cleared</span>' : '<span class="badge pend">' + icon('cross', 'sm') + 'Pending</span>') + '</div>' +
            (ok ? '' : '<div style="text-align:right"><button class="ghost sm" data-ov="' + c.id + '">Clear manually…</button></div>') + '</div>';
        }).join('');
      }
      html += '<h2>' + (d.submitted ? 'Today’s attendance (submitted)' : 'Take attendance') + '</h2>' +
        '<label class="field" for="tp" style="margin-top:0">Topic taught today</label><select id="tp">' + d.lessons.map(function (l) {
          return '<option value="' + esc(l.id) + '"' + (topic === l.id ? ' selected' : '') + '>' + esc(l.topic + ' ' + l.title) + '</option>';
        }).join('') + '</select><p class="muted small">Absent students get this topic as their missed lecture, and their parents get a WhatsApp alert.</p>' +
        '<div class="card" style="padding:4px 12px">' + d.students.map(function (s) {
          var st = marks[s.id];
          return '<div class="att"><span class="avatar">' + esc(initials(s.name)) + '</span><div class="grow"><b>' + esc(s.name) + '</b><div class="muted small">' + esc(s.roll) +
            ' · ' + esc(s.parent.name) + (s.whatsappFailed ? ' <span class="badge warn" title="WhatsApp failed; the alert went by SMS">SMS used</span>' : '') +
            ' <button class="ghost sm inline" data-ph="' + esc(s.id) + '" aria-label="Edit parent number for ' + esc(s.name) + '" title="Edit parent number">' + icon('edit', 'sm') + '</button></div></div>' +
            '<div class="pa" role="group" aria-label="' + esc(s.name) + '"><button class="p" data-a="' + esc(s.id) + '" data-v="present" aria-pressed="' + (st === 'present') + '">P</button>' +
            '<button class="a" data-a="' + esc(s.id) + '" data-v="absent" aria-pressed="' + (st === 'absent') + '">A</button></div></div>';
        }).join('') + '</div>' +
        '<div class="sticky-actions"><button id="allp">Mark all present</button><button class="primary grow" id="sub">' + (d.submitted ? 'Update attendance' : 'Submit attendance') + '</button></div>';
      app.innerHTML = html;

      $('tp').onchange = function () { topic = this.value; };
      each('[data-a]', function (b) { b.onclick = function () { marks[b.getAttribute('data-a')] = b.getAttribute('data-v'); draw(); }; });
      $('allp').onclick = function () { Object.keys(marks).forEach(function (k) { marks[k] = 'present'; }); draw(); };
      $('sub').onclick = function () {
        var btn = this; btn.disabled = true; btn.textContent = 'Saving…';
        post('teacher/assignments/' + aid + '/attendance', { lesson: topic, statuses: marks }).then(function (r) {
          toast('Attendance saved.' + (r.alertsSent ? ' ' + r.alertsSent + ' WhatsApp alert' + (r.alertsSent > 1 ? 's' : '') + ' sent to parents.' : ''));
          routes.class(aid);
        }, function (e) { btn.disabled = false; btn.textContent = 'Submit attendance'; toast(e.message); });
      };
      each('[data-ov]', function (b) {
        b.onclick = function () {
          var reason = prompt('Why are you clearing this student manually? (e.g. medical certificate provided)');
          if (reason === null) return;
          post('teacher/clearances/' + b.getAttribute('data-ov') + '/override', { reason: reason }).then(function (c) {
            toast(c.student + ' cleared. Parent notified.'); routes.class(aid);
          }, function (e) { toast(e.message); });
        };
      });
      each('[data-ph]', function (b) {
        b.onclick = function () {
          var s = d.students.filter(function (x) { return x.id === b.getAttribute('data-ph'); })[0];
          var v = prompt('Correct mobile number for ' + s.parent.name + ' (parent of ' + s.name + '):', s.parent.phone.replace('+92', '0'));
          if (v === null) return;
          post('teacher/students/' + s.id + '/parent-phone', { phone: v }).then(function (r) {
            s.parent = r.parent; toast('Parent number updated to ' + prettyPhone(r.parent.phone)); draw();
          }, function (e) { toast(e.message); });
        };
      });
    }
    draw();
  }

  /* ---------- parent ---------- */
  routes.parent = function () {
    app.innerHTML = skeleton(2);
    Promise.all([get('parent/home'), get('messages')]).then(function (res) {
      var d = res[0], msgs = res[1];
      var html = banner() + '<p class="muted" style="margin:0">' + todayLong() + '</p><h1>' + esc(d.me.name) + '</h1><p class="muted">' + esc(d.me.college) + '</p>';
      d.children.forEach(function (c) {
        var pending = c.clearances.filter(function (x) { return x.status === 'pending'; });
        html += '<div class="card"><div class="row"><span class="avatar">' + esc(initials(c.name)) + '</span><div class="grow"><b>' + esc(c.name) + '</b><div class="muted small">' +
          esc(c.class + ' · Roll ' + c.roll) + '</div></div>' +
          (pending.length ? '<span class="badge pend">' + icon('cross', 'sm') + 'Clearance pending</span>' : '<span class="badge ok">' + icon('check', 'sm') + 'Up to date</span>') + '</div>' +
          c.clearances.map(function (x) {
            return '<div class="small" style="margin-top:8px">' + (x.status === 'pending'
              ? icon('alert', 'sm') + ' Absent ' + dayName(x.date) + ': must complete <b>' + esc(x.lesson.topic + ' ' + x.lesson.title) + '</b>' +
                (x.attempts ? ' (' + x.attempts + ' attempt' + (x.attempts > 1 ? 's' : '') + ', best ' + x.best + '/5)' : ' (not started yet)')
              : icon('check', 'sm') + ' Cleared ' + esc(x.lesson.topic + ' ' + x.lesson.title) + ', ' + when(x.clearedAt)) + '</div>';
          }).join('') +
          (c.attendance.length ? '<div class="attstrip" aria-label="Recent attendance">' + c.attendance.slice(0, 7).reverse().map(function (a) {
            return '<span class="' + esc(a.status) + '" title="' + esc(dayName(a.date) + ': ' + a.status) + '">' + esc(new Date(a.date + 'T00:00:00').toLocaleDateString([], { weekday: 'short' })) + '<br>' + (a.status === 'absent' ? 'A' : 'P') + '</span>';
          }).join('') + '</div>' : '') + '</div>';
      });
      html += '<h2>WhatsApp from the college</h2>' + chat(msgs, false);
      app.innerHTML = html;
    }, function (e) { app.innerHTML = errorCard(e); });
  };

  /* ---------- messages ---------- */
  function chat(list, isTeacher) {
    var html = '<div class="wa"><div class="head"><span class="avatar">' + icon('book', 'sm') + '</span><div><b>' + esc(ME.college || 'Your college') +
      '</b><div class="small" style="opacity:.8">Verified business account</div></div></div><div class="body">';
    if (!list.length) html += '<p class="muted" style="text-align:center;padding:30px 8px">No messages yet.</p>';
    list.forEach(function (m) {
      var bad = m.status === 'failed' || m.status === 'skipped';
      html += '<div class="bubble' + (bad ? ' failed' : '') + '">' +
        (isTeacher ? '<div class="to">To ' + esc(m.toRole) + ': ' + esc(m.to) + ' · ' + esc(prettyPhone(m.phone)) + '</div>' : '') +
        '<div>' + esc(m.body) + '</div><div class="foot">' + (m.channel === 'sms' ? 'SMS · ' : '') + when(m.at) + ' ' +
        (m.status === 'failed' ? '✖ ' + esc(m.channel) + ' failed: ' + esc(m.error) : m.status === 'skipped' ? 'not sent: ' + esc(m.error) : '✓✓') + '</div></div>';
    });
    return html + '</div></div>';
  }
  routes.msgs = function () {
    app.innerHTML = skeleton(2);
    get('messages').then(function (list) {
      var isT = ME.role === 'teacher';
      app.innerHTML = banner() + '<h1>' + (isT ? 'WhatsApp log' : 'Messages') + '</h1><p class="muted">' +
        (isT ? 'Every alert sent about students in your classes, including failures and SMS fallbacks.' : 'Messages sent to you by the college.') + '</p>' +
        chat(list, isT) + '<p class="muted small" style="margin-top:12px">Demo: delivery is simulated. The real product sends approved WhatsApp templates, with SMS as the fallback.</p>';
    }, function (e) { app.innerHTML = errorCard(e); });
  };

  route();
})();

