input.new_string:
.toast { pointer-events: none; }
body.has-player .toast { bottom: 250px; }

/* ---------- UX pass: home, teacher, dialogs ---------- */
.ring-wrap { display: flex; flex-direction: column; align-items: center; gap: 2px; font-size: 12px; color: var(--muted); font-weight: 600; }
details.card summary > span b { margin-right: 4px; }
.who { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 6px; }
.att.is-absent .avatar { background: var(--bad-bg); color: var(--bad); }
.sticky-actions button:disabled { opacity: 1; background: var(--ok-bg); color: var(--ok); border-color: var(--ok-bg); }
h2.row { display: flex; }
h2 .badge { text-transform: none; letter-spacing: 0; }
textarea { width: 100%; font: inherit; padding: 8px 12px; border-radius: 10px; border: 1px solid var(--border); background: var(--card); color: var(--text); resize: vertical; }

.sheet-back {
  position: fixed; inset: 0; z-index: 80; background: rgba(10,12,18,.55);
  display: flex; align-items: flex-end; justify-content: center;
}
.sheet {
  width: 100%; max-width: 520px; max-height: 90vh; overflow: auto; background: var(--card); color: var(--text);
  border-radius: 16px 16px 0 0; padding: 8px 16px calc(16px + env(safe-area-inset-bottom));
  animation: sheet-up .18s ease-out;
}
.sheet .grab { width: 40px; height: 4px; border-radius: 2px; background: var(--border); margin: 0 auto 8px; }
.sheet h2 { text-transform: none; letter-spacing: 0; color: var(--text); font-size: 18px; margin: 8px 0 8px; }
.sheet .err:empty { display: none; }
.choices { border: 0; padding: 0; margin: 0 0 8px; }
.choices legend { margin-top: 4px; }
.choice { display: flex; gap: 10px; align-items: center; min-height: 48px; padding: 8px 12px; margin: 6px 0; border: 1px solid var(--border); border-radius: 10px; cursor: pointer; }
.choice input { width: 20px; height: 20px; accent-color: var(--primary); flex: none; }
.choice:has(input:checked) { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
body.sheet-open { overflow: hidden; }
@keyframes sheet-up { from { transform: translateY(24px); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .sheet { animation: none; } }

/* ---------- tablet and desktop (960 px and up) ---------- */
@media (min-width: 960px) {
  /* Side rail instead of the phone's bottom tab bar. */
  nav.bottom {
    top: 61px; bottom: 0; right: auto; width: 208px; height: auto; flex-direction: column; justify-content: flex-start;
    gap: 4px; padding: 16px 12px; border-top: 0; border-right: 1px solid var(--border);
  }
  nav.bottom a { flex: none; flex-direction: row; justify-content: flex-start; gap: 12px; min-height: 48px; padding: 0 14px; border-radius: 10px; font-size: 15px; }
  nav.bottom a:hover { background: var(--sunk); color: var(--text); }
  nav.bottom a[aria-current=page] { background: var(--accent-bg); color: var(--primary); }
  nav.bottom a[aria-current=page]::before { top: 10px; bottom: 10px; left: 0; right: auto; width: 3px; height: auto; border-radius: 0 3px 3px 0; }
  nav.bottom a[href="#/logout"] { margin-top: auto; }
