p = r'C:\Users\USER\EduSaas\demo\app.js'
s = open(p, encoding='utf-8').read()


def rep(a, b):
    global s
    assert s.count(a) == 1, (s.count(a), a[:80])
    s = s.replace(a, b)


rep("""    var name = parts[1] || '', arg = parts[2];""", """    var name = parts[1] || '', arg = parts[2], arg2 = parts[3];""")
rep("""    routes[name](arg);""", """    routes[name](arg, arg2);""")
rep("""    teacher: 'teacher', class: 'teacher', parent: 'parent',""", """    teacher: 'teacher', class: 'teacher', parent: 'parent', child: 'parent',""")
rep("""    var active = { lesson: 'home', quiz: 'home', subject: 'home', class: 'teacher' }[name] || name;""",
    """    var active = { lesson: 'home', quiz: 'home', subject: 'home', class: 'teacher', child: 'parent' }[name] || name;""")

start = s.index("  /* ---------- parent ---------- */")
end = s.index("  /* ---------- messages ---------- */")
s = s[:start] + r"""  /* ---------- parent ---------- */
  function lastActive(iso) {
    if (!iso) return 'No lessons started yet';
    var d = new Date(iso), days = Math.floor((new Date().setHours(0, 0, 0, 0) - new Date(iso).setHours(0, 0, 0, 0)) / 864e5);
    return 'Last studied ' + (days === 0 ? 'today at ' + hm(iso) : days === 1 ? 'yesterday' : days + ' days ago');
  }
  function childCard(c) {
    var pending = c.clearances.filter(function (x) { return x.status === 'pending'; }), s = c.summary;
    var stat = function (v, label, cls) { return '<div class="stat' + (cls ? ' ' + cls : '') + '"><b>' + v + '</b><span>' + label + '</span></div>'; };
    var att = s.attendanceRate30d == null ? '–' : s.attendanceRate30d + '%';
    return '<div class="card child-card"><div class="row"><span class="avatar">' + esc(initials(c.name)) + '</span><div class="grow"><b>' + esc(c.name) + '</b><div class="muted small">' +
      esc(c.class + ' · Roll ' + c.roll) + '</div></div>' +
      (pending.length ? '<span class="badge warn">' + icon('alert', 'sm') + pending.length + ' to clear</span>' : '<span class="badge ok">' + icon('check', 'sm') + 'Up to date</span>') + '</div>' +
      '<div class="stats">' +
      stat(att, s.attendanceRate30d == null ? 'No attendance yet' : 'Attendance, 30 days (' + s.attendanceClasses30d.present + ' of ' + s.attendanceClasses30d.total + ' classes)',
        s.attendanceRate30d != null && s.attendanceRate30d < 75 ? 'warn' : 'ok') +
      stat(s.topicsDone + '/' + s.topicsTotal, 'Topics done') +
      stat(s.avgScore == null ? '–' : s.avgScore + '<small>/5</small>', 'Average quiz score') + '</div>' +
      c.clearances.map(function (x) {
        return '<div class="small clr-line">' + (x.status === 'pending'
          ? icon('alert', 'sm') + '<span>Absent ' + dayName(x.date) + ': must complete <b>' + esc(x.lesson.subject + ' ' + x.lesson.topic + ' ' + x.lesson.title) + '</b>' +
            (x.attempts ? ' (' + x.attempts + ' attempt' + (x.attempts > 1 ? 's' : '') + ', best ' + x.best + '/5)' : ' (not started yet)') + '</span>'
          : icon('check', 'sm') + '<span>Cleared ' + esc(x.lesson.subject + ' ' + x.lesson.topic + ' ' + x.lesson.title) + ', ' + when(x.clearedAt) + '</span>') + '</div>';
      }).join('') +
      '<div class="muted small" style="margin:14px 0 4px">Subjects</div>' + (c.subjects.length ? c.subjects.map(function (x) {
        var live = x.status === 'live';
        var inner = subjectIcon(x.code, 'sm') + '<span class="grow"><b>' + esc(x.name) + '</b><span class="muted small"> · ' +
          (live ? x.done + ' of ' + x.total + ' topics' + (x.avgScore != null ? ' · avg ' + x.avgScore + '/5' : '') : 'Coming soon') + '</span>' +
          (live ? '<span class="bar" aria-hidden="true"><i style="width:' + (x.total ? x.done / x.total * 100 : 0) + '%"></i></span>' : '') + '</span>';
        return live ? '<a class="subj-line" href="#/child/' + esc(c.id) + '/' + esc(x.code) + '">' + inner + icon('next', 'sm') + '</a>'
          : '<div class="subj-line locked">' + inner + '</div>';
      }).join('') : '<p class="muted small">The college hasn’t added subjects yet.</p>') +
      (c.attendance.length ? '<div class="muted small" style="margin-top:12px">Recent attendance</div><div class="attstrip" aria-label="Recent attendance">' + c.attendance.slice(0, 7).reverse().map(function (a) {
        return '<span class="' + esc(a.status) + '" title="' + esc(dayName(a.date) + ' · ' + a.subject + ': ' + a.status) + '">' + esc(new Date(a.date + 'T00:00:00').toLocaleDateString([], { weekday: 'short' })) + '<br>' + (a.status === 'absent' ? 'A' : 'P') + '</span>';
      }).join('') + '</div>' : '') +
      '<p class="muted small" style="margin:12px 0 0">' + icon('clock', 'sm') + ' ' + esc(lastActive(s.lastActive)) +
      (s.medianDaysToClear != null ? ' · clears missed lectures in ' + s.medianDaysToClear + ' day' + (s.medianDaysToClear === 1 ? '' : 's') + ' (typical)' : '') + '</p></div>';
  }
  routes.parent = function () {
    app.innerHTML = skeleton(2);
    Promise.all([get('parent/home'), get('messages')]).then(function (res) {
      var d = res[0], msgs = res[1];
      var html = banner() + '<p class="muted" style="margin:0">' + todayLong() + '</p><h1>' + esc(d.me.name) + '</h1><p class="muted">' + esc(d.me.college) + '</p>' +
        '<div class="children">' + d.children.map(childCard).join('') + '</div>' +
        '<h2>Messages from the college</h2>' + chat(msgs.slice(-4), false) +
        (msgs.length > 4 ? '<p style="text-align:center"><a href="#/msgs">See all ' + msgs.length + ' messages</a></p>' : '') +
        '<div class="card row toggle-row"><div class="grow"><b>Weekly summary</b><div class="muted small">Every Sunday evening, a short progress report in Messages.</div></div>' +
        '<label class="switch"><input type="checkbox" id="wk"' + (d.weeklySummary ? ' checked' : '') + ' aria-label="Weekly summary"><span></span></label></div>';
      app.innerHTML = html;
      $('wk').onchange = function () {
        var box = this, v = box.checked; box.disabled = true;
        post('parent/settings', { weeklySummary: v }).then(function () {
          box.disabled = false; toast(v ? 'Weekly summary turned on' : 'Weekly summary turned off');
        }, function (e) { box.disabled = false; box.checked = !v; toast(e.message); });
      };
    }, function (e) { app.innerHTML = errorCard(e, true); if ($('retry')) $('retry').onclick = route; });
  };
  var TOPIC_STATE = {
    passed: ['ok', 'check', 'Passed'], quiz_ready: ['warn', 'lock', 'Quiz ready'],
    listening: ['neutral', 'clock', 'Listening'], not_started: ['neutral', 'minus', 'Not started']
  };
  routes.child = function (sid, code) {
    app.innerHTML = skeleton(3);
    get('parent/children/' + encodeURIComponent(sid) + '/subjects/' + encodeURIComponent(code)).then(function (d) {
      var html = banner() + '<div class="crumbs"><a href="#/parent">' + icon('back', 'sm') + esc(d.child.name) + '</a></div>' +
