import { createContext, useCallback, useContext, useEffect, useState, type ComponentType } from 'react';
import { get, getToken, post, setToken, setUnauthorizedHandler, type Me, type Role } from './lib/api';
import { useI18n } from './lib/i18n';
import { disablePush, pushSupport } from './lib/push';
import { go, useRoute } from './lib/router';
import { ErrorCard, Icon, Skeleton } from './ui';
import Login from './screens/Login';
import Gallery from './screens/Gallery';
import StudentHome from './screens/student/Home';
import Subject from './screens/student/Subject';
import Library from './screens/student/Library';
import Lesson from './screens/student/Lesson';
import Quiz from './screens/student/Quiz';
import ParentHome from './screens/parent/ParentHome';
import Child from './screens/parent/Child';
import Messages from './screens/Messages';
import TeacherHome from './screens/teacher/TeacherHome';
import ClassPage from './screens/teacher/ClassPage';
import AdminHome from './screens/admin/AdminHome';
import Activity from './screens/admin/Activity';
import People from './screens/admin/People';
import Classes from './screens/admin/Classes';
import Import from './screens/admin/Import';

// ---------- session ----------
interface Session { me: Me; setMe: (m: Me) => void; signOut: () => void }
const SessionCtx = createContext<Session | null>(null);
export function useSession(): Session {
  const s = useContext(SessionCtx);
  if (!s) throw new Error('useSession outside a signed-in screen');
  return s;
}

// ---------- routes ----------
type Screen = ComponentType<{ args: string[] }>;
const ROUTES: Record<string, { roles: Role[]; screen: Screen; nav?: string; player?: boolean }> = {
  home: { roles: ['student'], screen: StudentHome },
  subject: { roles: ['student'], screen: Subject, nav: 'home' },
  library: { roles: ['student'], screen: Library },
  lesson: { roles: ['student'], screen: Lesson, nav: 'home', player: true },
  quiz: { roles: ['student'], screen: Quiz, nav: 'home' },
  parent: { roles: ['parent'], screen: ParentHome },
  child: { roles: ['parent'], screen: Child, nav: 'parent' },
  msgs: { roles: ['teacher', 'parent'], screen: Messages },
  teacher: { roles: ['teacher'], screen: TeacherHome },
  class: { roles: ['teacher'], screen: ClassPage, nav: 'teacher' },
  admin: { roles: ['college_admin'], screen: AdminHome },
  activity: { roles: ['college_admin'], screen: Activity, nav: 'admin' },
  people: { roles: ['college_admin'], screen: People },
  classes: { roles: ['college_admin'], screen: Classes },
  import: { roles: ['college_admin'], screen: Import },
};
const HOME: Record<Role, string> = { student: '#/home', teacher: '#/teacher', parent: '#/parent', college_admin: '#/admin' };
const NAV: Record<Role, [string, string, string][]> = {
  student: [['home', 'home', 'Home'], ['library', 'library', 'Library']],
  teacher: [['teacher', 'users', 'My classes'], ['msgs', 'chat', 'Alerts log']],
  parent: [['parent', 'home', 'My child'], ['msgs', 'chat', 'Messages']],
  college_admin: [['admin', 'home', 'Home'], ['people', 'users', 'People'], ['classes', 'library', 'Classes'], ['import', 'pages', 'Import']],
};

function Header() {
  const { lang, setLang, t } = useI18n();
  const [, force] = useState(0);
  function theme() {
    const r = document.documentElement, cur = r.getAttribute('data-theme');
    const dark = cur ? cur === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    r.setAttribute('data-theme', dark ? 'light' : 'dark');
    try { localStorage.setItem('edusaas_theme', dark ? 'light' : 'dark'); } catch { /* ignore */ }
    force((n) => n + 1);
  }
  function switchLang() {
    const next = lang === 'ur' ? 'en' : 'ur';
    setLang(next);
    if (getToken()) post('me/language', { language: next }).catch(() => {});
  }
  return (
    <header className="top">
      <a className="brand" href="#/"><span className="mark"><Icon name="book" /></span>EduSaas <small>demo</small></a>
      <button className="langbtn" lang={lang === 'ur' ? 'en' : 'ur'} onClick={switchLang}
        aria-label={lang === 'ur' ? 'Switch to English' : t('Switch to Urdu')}>{lang === 'ur' ? 'English' : 'اردو'}</button>
      <button className="iconbtn" onClick={theme} aria-label="Switch light or dark theme" title="Theme"><Icon name="moon" /></button>
    </header>
  );
}

function Nav({ role, active }: { role: Role; active: string }) {
  const { t } = useI18n();
  return (
    <nav className="bottom" aria-label="Main">
      {NAV[role].map(([name, icon, label]) => (
        <a key={name} href={'#/' + name} aria-current={active === name ? 'page' : undefined}><Icon name={icon} />{t(label)}</a>
      ))}
      <a href="#/logout"><Icon name="logout" />{t('Log out')}</a>
    </nav>
  );
}

export default function App() {
  const route = useRoute();
  const { lang, setLang } = useI18n();
  const [me, setMe] = useState<Me | null>(null);
  const [loadError, setLoadError] = useState<{ message: string } | null>(null);
  const [hasToken, setHasToken] = useState(!!getToken());

  const signOut = useCallback(() => {
    const done = () => { setToken(null); setMe(null); setHasToken(false); go('#/login'); };
    // This phone should stop getting the previous person's alerts.
    if (getToken() && pushSupport() === 'ok') {
      let finished = false;
      const once = () => { if (!finished) { finished = true; done(); } };
      disablePush().then(once, once); setTimeout(once, 2000);
    } else done();
  }, []);

  useEffect(() => { setUnauthorizedHandler(() => { setMe(null); setHasToken(false); go('#/login'); }); }, []);
  useEffect(() => {
    try { const th = localStorage.getItem('edusaas_theme'); if (th) document.documentElement.setAttribute('data-theme', th); } catch { /* ignore */ }
  }, []);
  useEffect(() => {
    if (!hasToken || me) return;
    get<Me>('me').then((m) => { setMe(m); if (m.language && m.language !== lang) setLang(m.language); },
      (e) => { if (e.status !== 401) setLoadError(e); });
  }, [hasToken, me]); // eslint-disable-line react-hooks/exhaustive-deps

  const onSignedIn = useCallback((m: Me) => {
    setHasToken(true); setMe(m);
    if (m.language !== lang) post('me/language', { language: lang }).catch(() => {});
    go(HOME[m.role]);
  }, [lang]);

  // Routing decisions
  if (route.name === 'gallery') return <Shell><Gallery /></Shell>;
  if (route.name === 'logout') { if (hasToken || me) signOut(); else go('#/login'); return null; }
  if (!hasToken) {
    if (route.name !== 'login') { go('#/login'); return null; }
    return <Shell><Login onSignedIn={onSignedIn} /></Shell>;
  }
  if (!me) return <Shell>{loadError ? <ErrorCard error={loadError} /> : <Skeleton rows={2} />}</Shell>;
  const def = ROUTES[route.name];
  if (!def || !def.roles.includes(me.role)) { go(HOME[me.role]); return null; }
  const Screen = def.screen;
  document.body.classList.toggle('has-player', !!def.player);
  return (
    <SessionCtx.Provider value={{ me, setMe, signOut }}>
      <Shell nav={<Nav role={me.role} active={def.nav || route.name} />}>
        <Screen key={route.name + '/' + route.args.join('/')} args={route.args} />
      </Shell>
    </SessionCtx.Provider>
  );
}

function Shell({ children, nav }: { children: React.ReactNode; nav?: React.ReactNode }) {
  return <><Header /><main id="app">{children}</main>{nav}</>;
}

