import { useEffect, useState } from 'react';
import { ApiError, post, type QuizResult, type QuizStart } from '../../lib/api';
import { useI18n } from '../../lib/i18n';
import { Bar, ErrorCard, Icon, OfflineBanner, Skeleton, useToast } from '../../ui';

/** Five questions drawn on the server; answers are only revealed after submitting (scored on the server). */
export default function Quiz({ args }: { args: string[] }) {
  const { t, subj, err } = useI18n();
  const id = args[0] || '';
  const [quiz, setQuiz] = useState<QuizStart | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [i, setI] = useState(0);
  const [answers, setAnswers] = useState<number[]>([]);
  const [result, setResult] = useState<QuizResult | null>(null);
  const [busy, setBusy] = useState(false);
  const [n, setN] = useState(0);
  const toast = useToast();
  useEffect(() => {
    setQuiz(null); setError(null); setResult(null); setI(0); setAnswers([]);
    post<QuizStart>('lessons/' + encodeURIComponent(id) + '/quiz').then(setQuiz, setError);
  }, [id, n]);

  const backLink = <div className="crumbs"><a href={'#/lesson/' + id}><Icon name="back" sm />{t('Back to lesson')}</a></div>;
  if (error) {
    if (error.status === 0) return <>{backLink}<ErrorCard error={error} onRetry={() => setN((x) => x + 1)} /></>;
    return (
      <>{backLink}
        <div className="card" style={{ textAlign: 'center', padding: '24px 16px' }}>
          <Icon name={error.code === 'cooldown' ? 'clock' : 'lock'} /><p><b>{err(error)}</b></p>
          {error.code === 'cooldown'
            ? <button className="primary" onClick={() => setN((x) => x + 1)}>{t('Try again')}</button>
            : <a className="btn primary" href={'#/lesson/' + id}>{t('Back to lesson')}</a>}
        </div></>
    );
  }
  if (result) return <Result r={result} id={id} />;
  if (!quiz) return <Skeleton rows={1} />;

  const it = quiz.questions[i], last = i === quiz.questions.length - 1, sel = answers[i];
  async function submit() {
    setBusy(true);
    try {
      const r = await post<QuizResult>('quiz/' + quiz!.attempt + '/submit', { answers });
      setResult(r); window.scrollTo(0, 0);
    } catch (e) { toast(err(e as ApiError)); setBusy(false); }
  }
  return (
    <>
      <OfflineBanner />{backLink}
      <div className="qhead"><b>{t('{subject} · {topic} quiz', { subject: subj(quiz.lesson.subject), topic: quiz.lesson.topic })}</b>
        <span>{t('Question {i} of {n}', { i: i + 1, n: quiz.questions.length })}</span></div>
      <Bar value={(i + 1) / quiz.questions.length} style={{ margin: '8px 0 16px' }} />
      <div className="card">
        <p className="qtext" id="qt">{it.question}</p>
        <div role="radiogroup" aria-labelledby="qt">
          {it.options.map((o, k) => (
            <button key={k} className="opt" role="radio" aria-checked={sel === k}
              onClick={() => setAnswers((a) => { const b = a.slice(); b[i] = k; return b; })}>
              <span className="k">{'ABCD'[k]}</span><span>{o}</span>
            </button>
          ))}
        </div>
      </div>
      <div className="row">
        {i > 0 && <button onClick={() => setI(i - 1)}>{t('Back')}</button>}
        <button className="primary grow" disabled={sel === undefined || busy} onClick={() => (last ? submit() : setI(i + 1))}>
          {busy ? t('Checking…') : t(last ? 'Submit answers' : 'Next')}
        </button>
      </div>
      <p className="muted small" style={{ textAlign: 'center' }}>{t('You need {m} of {n} correct to pass.', { m: quiz.passMark, n: quiz.size })}</p>
    </>
  );
}

function Result({ r, id }: { r: QuizResult; id: string }) {
  const { t, tr } = useI18n();
  return (
    <>
      <OfflineBanner />
      {r.passed ? (
        <>
          <div className="result pass"><div className="icon"><Icon name="check" /></div>
            <div className="score" dir="ltr">{r.score}/{r.size}</div><h1>{t('Great job, you passed!')}</h1>
            {r.cleared
              ? <><p><span className="badge ok"><Icon name="check" sm /> {t('Cleared for class')}</span></p><p className="muted">{t('Your parent and your teacher have been told.')}</p></>
              : <p className="muted">{t('Topic complete.')}</p>}
          </div>
          <a className="btn primary block" href="#/home">{t('Back to home')}</a>
          <Confetti />
        </>
      ) : (
        <>
          <div className="result fail"><div className="icon"><Icon name="refresh" /></div>
            <div className="score" dir="ltr">{r.score}/{r.size}</div><h1>{t('Almost there!')}</h1>
            <p className="muted">{t('You need {m}/{n} to pass. Review the lesson, then try again in {s} seconds.', { m: r.passMark, n: r.size, s: r.retryAfter })}
              {r.attempts >= 3 && <><br />{t('Tip: listen to the lesson once more before your next try.')}</>}</p>
          </div>
          <div className="row"><a className="btn grow" href={'#/lesson/' + id}>{t('Review lesson')}</a>
            <a className="btn primary grow" href={'#/quiz/' + id + '/again-' + Date.now()}>{t('Try again')}</a></div>
        </>
      )}
      <h2>{t('Review your answers')}</h2>
      {r.review.map((it, k) => (
        <div key={k} className={'card review ' + (it.ok ? 'right' : 'wrong')}>
          <div className="row" style={{ alignItems: 'flex-start' }}>
            <span className={'badge ' + (it.ok ? 'ok' : 'warn')}><Icon name={it.ok ? 'check' : 'cross'} sm /></span>
            <div className="grow"><b>{it.question}</b>
              <div className="ans">{it.ok ? t('Your answer: {a}', { a: it.options[it.correct] }) : (
                <>{t('You chose: {a}', { a: it.chosen == null ? t('(none)') : it.options[it.chosen] })}<br />
                  {tr('Correct: {a}', { a: <b>{it.options[it.correct]}</b> })}</>
              )}</div>
              <div className="muted small" style={{ marginTop: 4 }}>{it.explanation}</div>
            </div>
          </div>
        </div>
      ))}
    </>
  );
}

function Confetti() {
  const [show, setShow] = useState(true);
  useEffect(() => { const id = window.setTimeout(() => setShow(false), 2400); return () => window.clearTimeout(id); }, []);
  if (!show) return null;
  const cols = ['#0f8f83', '#1e3a5f', '#f5b94a', '#4ade9b', '#7aa7e8'];
  return (
    <div className="confetti" aria-hidden="true">
      {Array.from({ length: 40 }, (_, i) => (
        <i key={i} style={{ left: Math.random() * 100 + '%', background: cols[i % 5], animationDelay: Math.random() * 0.5 + 's' }} />
      ))}
    </div>
  );
}

