          label={s.attendanceRate30d == null ? t('No attendance yet') : <>{t('Attendance')}<br />{t('{p} of {t} classes, 30 days', { p: s.attendanceClasses30d.present, t: s.attendanceClasses30d.total })}</>} />
        <Stat value={s.topicsDone + '/' + s.topicsTotal} label={t('Topics done')} />
        <Stat value={s.avgScore == null ? '–' : <>{s.avgScore}<small>/5</small></>} label={t('Average quiz score')} />
      </div>
      {c.clearances.map((x) => (
        <div key={x.id} className="small clr-line">
          {x.status === 'pending' ? (
            <><Icon name="alert" sm /><span>{tr('Absent {date}: must complete {topic}', { date: dayName(x.date, locale), topic: <b>{subj(x.lesson.subject)} {x.lesson.topic} {x.lesson.title}</b> })}{' '}
              {x.attempts ? t(x.attempts > 1 ? '({n} attempts, best {best}/5)' : '({n} attempt, best {best}/5)', { n: x.attempts, best: x.best ?? 0 }) : t('(not started yet)')}</span></>
          ) : (
            <><Icon name="check" sm /><span>{t('Cleared {topic}, {when}', { topic: `${subj(x.lesson.subject)} ${x.lesson.topic} ${x.lesson.title}`, when: when(x.clearedAt, locale) })}</span></>
          )}
        </div>
      ))}
      <div className="muted small" style={{ margin: '14px 0 4px' }}>{t('Subjects')}</div>
      {c.subjects.length ? c.subjects.map((x) => {
        const live = x.status === 'live';
        const inner = (
          <><SubjectIcon code={x.code} sm /><span className="grow"><b>{subj(x.name)}</b><span className="muted small"> · {live
            ? t('{done} of {total} topics', { done: x.done, total: x.total }) + (x.avgScore != null ? ' · ' + t('avg {a}/5', { a: x.avgScore }) : '')
            : t('Coming soon')}</span>{live && <Bar value={x.total ? x.done / x.total : 0} />}</span></>
        );
        return live ? <a key={x.code} className="subj-line" href={'#/child/' + c.id + '/' + x.code}>{inner}<Icon name="chev" sm /></a>
          : <div key={x.code} className="subj-line locked">{inner}</div>;
      }) : <p className="muted small">{t('The college hasn’t added subjects yet.')}</p>}
      {c.attendance.length > 0 && (
        <>
          <div className="muted small" style={{ marginTop: 12 }}>{t('Recent attendance')}</div>
          <div className="attstrip" aria-label={t('Recent attendance')}>
            {c.attendance.slice(0, 7).reverse().map((a, k) => (
              <span key={k} className={a.status} title={`${dayName(a.date, locale)} · ${subj(a.subject)}: ${a.status}`}>
                {new Date(a.date + 'T00:00:00').toLocaleDateString(locale, { weekday: 'short' })}<br />{t(a.status === 'absent' ? 'A' : 'P')}</span>
            ))}
          </div>
        </>
      )}
      <p className="muted small" style={{ margin: '12px 0 0' }}><Icon name="clock" sm /> <LastActive iso={s.lastActive} />
        {s.medianDaysToClear != null && ' · ' + t(s.medianDaysToClear === 1 ? 'usually clears missed lectures in {n} day' : 'usually clears missed lectures in {n} days', { n: s.medianDaysToClear })}</p>
    </div>
  );
}

export default function ParentHome() {
  const { t, locale } = useI18n();
  const toast = useToast();
  const { data, error, reload } = useLoad(() => Promise.all([get<ParentData>('parent/home'), get<Message[]>('messages')]));
  const [weekly, setWeekly] = useState<boolean | null>(null);
  if (error) return <ErrorCard error={error} onRetry={reload} />;
  if (!data) return <Skeleton rows={2} />;
  const [d, msgs] = data;
  const on = weekly ?? d.weeklySummary;
  async function toggle(v: boolean) {
    setWeekly(v);
    try { await post('parent/settings', { weeklySummary: v }); toast(t(v ? 'Weekly summary turned on' : 'Weekly summary turned off')); }
    catch (e) { setWeekly(!v); toast((e as Error).message); }
  }
  return (
    <>
      <OfflineBanner />
      <p className="muted" style={{ margin: 0 }}>{todayLong(locale)}</p>
      <h1>{d.me.name}</h1><p className="muted">{d.me.college}</p>
      <div className="children">{d.children.map((c) => <ChildCard key={c.id} c={c} />)}</div>
      <AlertsCard />
      <h2>{t('Messages from the college')}</h2>
      <Chat list={msgs.slice(-4)} />
      {msgs.length > 4 && <p style={{ textAlign: 'center' }}><a href="#/msgs">{t('See all {n} messages', { n: msgs.length })}</a></p>}
      <div className="card row toggle-row">
        <div className="grow"><b>{t('Weekly summary')}</b><div className="muted small">{t('Every Sunday evening, a short progress report in Messages.')}</div></div>
        <label className="switch"><input type="checkbox" checked={on} onChange={(e) => toggle(e.target.checked)} aria-label={t('Weekly summary')} /><span /></label>
      </div>
    </>
  );
}

import { get } from '../../lib/api';
import { useI18n } from '../../lib/i18n';
import { useLoad } from '../../lib/useLoad';
import { Badge, ErrorCard, Icon, OfflineBanner, Skeleton, SubjectIcon, type Tone } from '../../ui';

interface Topic { id: string; topic: string; title: string; status: 'passed' | 'quiz_ready' | 'listening' | 'not_started'; heardShare: number; best: number | null; missed: boolean; cleared: boolean }
interface ChildSubject {
  child: { id: string; name: string; class: string }; subject: { code: string; name: string; status: string };
  passMark: number; quizSize: number; units: { number: number; title: string; status: string; topics: Topic[] }[];
}
const STATE: Record<Topic['status'], [Tone, string, string]> = {
  passed: ['ok', 'check', 'Passed'], quiz_ready: ['warn', 'lock', 'Quiz ready'],
  listening: ['neutral', 'clock', 'Listening'], not_started: ['neutral', 'minus', 'Not started'],
};

/** One subject of the parent's own child: read-only topic statuses (F21). */
export default function Child({ args }: { args: string[] }) {
  const { t, subj } = useI18n();
  const [sid, code] = args;
  const { data: d, error, reload } = useLoad(() => get<ChildSubject>(`parent/children/${encodeURIComponent(sid || '')}/subjects/${encodeURIComponent(code || '')}`), [sid, code]);
  if (error) return <><a className="crumbs" href="#/parent"><Icon name="back" sm />{t('My child')}</a><ErrorCard error={error} onRetry={reload} /></>;
  if (!d) return <Skeleton />;
  const soon = d.units.filter((u) => u.status !== 'live').length;
  return (
    <>
      <OfflineBanner />
      <div className="crumbs"><a href="#/parent"><Icon name="back" sm />{d.child.name}</a></div>
      <div className="row" style={{ margin: '6px 0 4px' }}><span className="sicon big"><SubjectIcon code={d.subject.code} /></span>
        <div className="grow"><h1 style={{ margin: 0 }}>{subj(d.subject.name)}</h1><p className="muted" style={{ margin: 0 }}>{d.child.name} · {d.child.class}</p></div></div>
      <div className="banner info"><Icon name="shield" sm />
        <span>{t('After each lesson there is a {q}-question quiz. {p} correct answers is a pass. A missed lecture is cleared when the quiz is passed.', { q: d.quizSize, p: d.passMark })}</span></div>
      {d.units.filter((u) => u.status === 'live').map((u) => (
        <div key={u.number}>
          <h2>{t('Unit {n}', { n: u.number })} · {u.title}</h2>
          <div className="card" style={{ padding: '4px 12px' }}>
            {u.topics.map((tp) => {
              const [tone, icon, label] = STATE[tp.status];
              const extra = tp.status === 'passed' ? ' ' + tp.best + '/5' : tp.status === 'listening' ? ' (' + t('{p}% heard', { p: Math.round(tp.heardShare * 100) }) + ')' : '';
              return (
                <div key={tp.id} className="att"><span className="chip">{tp.topic}</span>
                  <div className="grow"><b>{tp.title}</b>
                    {tp.missed ? <div className="small" style={{ color: 'var(--warn)' }}>{t('Missed lecture, not cleared yet')}</div>
                      : tp.cleared ? <div className="small" style={{ color: 'var(--ok)' }}>{t('Missed, now cleared')}</div> : null}</div>
                  <Badge tone={tone} icon={icon}>{t(label) + extra}</Badge>
                </div>
              );
            })}
          </div>
        </div>
      ))}
      {soon > 0 && <p className="muted small" style={{ textAlign: 'center' }}>{t(soon > 1 ? '{n} more units coming soon.' : '{n} more unit coming soon.', { n: soon })}</p>}
    </>
  );
}

