    <>
      <OfflineBanner />{back}
      <p className="muted" style={{ margin: 0 }}>{todayLong()} · {d.assignment.subject}</p><h1>{d.assignment.class}</h1>
      <div className="stats">
        <Stat value={d.students.length - absent} label="Present" tone="ok" />
        <Stat value={absent} label="Absent" />
        <Stat value={pending.length} label="Pending" tone={pending.length ? 'warn' : undefined} />
      </div>
      {today.length > 0 && (todo.length === 0
        ? <div className="card ok-card small row"><Icon name="check" sm /><span>All parents of today’s absent students have been told on WhatsApp.</span></div>
