import { useEffect, useState } from 'react';
import { useSession } from '../../App';
import { get, post } from '../../lib/api';
import { todayLong } from '../../lib/format';
import { go } from '../../lib/router';
import { useLoad } from '../../lib/useLoad';
import AlertsCard from '../../ui/AlertsCard';
import { Badge, ErrorCard, Icon, OfflineBanner, Sheet, Skeleton, SubjectIcon, useToast } from '../../ui';

export interface Assignment { id: number; class: string; classId: string; subject: string; subjectCode: string; grade: string; subjectStatus: string; students: number }
interface Request { id: number; classId: string; class: string; subject: { code: string; name: string; status: string }; status: string; note: string }
interface CatalogueRow { code: string; name: string; status: string; inClass: boolean }

let autoOpened = false; // open the only class straight away, once per visit
const dismissed = (): number[] => { try { return JSON.parse(localStorage.getItem('edusaas_dismissed') || '[]'); } catch { return []; } };

export default function TeacherHome() {
  const { me } = useSession();
  const toast = useToast();
  const { data, error, reload } = useLoad(() => Promise.all([get<Assignment[]>('teacher/assignments'), get<Request[]>('teacher/subject-requests')]));
  const [adding, setAdding] = useState(false);
  const [gone, setGone] = useState(dismissed);
  const open = data ? data[1].filter((r) => r.status === 'pending' || (r.status === 'declined' && !gone.includes(r.id))) : [];
  useEffect(() => {
    if (data && data[0].length === 1 && !open.length && !autoOpened) { autoOpened = true; go('#/class/' + data[0][0].id); }
  }, [data]); // eslint-disable-line react-hooks/exhaustive-deps
  if (error) return <ErrorCard error={error} onRetry={reload} />;
  if (!data) return <Skeleton rows={2} />;
  const [list] = data;
  function dismiss(id: number) {
    const ids = [...gone, id];
    try { localStorage.setItem('edusaas_dismissed', JSON.stringify(ids)); } catch { /* ignore */ }
    setGone(ids);
  }
  return (
    <>
      <OfflineBanner />
      <p className="muted" style={{ margin: 0 }}>{todayLong()}</p><h1>{me.name}</h1><p className="muted">{me.college}</p>
      <h2 className="row between">My classes<button className="sm" onClick={() => setAdding(true)}><Icon name="plus2" sm />Add subject</button></h2>
      {list.length ? (
        <div className="lesson-list">
          {list.map((a) => (
            <a key={a.id} className="card" href={'#/class/' + a.id}><div className="lesson-row">
              <span className="sicon"><SubjectIcon code={a.subjectCode} /></span>
              <div className="grow"><b>{a.class}</b><div className="meta"><span>{a.subject}</span><span>{a.students} students</span>
                {a.subjectStatus !== 'live' && <Badge tone="neutral">Coming soon</Badge>}</div></div></div></a>
          ))}
        </div>
      ) : <div className="card muted">You are not assigned to any class yet. Please contact the college admin.</div>}
      {open.length > 0 && (
        <>
          <h2>Your subject requests</h2>
          {open.map((r) => {
            const dec = r.status === 'declined';
            return (
              <div key={r.id} className={'card tight' + (dec ? '' : ' locked')}><div className="row">
                <span className="sicon"><SubjectIcon code={r.subject.code} /></span>
                <div className="grow"><b>{r.class}</b><div className="meta"><span>{r.subject.name}</span>
                  {dec ? <Badge tone="pend">Declined</Badge> : <Badge tone="warn">Waiting for college admin</Badge>}</div>
                  {dec && r.note && <div className="muted small">{r.note}</div>}</div>
                {dec && <button className="ghost sm" onClick={() => dismiss(r.id)}>Dismiss</button>}
              </div></div>
            );
          })}
        </>
      )}
      <AlertsCard teacher />
      {adding && <AddSubject list={list} onClose={() => setAdding(false)}
        onDone={(r) => { toast(`${r.subject.name} requested for ${r.class}. Waiting for the college admin.`); reload(); }} />}
    </>
  );
}

function AddSubject({ list, onClose, onDone }: { list: Assignment[]; onClose: () => void; onDone: (r: Request) => void }) {
  const classes = list.filter((a, i) => list.findIndex((b) => b.classId === a.classId) === i);
  const [classId, setClassId] = useState(classes[0]?.classId || '');
  const [rows, setRows] = useState<CatalogueRow[] | null>(null);
  const [pick, setPick] = useState('');
  const cls = classes.find((c) => c.classId === classId);
  useEffect(() => {
    if (!cls) return;
    setRows(null); setPick('');
    get<CatalogueRow[]>(`catalogue?grade=${parseInt(cls.grade, 10)}&classId=${encodeURIComponent(cls.classId)}`).then(setRows, () => setRows([]));
  }, [classId]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!classes.length) return <Sheet title="Add a subject" confirm="OK" onClose={onClose} onConfirm={() => {}}>You need at least one class before you can add a subject.</Sheet>;
  return (
    <Sheet title="Add a subject" confirm="Send request" onClose={onClose}
      onConfirm={async () => {
        if (!pick) throw new Error('Choose a subject.');
        onDone(await post<Request>('teacher/subject-requests', { classId, subject: pick }));
      }}>
      <p className="muted small" style={{ marginTop: 0 }}>Your college admin approves the request. Subjects without lessons yet show as “Coming soon”.</p>
      <label className="field" htmlFor="as-c">Class</label>
      <select id="as-c" value={classId} onChange={(e) => setClassId(e.target.value)}>
        {classes.map((c) => <option key={c.classId} value={c.classId}>{c.class}</option>)}
      </select>
      <fieldset className="choices"><legend className="field">Subject</legend>
        {!rows ? <span className="muted small">Loading…</span> : rows.map((r) => {
          const mine = list.some((a) => a.classId === classId && a.subjectCode === r.code), has = mine || r.inClass;
          return (
            <label key={r.code} className={'choice' + (has ? ' locked' : '')}>
              <input type="radio" name="as-sub" value={r.code} disabled={has} checked={pick === r.code} onChange={() => setPick(r.code)} />
              <SubjectIcon code={r.code} sm /><span className="grow">{r.name}</span>
              {mine ? <Badge tone="ok">You teach this</Badge> : has ? <Badge tone="neutral">Already taught here</Badge> : r.status !== 'live' && <Badge tone="neutral">Coming soon</Badge>}
            </label>
          );
        })}
      </fieldset>
    </Sheet>
  );
}

import { useMemo, useState } from 'react';
import { get, post, type Clearance } from '../../lib/api';
import { dayName, initials, todayLong, when } from '../../lib/format';
import { useLoad } from '../../lib/useLoad';
import { Badge, ErrorCard, Icon, OfflineBanner, PhoneInput, Sheet, Skeleton, Stat, useToast } from '../../ui';
import type { Assignment } from './TeacherHome';

interface Student { id: string; name: string; roll: string; status: string | null; parent: { name: string; phone: string }; whatsappFailed: boolean }
interface ClassData {
  assignment: Assignment; date: string; submitted: boolean; topic: string | null;
  lessons: { id: string; topic: string; title: string }[]; students: Student[]; clearances: Clearance[];
}
const REASONS = ['Medical certificate provided', 'On official college duty', 'Covered the topic with the teacher in person'];

export default function ClassPage({ args }: { args: string[] }) {
  const aid = args[0] || '';
  const { data, error, reload, setData } = useLoad(() => get<ClassData>('teacher/assignments/' + encodeURIComponent(aid)), [aid]);
  const back = <div className="crumbs"><a href="#/teacher"><Icon name="back" sm />My classes</a></div>;
  if (error) return <>{back}<ErrorCard error={error} onRetry={reload} /></>;
  if (!data) return <Skeleton />;
  if (!data.lessons.length) {
    return (
      <>{back}<p className="muted" style={{ margin: 0 }}>{data.assignment.subject}</p><h1>{data.assignment.class}</h1>
        <div className="card soon-card"><Icon name="clock" /><div><b>{data.assignment.subject} lessons are coming soon</b>
          <div className="muted small">Attendance with missed-lesson clearance starts when the first {data.assignment.subject} lesson is approved. {data.students.length} students are in this class.</div></div></div></>
    );
  }
  return <Roster key={data.date + data.submitted + data.clearances.length} d={data} aid={aid} reload={reload} setData={setData} back={back} />;
}

function Roster({ d, aid, reload, setData, back }: { d: ClassData; aid: string; reload: () => void; setData: (x: ClassData) => void; back: React.ReactNode }) {
  const toast = useToast();
  const initial = useMemo(() => Object.fromEntries(d.students.map((s) => [s.id, s.status || 'present'])), [d]);
  const [marks, setMarks] = useState<Record<string, string>>(initial);
  const [topic, setTopic] = useState(d.topic || d.lessons[0].id);
  const [saving, setSaving] = useState(false);
  const [override, setOverride] = useState<Clearance | null>(null);
  const [phoneFor, setPhoneFor] = useState<Student | null>(null);
  const saved = JSON.stringify([d.topic || d.lessons[0].id, initial]);
  const dirty = !d.submitted || JSON.stringify([topic, marks]) !== saved;
  const absent = Object.values(marks).filter((v) => v === 'absent').length;
  const pending = d.clearances.filter((c) => c.status === 'pending');
  const clear = [...d.clearances].sort((a, b) => (a.status === 'pending' ? 0 : 1) - (b.status === 'pending' ? 0 : 1));
  const today = d.clearances.filter((c) => c.whatsapp), todo = today.filter((c) => !c.whatsapp!.notifiedAt);

  async function submit() {
    setSaving(true);
    try {
      const r = await post<{ alertsSent: number }>(`teacher/assignments/${aid}/attendance`, { lesson: topic, statuses: marks });
      toast('Attendance saved.' + (r.alertsSent ? ` ${r.alertsSent} parent${r.alertsSent > 1 ? 's' : ''} alerted in the app. Tell them on WhatsApp too.` : ''));
      reload();
    } catch (e) { toast((e as Error).message); setSaving(false); }
  }
  function sentOnWhatsApp(c: Clearance) {
    post<{ notifiedAt: string }>(`teacher/clearances/${c.id}/whatsapp-sent`).then((r) => {
      setData({ ...d, clearances: d.clearances.map((x) => (x.id === c.id && x.whatsapp ? { ...x, whatsapp: { ...x.whatsapp, notifiedAt: r.notifiedAt } } : x)) });
    }, (e) => toast(e.message));
  }

  return (
    <>
      <OfflineBanner />{back}
      <p className="muted" style={{ margin: 0 }}>{todayLong()} · {d.assignment.subject}</p><h1>{d.assignment.class}</h1>
      <div className="stats">
        <Stat value={d.students.length - absent} label="Present" tone="ok" />
        <Stat value={absent} label="Absent" />
        <Stat value={pending.length} label="Pending" tone={pending.length ? 'warn' : undefined} />
      </div>
      {today.length > 0 && (todo.length === 0
        ? <div className="card ok-card small row"><Icon name="check" sm /><span>All parents of today’s absent students have been told on WhatsApp.</span></div>
        : (
          <div className="card wa-card">
            <div className="row between"><b>Tell parents on WhatsApp</b><Badge tone="warn">{todo.length} not told yet</Badge></div>
            <p className="muted small" style={{ margin: '4px 0 8px' }}>Free: each button opens your WhatsApp with the message ready. Tap Send there. Parents with the app also got an alert.</p>
            {todo.map((c) => (
              <div key={c.id} className="att"><span className="avatar">{initials(c.student)}</span>
                <div className="grow"><b>{c.whatsapp!.parent}</b><div className="muted small">parent of {c.student}</div></div>
                <a className="btn sm wa-btn" target="_blank" rel="noopener" onClick={() => sentOnWhatsApp(c)}
                  href={`https://wa.me/${c.whatsapp!.phone}?text=${encodeURIComponent(c.whatsapp!.text)}`}><Icon name="chat" sm />Send on WhatsApp</a>
              </div>
            ))}
          </div>
        ))}
      <div className="class-grid">
        <section className="col-att">
          <h2 className="row between">{d.submitted ? 'Today’s attendance' : 'Take attendance'}{d.submitted && <Badge tone="ok" icon="check">Submitted</Badge>}</h2>
          <label className="field" htmlFor="tp" style={{ marginTop: 0 }}>Topic taught today</label>
          <select id="tp" value={topic} onChange={(e) => setTopic(e.target.value)}>
            {d.lessons.map((l) => <option key={l.id} value={l.id}>{l.topic} {l.title}</option>)}
          </select>
          <p className="muted small">Absent students get this topic as their missed lecture, and their parents get an alert.</p>
          <div className="card" style={{ padding: '4px 12px' }}>
            {d.students.map((s) => {
              const st = marks[s.id];
              return (
                <div key={s.id} className={'att' + (st === 'absent' ? ' is-absent' : '')}>
                  <span className="avatar">{initials(s.name)}</span>
                  <div className="grow"><b>{s.name}</b>
                    <div className="muted small who"><span>{s.roll} · {s.parent.name}</span>
                      {s.whatsappFailed && <span className="badge warn" title="WhatsApp failed; the alert went by SMS">SMS used</span>}
                      <button className="ghost sm inline" aria-label={'Edit parent number for ' + s.name} title="Edit parent number" onClick={() => setPhoneFor(s)}><Icon name="edit" sm /></button>
                    </div></div>
                  <div className="pa" role="group" aria-label={s.name}>
                    <button className="p" aria-pressed={st === 'present'} aria-label="Present" onClick={() => setMarks({ ...marks, [s.id]: 'present' })}>P</button>
                    <button className="a" aria-pressed={st === 'absent'} aria-label="Absent" onClick={() => setMarks({ ...marks, [s.id]: 'absent' })}>A</button>
                  </div>
                </div>
              );
            })}
          </div>
          <div className="sticky-actions">
            <button onClick={() => setMarks(Object.fromEntries(d.students.map((s) => [s.id, 'present'])))}>All present</button>
            <button className="primary grow" disabled={!dirty || saving} onClick={submit}>
              {saving ? 'Saving…' : !dirty ? <><Icon name="check" sm />Saved</> : (d.submitted ? 'Save changes' : 'Submit attendance') + (absent ? ` · ${absent} absent` : '')}
            </button>
          </div>
        </section>
        <section className={'col-clear' + (clear.length ? '' : ' empty')}>
          <h2>Class clearance</h2>
          {clear.length ? clear.map((c) => {
            const ok = c.status === 'cleared';
            return (
              <div key={c.id} className="card tight">
                <div className="row"><span className="avatar">{initials(c.student)}</span>
                  <div className="grow"><b>{c.student}</b>
                    <div className="muted small">{c.lesson.topic} {c.lesson.title} · absent {dayName(c.date)}</div>
                    <div className="muted small">{ok ? (c.clearedBy === 'teacher' ? 'Cleared by teacher: ' + c.overrideReason : `Passed ${c.best}/5, ${when(c.clearedAt)}`)
                      : c.lastAttempt ? `Last attempt ${when(c.lastAttempt)} · best ${c.best}/5 · ${c.attempts} attempt${c.attempts > 1 ? 's' : ''}` : 'Not started yet'}</div></div>
                  {ok ? <Badge tone="ok" icon="check">Cleared</Badge> : <Badge tone="pend" icon="cross">Pending</Badge>}
                </div>
                {!ok && <div style={{ textAlign: 'right' }}><button className="ghost sm" onClick={() => setOverride(c)}>Clear manually…</button></div>}
              </div>
            );
          }) : <div className="card muted small">No absences yet. When you mark a student absent, their catch-up progress appears here.</div>}
        </section>
      </div>
      {override && <OverrideSheet c={override} onClose={() => setOverride(null)} onDone={() => { toast(override.student + ' cleared. Parent notified.'); reload(); }} />}
      {phoneFor && <PhoneSheet s={phoneFor} onClose={() => setPhoneFor(null)}
        onDone={(parent) => { toast('Parent number updated'); setData({ ...d, students: d.students.map((x) => (x.id === phoneFor.id ? { ...x, parent } : x)) }); }} />}
    </>
  );
}

function OverrideSheet({ c, onClose, onDone }: { c: Clearance; onClose: () => void; onDone: () => void }) {
  const [reason, setReason] = useState(REASONS[0]);
  const [other, setOther] = useState('');
  return (
    <Sheet title={`Clear ${c.student} manually`} confirm="Clear for class" onClose={onClose}
      onConfirm={async () => {
        const r = reason === 'Other' ? other.trim() : reason;
        if (r.length < 3) throw new Error('Write a short reason, for example “Medical certificate provided”.');
        await post(`teacher/clearances/${c.id}/override`, { reason: r }); onDone();
      }}>
      <p className="muted small" style={{ marginTop: 0 }}>{c.lesson.topic} {c.lesson.title}. The reason is saved with the record, and the parent gets an alert.</p>
      <fieldset className="choices"><legend className="field">Reason</legend>
        {[...REASONS, 'Other'].map((r) => (
          <label key={r} className="choice"><input type="radio" name="rsn" checked={reason === r} onChange={() => setReason(r)} /><span>{r}</span></label>
        ))}
      </fieldset>
      {reason === 'Other' && <textarea rows={2} maxLength={200} placeholder="Write the reason" aria-label="Other reason" autoFocus value={other} onChange={(e) => setOther(e.target.value)} />}
    </Sheet>
  );
}

function PhoneSheet({ s, onClose, onDone }: { s: Student; onClose: () => void; onDone: (p: { name: string; phone: string }) => void }) {
  const [v, setV] = useState(s.parent.phone.replace(/^\+92/, ''));
  return (
    <Sheet title="Parent’s mobile number" confirm="Save number" onClose={onClose}
      onConfirm={async () => {
        const n = v.replace(/^0/, '');
        if (!/^3\d{9}$/.test(n)) throw new Error('Enter a 10-digit mobile number starting with 3.');
        const r = await post<{ parent: { name: string; phone: string } }>(`teacher/students/${s.id}/parent-phone`, { phone: '0' + n });
        onDone(r.parent);
      }}>
      <p className="muted small" style={{ marginTop: 0 }}>{s.parent.name}, parent of {s.name}. Absence alerts go to this number.</p>
      <PhoneInput id="pp-in" label="Mobile number" value={v} onChange={setV} />
    </Sheet>
  );
}

