import { useState } from 'react';
import { post } from '../../lib/api';
import { prettyPhone } from '../../lib/format';
import { Icon, Tabs, useToast } from '../../ui';

const TEMPLATES = {
  students: 'class_grade,class_stream,class_section,roll_number,student_name,student_gender,student_phone,parent_name,parent_phone\n' +
    '11th,Pre-Medical,A,11A-21,Imran Ali,male,03001234567,Mr. Ali Khan,03007654321\n',
  teachers: 'teacher_name,teacher_phone,teacher_gender,subject,class_grade,class_stream,class_section\n' +
    'Ms. Hira Saleem,03001112233,female,English,11th,Pre-Medical,A\n',
};
interface Report {
  id: number; kind: string; counts: { rows: number; ok: number; errors: number };
  errors: { row: number; message: string }[];
  preview: { row: number; name: string; phone: string; class: string; roll?: string; parentName?: string; parentExists?: boolean; subject?: string }[];
}
const plural = (n: number, word: string) => `${n} ${n === 1 ? word.replace(/s$/, '') : word}`;

/** Roster import (F5 in F22): check first, then commit all-or-nothing. */
export default function Import({ args }: { args: string[] }) {
  const kind = args[0] === 'teachers' ? 'teachers' : 'students';
  const toast = useToast();
  const [csv, setCsv] = useState('');
  const [report, setReport] = useState<Report | null>(null);
  const [done, setDone] = useState<Record<string, number> | null>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  async function check() {
    setBusy(true); setError(''); setDone(null);
    try { setReport(await post<Report>('admin/imports', { kind, csv })); } catch (e) { setError((e as Error).message); setReport(null); }
    setBusy(false);
  }
  async function commit() {
    if (!report) return;
    setBusy(true);
    try { const r = await post<{ created: Record<string, number> }>(`admin/imports/${report.id}/commit`); setDone(r.created); setReport(null); setCsv(''); }
    catch (e) { toast((e as Error).message); }
    setBusy(false);
  }
  const ok = report && !report.errors.length;
  return (
    <>
      <h1>Import</h1>
      <p className="muted">Add a whole class, or all your teachers, from a spreadsheet saved as CSV.</p>
      <Tabs label="Import" current={kind} items={[{ key: 'students', href: '#/import/students', label: 'Students and parents' }, { key: 'teachers', href: '#/import/teachers', label: 'Teachers' }]} />
      <div className="card">
        <ol className="steps">
          <li><a href={'data:text/csv;charset=utf-8,' + encodeURIComponent(TEMPLATES[kind])} download={`edusaas-${kind}-template.csv`}>Download the template</a> and fill it in (Excel: File → Save as → CSV).</li>
          <li>Choose the file, or paste its contents below.</li>
          <li><b>Check file</b>. Nothing is saved until you press <b>Import</b>.</li>
        </ol>
        <input type="file" accept=".csv,text/csv" aria-label="CSV file" onChange={(e) => {
          const f = e.target.files?.[0]; if (!f) return;
          const rd = new FileReader(); rd.onload = () => setCsv(String(rd.result)); rd.readAsText(f);
        }} />
        <textarea rows={6} placeholder={TEMPLATES[kind].split('\n')[0]} aria-label="CSV contents" style={{ marginTop: 8 }} value={csv} onChange={(e) => setCsv(e.target.value)} />
        <button className="primary block" style={{ marginTop: 10 }} disabled={busy} onClick={check}>{busy && !report ? 'Checking…' : 'Check file'}</button>
      </div>
      {error && <div className="card alert-card small">{error}</div>}
      {done && <div className="card ok-card"><b><Icon name="check" sm /> Imported</b>
        <div className="small">{Object.entries(done).map(([k, v]) => plural(v, k)).join(', ')} created. They can sign in with their numbers now.</div></div>}
      {report && (
        <>
          <div className={'card ' + (ok ? 'ok-card' : 'alert-card')}>
            <b>{ok ? `Ready to import ${plural(report.counts.ok, 'rows')}` : `${plural(report.counts.errors, 'rows')} ${report.counts.errors === 1 ? 'needs' : 'need'} fixing`}</b>
            <div className="small">{report.counts.rows} rows checked · {report.counts.ok} OK · {report.counts.errors} with errors</div>
          </div>
          {report.errors.length > 0 && (
            <>
              <h2>Fix these rows, then check again</h2>
              <div className="card" style={{ padding: '4px 12px' }}>
                {report.errors.map((e) => <div key={e.row} className="att"><span className="chip" style={{ background: 'var(--bad-bg)', color: 'var(--bad)' }}>{e.row}</span>
                  <div className="grow small">{e.message}</div></div>)}
              </div>
              <p className="muted small">Row numbers match your spreadsheet (row 1 is the header).</p>
            </>
          )}
          {report.preview.length > 0 && (
            <>
              <h2>{ok ? 'Will be added' : 'Rows that are OK'}</h2>
              <div className="card" style={{ padding: '4px 12px' }}>
                {report.preview.map((x) => <div key={x.row} className="att"><span className="chip">{x.row}</span>
                  <div className="grow small"><b>{x.name}</b> · {prettyPhone(x.phone)}<br /><span className="muted">{kind === 'students'
                    ? `${x.class}, roll ${x.roll} · parent ${x.parentName}${x.parentExists ? ' (already registered)' : ''}` : `${x.subject} · ${x.class}`}</span></div></div>)}
              </div>
            </>
          )}
          {ok && <button className="primary block" disabled={busy} onClick={commit}>{busy ? 'Importing…' : `Import ${plural(report.counts.ok, 'rows')}`}</button>}
        </>
      )}
    </>
  );
}

