import { useState } from 'react';
import { useSession } from '../../App';
import { get, post } from '../../lib/api';
import { todayLong, when } from '../../lib/format';
import { useLoad } from '../../lib/useLoad';
import { Badge, ErrorCard, OfflineBanner, Sheet, Skeleton, Stat, SubjectIcon, useToast } from '../../ui';

export interface AuditRow { id: number; action: string; type: string; summary: string; actor: string | null; at: string }
interface Overview {
  college: string; counts: { teachers: number; students: number; parents: number; classes: number };
  requests: { id: number; class: string; teacher: string; createdAt: string; subject: { code: string; name: string; status: string } }[];
  activity: AuditRow[];
}

export function ActivityList({ rows }: { rows: AuditRow[] }) {
  if (!rows.length) return <div className="card muted small">No activity yet.</div>;
  return (
    <div className="card" style={{ padding: '4px 12px' }}>
      {rows.map((a) => <div key={a.id} className="att"><div className="grow"><div>{a.summary}</div>
        <div className="muted small">{(a.actor || 'EduSaas team') + ' · ' + when(a.at)}</div></div></div>)}
    </div>
  );
}

export default function AdminHome() {
  const { me } = useSession();
  const toast = useToast();
  const { data: d, error, reload } = useLoad(() => get<Overview>('admin/overview'));
  const [declining, setDeclining] = useState<number | null>(null);
  const [note, setNote] = useState('');
  if (error) return <ErrorCard error={error} onRetry={reload} />;
  if (!d) return <Skeleton rows={3} />;
  async function decide(id: number, approve: boolean, n = '') {
    const r = await post<{ subject: { name: string }; class: string }>(`admin/subject-requests/${id}/decide`, { approve, note: n });
    toast(approve ? `${r.subject.name} added to ${r.class}.` : 'Request declined. The teacher will see your note.');
    reload();
  }
  return (
    <>
      <OfflineBanner />
      <p className="muted" style={{ margin: 0 }}>{todayLong()}</p><h1>{d.college}</h1><p className="muted">College admin · {me.name}</p>
      <div className="stats four">
        <Stat value={d.counts.students} label="Students" href="#/people/student" />
        <Stat value={d.counts.teachers} label="Teachers" href="#/people/teacher" />
        <Stat value={d.counts.parents} label="Parents" href="#/people/parent" />
        <Stat value={d.counts.classes} label="Classes" href="#/classes" />
      </div>
      <h2>Subject requests {d.requests.length > 0 && <Badge tone="warn">{d.requests.length} waiting</Badge>}</h2>
      {d.requests.length ? d.requests.map((r) => (
        <div key={r.id} className="card tight">
          <div className="row"><span className="sicon"><SubjectIcon code={r.subject.code} /></span>
            <div className="grow"><b>{r.subject.name} for {r.class}</b>
              <div className="muted small">Asked by {r.teacher} · {when(r.createdAt)}{r.subject.status === 'live' ? '' : ' · no lessons yet (Coming soon)'}</div></div></div>
          <div className="row" style={{ justifyContent: 'flex-end', marginTop: 8 }}>
            <button className="sm" onClick={() => { setNote(''); setDeclining(r.id); }}>Decline…</button>
            <button className="sm primary" onClick={() => decide(r.id, true).catch((e) => toast(e.message))}>Approve</button>
          </div>
        </div>
      )) : <div className="card muted small">No requests waiting. Teachers ask for subjects from “My classes → Add subject”.</div>}
      <h2 className="row between">Recent activity <a className="small" href="#/activity">See all</a></h2>
      <ActivityList rows={d.activity} />
      {declining != null && (
        <Sheet title="Decline this request" confirm="Decline" onClose={() => setDeclining(null)} onConfirm={() => decide(declining, false, note.trim())}>
          <label className="field" htmlFor="dn">Note for the teacher (optional)</label>
          <textarea id="dn" rows={3} maxLength={200} placeholder="For example: Ms. Hira already teaches this class" value={note} onChange={(e) => setNote(e.target.value)} />
        </Sheet>
      )}
    </>
  );
}

import { get } from '../../lib/api';
import { useLoad } from '../../lib/useLoad';
import { ErrorCard, Icon, Skeleton } from '../../ui';
import { ActivityList, type AuditRow } from './AdminHome';

export default function Activity() {
  const { data, error, reload } = useLoad(() => get<AuditRow[]>('admin/audit'));
  if (error) return <ErrorCard error={error} onRetry={reload} />;
  if (!data) return <Skeleton rows={3} />;
  return (
    <>
      <div className="crumbs"><a href="#/admin"><Icon name="back" sm />Home</a></div>
      <h1>Activity log</h1>
      <p className="muted">Every change in your college: who did it and when. Phone numbers are partly hidden.</p>
      <ActivityList rows={data} />
    </>
  );
}

import { useEffect, useState } from 'react';
import { get, post } from '../../lib/api';
import { initials, prettyPhone } from '../../lib/format';
import { useLoad } from '../../lib/useLoad';
import { Badge, ErrorCard, Icon, PhoneInput, Sheet, Skeleton, Tabs, useToast } from '../../ui';

export interface Person {
  id: string; name: string; role: 'student' | 'teacher' | 'parent'; phone: string; gender: string; active: boolean;
  class?: string; classId?: string; roll?: string; parent?: { id: string; name: string; phone: string };
  assignments?: string[]; children?: string[];
}
export interface ClassRow { id: string; name: string; grade: string; section: string; gender: string; academicYear: string; students: number;
  assignments: { id: number; teacher: string; teacherId: string; subject: string; subjectCode: string }[] }
const ROLES: [Person['role'], string][] = [['student', 'Students'], ['teacher', 'Teachers'], ['parent', 'Parents']];
const digits = (v: string) => v.replace(/\D/g, '').replace(/^0/, '');

export default function People({ args }: { args: string[] }) {
  const role = (ROLES.some(([r]) => r === args[0]) ? args[0] : 'student') as Person['role'];
  const [q, setQ] = useState(''), [query, setQuery] = useState('');
  useEffect(() => { const id = window.setTimeout(() => setQuery(q.trim()), 300); return () => window.clearTimeout(id); }, [q]);
  const { data, error, reload } = useLoad(() => get<Person[]>(`admin/people?role=${role}${query ? '&q=' + encodeURIComponent(query) : ''}`), [role, query]);
  const classes = useLoad(() => get<ClassRow[]>('admin/classes'));
  const [editing, setEditing] = useState<Person | 'new' | null>(null);
  const toast = useToast();
  const label = { student: 'student', teacher: 'teacher', parent: 'parent' }[role];
  return (
    <>
      <h1 className="row between">People<button className="sm primary" onClick={() => {
        if (role === 'student' && classes.data && !classes.data.length) toast('Create a class first, under Classes.');
        else setEditing('new');
      }}><Icon name="plus2" sm />Add</button></h1>
      <Tabs label="People" current={role} items={ROLES.map(([r, l]) => ({ key: r, href: '#/people/' + r, label: l }))} />
      <input type="text" placeholder="Search by name, phone or roll number" aria-label="Search" value={q} onChange={(e) => setQ(e.target.value)} />
      <div style={{ marginTop: 10 }}>
        {error ? <ErrorCard error={error} onRetry={reload} /> : !data ? <Skeleton /> : data.length ? (
          <>
            <div className="card" style={{ padding: '4px 8px' }}>
              {data.map((p) => (
                <button key={p.id} className={'person' + (p.active ? '' : ' off')} onClick={() => setEditing(p)}>
                  <span className="avatar">{initials(p.name)}</span>
                  <span className="grow"><b>{p.name}</b>{!p.active && <> <Badge tone="pend">Suspended</Badge></>}
                    <span className="muted small">{prettyPhone(p.phone)} · {p.role === 'student' ? `${p.class} · Roll ${p.roll} · parent ${p.parent?.name}`
                      : p.role === 'teacher' ? (p.assignments?.length ? p.assignments.join(', ') : 'No classes yet')
                      : (p.children?.length ? 'Parent of ' + p.children.join(', ') : 'No children linked')}</span></span>
                  <Icon name="chev" sm />
                </button>
              ))}
            </div>
            <p className="muted small" style={{ textAlign: 'center' }}>{data.length} shown</p>
          </>
        ) : <div className="card muted small">{query ? `Nobody matches “${query}”.` : 'Nobody here yet. Use Add, or import a file.'}</div>}
      </div>
      {editing === 'new' && <AddPerson role={role} label={label} classes={classes.data || []} onClose={() => setEditing(null)}
        onDone={(p) => { toast(p.name + ' added.'); reload(); }} />}
      {editing && editing !== 'new' && <EditPerson p={editing} classes={classes.data || []} onClose={() => setEditing(null)}
        onDone={(msg) => { toast(msg); reload(); }} />}
    </>
  );
}

function AddPerson({ role, label, classes, onClose, onDone }: { role: Person['role']; label: string; classes: ClassRow[]; onClose: () => void; onDone: (p: Person) => void }) {
  const [f, setF] = useState({ name: '', phone: '', gender: role === 'parent' ? 'female' : 'male', classId: classes[0]?.id || '', roll: '', parentPhone: '', parentName: '' });
  const set = (k: keyof typeof f) => (e: { target: { value: string } }) => setF({ ...f, [k]: e.target.value });
  return (
    <Sheet title={'Add a ' + label} confirm={'Add ' + label} onClose={onClose}
      onConfirm={async () => onDone(await post<Person>('admin/people', {
        role, name: f.name.trim(), phone: digits(f.phone), gender: f.gender,
        ...(role === 'student' ? { classId: f.classId, roll: f.roll.trim(), parentPhone: digits(f.parentPhone), parentName: f.parentName.trim() } : {}),
      }))}>
      <label className="field" htmlFor="pn">Full name</label><input id="pn" type="text" value={f.name} onChange={set('name')} />
      <PhoneInput id="pp" label="Mobile number" value={f.phone} onChange={(v) => setF({ ...f, phone: v })} />
      <label className="field" htmlFor="pg">Gender</label>
      <select id="pg" value={f.gender} onChange={set('gender')}><option value="male">Male</option><option value="female">Female</option></select>
      {role === 'student' && (
        <>
          <label className="field" htmlFor="pc">Class</label>
          <select id="pc" value={f.classId} onChange={set('classId')}>{classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
          <label className="field" htmlFor="pr">Roll number</label><input id="pr" type="text" placeholder="e.g. 11A-07" value={f.roll} onChange={set('roll')} />
          <div className="sheet-sub">Parent</div>
          <PhoneInput id="ppp" label="Parent’s mobile number" value={f.parentPhone} onChange={(v) => setF({ ...f, parentPhone: v })} />
          <label className="field" htmlFor="ppn">Parent’s full name</label>
          <input id="ppn" type="text" placeholder="Leave blank if the parent is already registered" value={f.parentName} onChange={set('parentName')} />
        </>
      )}
      <p className="muted small">They sign in with this number. Nobody else can use it.</p>
    </Sheet>
  );
}

function EditPerson({ p, classes, onClose, onDone }: { p: Person; classes: ClassRow[]; onClose: () => void; onDone: (msg: string) => void }) {
  const [f, setF] = useState({ name: p.name, phone: p.phone.replace(/^\+92/, ''), classId: p.classId || '', roll: p.roll || '', reason: '' });
  const [error, setError] = useState('');
  async function setActive(active: boolean) {
    setError('');
    try {
      await post('admin/people/' + p.id, active ? { active } : { active, reason: f.reason.trim() });
      onClose(); onDone(p.name + (active ? ' reactivated.' : ' suspended.'));
    } catch (e) { setError((e as Error).message); }
  }
  return (
    <Sheet title={p.name} confirm="Save changes" onClose={onClose}
      onConfirm={async () => {
        await post('admin/people/' + p.id, { name: f.name.trim(), phone: digits(f.phone), ...(p.role === 'student' ? { classId: f.classId, roll: f.roll.trim() } : {}) });
        onDone('Saved.');
      }}>
      <label className="field" htmlFor="pn">Full name</label><input id="pn" type="text" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} />
      <PhoneInput id="pp" label="Mobile number" value={f.phone} onChange={(v) => setF({ ...f, phone: v })} />
      {p.role === 'student' && (
        <>
          <label className="field" htmlFor="pc">Class</label>
          <select id="pc" value={f.classId} onChange={(e) => setF({ ...f, classId: e.target.value })}>{classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
          <label className="field" htmlFor="pr">Roll number</label><input id="pr" type="text" value={f.roll} onChange={(e) => setF({ ...f, roll: e.target.value })} />
          <p className="muted small">Parent: {p.parent?.name}, {prettyPhone(p.parent?.phone)}. Open the Parents tab to change the parent’s details.</p>
        </>
      )}
      <div className="sheet-sub">Account</div>
      {p.active ? (
        <>
          <p className="muted small" style={{ margin: '4px 0' }}>Suspending signs them out and stops them signing in. Records are kept.</p>
          <label className="field" htmlFor="sr">Reason for suspending</label>
          <input id="sr" type="text" placeholder="e.g. Left the college" value={f.reason} onChange={(e) => setF({ ...f, reason: e.target.value })} />
          <button className="block" style={{ marginTop: 8, color: 'var(--bad)' }} onClick={() => setActive(false)}>Suspend account</button>
        </>
      ) : (
        <><p className="small"><Badge tone="pend">Suspended</Badge></p><button className="block" onClick={() => setActive(true)}>Reactivate account</button></>
      )}
      {error && <p className="small err" role="alert">{error}</p>}
    </Sheet>
  );
}

import { useState } from 'react';
import { del, get, post } from '../../lib/api';
import { useLoad } from '../../lib/useLoad';
import { ErrorCard, Icon, Sheet, Skeleton, SubjectIcon, useToast } from '../../ui';
import type { ClassRow, Person } from './People';

const GENDER: Record<string, string> = { male: 'Boys', female: 'Girls', mixed: 'Mixed' };

export default function Classes() {
  const toast = useToast();
  const { data, error, reload } = useLoad(() => get<ClassRow[]>('admin/classes'));
  const [adding, setAdding] = useState(false);
  const [assignTo, setAssignTo] = useState<ClassRow | null>(null);
  const [removing, setRemoving] = useState<ClassRow['assignments'][number] | null>(null);
  if (error) return <ErrorCard error={error} onRetry={reload} />;
  if (!data) return <Skeleton />;
  return (
    <>
      <h1 className="row between">Classes<button className="sm primary" onClick={() => setAdding(true)}><Icon name="plus2" sm />New class</button></h1>
      {data.length ? (
        <div className="lesson-list">
          {data.map((c) => (
            <div key={c.id} className="card">
              <div className="row"><span className="chip">{c.section}</span>
                <div className="grow"><b>{c.name}</b><div className="muted small">{c.academicYear} · {GENDER[c.gender]} · {c.students} students</div></div></div>
              <div className="muted small" style={{ margin: '10px 0 4px' }}>Teachers</div>
              {c.assignments.length ? c.assignments.map((a) => (
                <div key={a.id} className="asg"><SubjectIcon code={a.subjectCode} sm /><span className="grow"><b>{a.subject}</b> · {a.teacher}</span>
                  <button className="ghost sm inline" aria-label={`Remove ${a.teacher} from ${a.subject}`} onClick={() => setRemoving(a)}><Icon name="cross" sm /></button></div>
              )) : <p className="muted small" style={{ margin: 0 }}>No teachers yet.</p>}
              <button className="sm" style={{ marginTop: 8 }} onClick={() => setAssignTo(c)}><Icon name="plus2" sm />Assign teacher</button>
            </div>
          ))}
        </div>
      ) : <div className="card muted small">No classes yet. Create one, then add students.</div>}
      {adding && <NewClass onClose={() => setAdding(false)} onDone={(n) => { toast(n + ' created.'); reload(); }} />}
      {assignTo && <Assign c={assignTo} onClose={() => setAssignTo(null)} onDone={() => { toast('Teacher assigned.'); reload(); }} />}
      {removing && (
        <Sheet title="Remove this teacher?" confirm="Remove" onClose={() => setRemoving(null)}
          onConfirm={async () => { await del('admin/assignments/' + removing.id); toast('Removed.'); reload(); }}>
          <p className="muted small" style={{ marginTop: 0 }}>{removing.teacher} will no longer teach {removing.subject}. Attendance and clearances already recorded are kept.</p>
        </Sheet>
      )}
    </>
  );
}

function NewClass({ onClose, onDone }: { onClose: () => void; onDone: (name: string) => void }) {
  const [f, setF] = useState({ grade: '11th', stream: '', section: '', gender: 'male', academicYear: '2026-2027' });
  const set = (k: keyof typeof f) => (e: { target: { value: string } }) => setF({ ...f, [k]: e.target.value });
  return (
    <Sheet title="New class" confirm="Create class" onClose={onClose}
      onConfirm={async () => onDone((await post<ClassRow>('admin/classes', { ...f, stream: f.stream.trim(), section: f.section.trim() })).name)}>
      <label className="field" htmlFor="cg">Grade</label><select id="cg" value={f.grade} onChange={set('grade')}><option>11th</option><option>12th</option></select>
      <label className="field" htmlFor="cs">Stream</label><input id="cs" type="text" placeholder="e.g. Pre-Medical" value={f.stream} onChange={set('stream')} />
      <label className="field" htmlFor="cx">Section</label><input id="cx" type="text" placeholder="e.g. A" value={f.section} onChange={set('section')} />
      <label className="field" htmlFor="cgen">Students</label>
      <select id="cgen" value={f.gender} onChange={set('gender')}><option value="male">Boys</option><option value="female">Girls</option><option value="mixed">Mixed</option></select>
      <label className="field" htmlFor="cy">Academic year</label><input id="cy" type="text" value={f.academicYear} onChange={set('academicYear')} />
    </Sheet>
  );
}

function Assign({ c, onClose, onDone }: { c: ClassRow; onClose: () => void; onDone: () => void }) {
  const { data } = useLoad(() => Promise.all([get<Person[]>('admin/people?role=teacher'), get<{ code: string; name: string; status: string }[]>('catalogue?grade=' + parseInt(c.grade, 10))]));
  const teachers = data ? data[0].filter((x) => x.active) : [];
  const [teacher, setTeacher] = useState(''), [subject, setSubject] = useState('');
  return (
    <Sheet title={'Assign a teacher to ' + c.name} confirm="Assign" onClose={onClose} busy={!data}
      onConfirm={async () => {
        const tid = teacher || teachers[0]?.id, sub = subject || data?.[1][0]?.code;
        if (!tid) throw new Error('Add a teacher first, under People.');
        await post('admin/assignments', { teacherId: tid, classId: c.id, subject: sub }); onDone();
      }}>
      {!data ? <span className="muted small">Loading…</span> : (
        <>
          <label className="field" htmlFor="at">Teacher</label>
          <select id="at" value={teacher || teachers[0]?.id || ''} onChange={(e) => setTeacher(e.target.value)}>{teachers.map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select>
          <label className="field" htmlFor="as">Subject</label>
          <select id="as" value={subject || data[1][0]?.code || ''} onChange={(e) => setSubject(e.target.value)}>
            {data[1].map((x) => <option key={x.code} value={x.code}>{x.name}{x.status === 'live' ? '' : ' (coming soon)'}</option>)}</select>
        </>
      )}
    </Sheet>
  );
}

import { useState } from 'react';
import { post } from '../../lib/api';
import { prettyPhone } from '../../lib/format';
import { Icon, Tabs, useToast } from '../../ui';

const TEMPLATES = {
  students: 'class_grade,class_stream,class_section,roll_number,student_name,student_gender,student_phone,parent_name,parent_phone\n' +
    '11th,Pre-Medical,A,11A-21,Imran Ali,male,03001234567,Mr. Ali Khan,03007654321\n',
  teachers: 'teacher_name,teacher_phone,teacher_gender,subject,class_grade,class_stream,class_section\n' +
    'Ms. Hira Saleem,03001112233,female,English,11th,Pre-Medical,A\n',
};
interface Report {
  id: number; kind: string; counts: { rows: number; ok: number; errors: number };
  errors: { row: number; message: string }[];
  preview: { row: number; name: string; phone: string; class: string; roll?: string; parentName?: string; parentExists?: boolean; subject?: string }[];
}
const plural = (n: number, word: string) => `${n} ${n === 1 ? word.replace(/s$/, '') : word}`;

/** Roster import (F5 in F22): check first, then commit all-or-nothing. */
export default function Import({ args }: { args: string[] }) {
  const kind = args[0] === 'teachers' ? 'teachers' : 'students';
  const toast = useToast();
  const [csv, setCsv] = useState('');
  const [report, setReport] = useState<Report | null>(null);
  const [done, setDone] = useState<Record<string, number> | null>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  async function check() {
    setBusy(true); setError(''); setDone(null);
    try { setReport(await post<Report>('admin/imports', { kind, csv })); } catch (e) { setError((e as Error).message); setReport(null); }
    setBusy(false);
  }
  async function commit() {
    if (!report) return;
    setBusy(true);
    try { const r = await post<{ created: Record<string, number> }>(`admin/imports/${report.id}/commit`); setDone(r.created); setReport(null); setCsv(''); }
    catch (e) { toast((e as Error).message); }
    setBusy(false);
  }
  const ok = report && !report.errors.length;
  return (
    <>
      <h1>Import</h1>
      <p className="muted">Add a whole class, or all your teachers, from a spreadsheet saved as CSV.</p>
      <Tabs label="Import" current={kind} items={[{ key: 'students', href: '#/import/students', label: 'Students and parents' }, { key: 'teachers', href: '#/import/teachers', label: 'Teachers' }]} />
      <div className="card">
        <ol className="steps">
          <li><a href={'data:text/csv;charset=utf-8,' + encodeURIComponent(TEMPLATES[kind])} download={`edusaas-${kind}-template.csv`}>Download the template</a> and fill it in (Excel: File → Save as → CSV).</li>
          <li>Choose the file, or paste its contents below.</li>
          <li><b>Check file</b>. Nothing is saved until you press <b>Import</b>.</li>
        </ol>
        <input type="file" accept=".csv,text/csv" aria-label="CSV file" onChange={(e) => {
          const f = e.target.files?.[0]; if (!f) return;
          const rd = new FileReader(); rd.onload = () => setCsv(String(rd.result)); rd.readAsText(f);
        }} />
        <textarea rows={6} placeholder={TEMPLATES[kind].split('\n')[0]} aria-label="CSV contents" style={{ marginTop: 8 }} value={csv} onChange={(e) => setCsv(e.target.value)} />
        <button className="primary block" style={{ marginTop: 10 }} disabled={busy} onClick={check}>{busy && !report ? 'Checking…' : 'Check file'}</button>
      </div>
      {error && <div className="card alert-card small">{error}</div>}
      {done && <div className="card ok-card"><b><Icon name="check" sm /> Imported</b>
        <div className="small">{Object.entries(done).map(([k, v]) => plural(v, k)).join(', ')} created. They can sign in with their numbers now.</div></div>}
      {report && (
        <>
          <div className={'card ' + (ok ? 'ok-card' : 'alert-card')}>
            <b>{ok ? `Ready to import ${plural(report.counts.ok, 'rows')}` : `${plural(report.counts.errors, 'rows')} ${report.counts.errors === 1 ? 'needs' : 'need'} fixing`}</b>
            <div className="small">{report.counts.rows} rows checked · {report.counts.ok} OK · {report.counts.errors} with errors</div>
          </div>
          {report.errors.length > 0 && (
            <>
              <h2>Fix these rows, then check again</h2>
              <div className="card" style={{ padding: '4px 12px' }}>
                {report.errors.map((e) => <div key={e.row} className="att"><span className="chip" style={{ background: 'var(--bad-bg)', color: 'var(--bad)' }}>{e.row}</span>
                  <div className="grow small">{e.message}</div></div>)}
              </div>
              <p className="muted small">Row numbers match your spreadsheet (row 1 is the header).</p>
            </>
          )}
          {report.preview.length > 0 && (
            <>
              <h2>{ok ? 'Will be added' : 'Rows that are OK'}</h2>
              <div className="card" style={{ padding: '4px 12px' }}>
                {report.preview.map((x) => <div key={x.row} className="att"><span className="chip">{x.row}</span>
                  <div className="grow small"><b>{x.name}</b> · {prettyPhone(x.phone)}<br /><span className="muted">{kind === 'students'
                    ? `${x.class}, roll ${x.roll} · parent ${x.parentName}${x.parentExists ? ' (already registered)' : ''}` : `${x.subject} · ${x.class}`}</span></div></div>)}
              </div>
            </>
          )}
          {ok && <button className="primary block" disabled={busy} onClick={commit}>{busy ? 'Importing…' : `Import ${plural(report.counts.ok, 'rows')}`}</button>}
        </>
      )}
    </>
  );
}

