// F1 parity journey on the React app at /app/: every role, the full clearance loop, plus gallery screenshots.
const { chromium } = require('playwright-core');
const { execSync } = require('child_process');
const BASE = 'http://127.0.0.1:8010';
const APP = BASE + '/app/';
const SP = 'C:/Users/USER/AppData/Local/Temp/claude/c--Users-USER-EduSaas/c157907d-778b-4123-a5ae-2e119f027594/scratchpad';
const shell = (code) => execSync(`python manage.py shell -c "${code}"`, { cwd: 'C:/Users/USER/EduSaas/backend',
  env: { ...process.env, SQLITE_PATH: SP + '/f1.sqlite3' } }).toString().trim().split('\n').pop();
const txt = async (pg, sel = '#app') => (await pg.textContent(sel)).replace(/\s+/g, ' ').trim().slice(0, 220);
const errs = [];
let ok = 0, fail = 0;
function check(name, cond, info = '') { if (cond) ok++; else fail++; console.log((cond ? 'PASS ' : 'FAIL ') + name + (cond ? '' : '  ' + info)); }

async function signIn(browser, phone, vp = { width: 390, height: 844 }) {
  const ctx = await browser.newContext({ viewport: vp });
  const pg = await ctx.newPage();
  pg.on('pageerror', (e) => errs.push(e.message));
  await pg.goto(APP + '#/login'); await pg.waitForSelector('#ph');
  await pg.fill('#ph', phone); await pg.click('text=Send code');
  await pg.waitForSelector('.sms-preview');
  const code = (await pg.textContent('.sms-preview')).match(/(\d{6})/)[1];
  await pg.fill('#otp', code); await pg.waitForTimeout(1500);
  return pg;
}
const hash = (pg) => pg.url().split('#')[1];

(async () => {
  const browser = await chromium.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', args: ['--autoplay-policy=no-user-gesture-required'] });

  // Stranger is refused
  const s0 = await (await browser.newContext()).newPage();
  await s0.goto(APP + '#/login'); await s0.waitForSelector('#ph');
  await s0.fill('#ph', '3001234567'); await s0.click('text=Send code'); await s0.waitForTimeout(700);
  check('stranger refused', (await s0.textContent('.err')).includes('not registered'));

  // Teacher marks Ali absent
  const t = await signIn(browser, '3991110001');
  check('teacher lands on class', hash(t).startsWith('/class/'), hash(t));
  await t.selectOption('#tp', 'u1-derived-units');
  await t.click('.att:has-text("Ali Raza") button[aria-label="Absent"]');
  check('save button shows absent count', (await t.textContent('.sticky-actions .primary')).includes('1 absent'));
  await t.click('.sticky-actions .primary'); await t.waitForTimeout(1500);
  check('WhatsApp card after absence', (await txt(t, '.wa-card')).includes('Mrs. Fatima Raza'));
  const href = await t.getAttribute('.wa-btn', 'href');
  check('wa.me link has number and text', href.startsWith('https://wa.me/923993330001?text=Dear%20Parent'));
  const pop = t.context().waitForEvent('page').catch(() => null);
  await t.click('.wa-btn'); const pp = await pop; if (pp) await pp.close(); await t.waitForTimeout(1000);
  check('WhatsApp card clears after sending', (await txt(t)).includes('have been told on WhatsApp'));
  await t.screenshot({ path: SP + '/shots/f1-teacher-class.png', fullPage: true });

  // Student: pending card, lesson plays and counts, quiz passes
  const s = await signIn(browser, '3992220001');
  check('student lands on home', hash(s) === '/home', hash(s));
  check('pending card on home', (await txt(s)).includes('Pending clearance'));
  await s.screenshot({ path: SP + '/shots/f1-student-home.png', fullPage: true });
  await s.click('text=Start missed lesson'); await s.waitForSelector('.player');
  await s.click('.player .play'); await s.waitForTimeout(3500);
  check('audio plays', /0:0[2-5]/.test(await s.textContent('.times')), await s.textContent('.times'));
  await s.click('.player .play'); await s.waitForTimeout(500);
  await s.screenshot({ path: SP + '/shots/f1-lesson.png' });
  await s.click('[data-track], .tracksw button[lang="ur"]'); await s.waitForTimeout(1800);
  check('Urdu narration switch', (await s.textContent('details.transcript summary')).includes('Urdu'));
  await s.click('.tracksw button:not([lang])'); await s.waitForTimeout(1500);
  // unlock via the server as a long listen would, then take the quiz with the right answers
  shell("from lms.models import *; LessonProgress.objects.filter(student__phone_number='+923992220001', lesson_id='u1-derived-units').update(unlocked=True); print('ok')");
  await s.goto(APP + '#/quiz/u1-derived-units'); await s.reload(); await s.waitForSelector('.opt');
  const answers = JSON.parse(shell("import json; from lms.models import *; a=QuizAttempt.objects.filter(student__phone_number='+923992220001').latest('started_at'); p=a.lesson.quiz; print(json.dumps([x['order'].index(p[x['q']]['answer']) for x in a.questions]))"));
  for (let i = 0; i < answers.length; i++) { await s.click(`.opt >> nth=${answers[i]}`); await s.click('.row .primary'); await s.waitForTimeout(250); }
  await s.waitForSelector('.result');
  check('quiz passed and cleared', (await txt(s)).includes('Cleared for class'), await txt(s));
  await s.screenshot({ path: SP + '/shots/f1-result.png' });
  await s.goto(APP + '#/admin'); await s.waitForTimeout(1200);
  check('student cannot open admin route', hash(s) === '/home', hash(s));

  // Teacher sees the green tick
  await t.reload(); await t.waitForTimeout(1500);
  check('teacher sees Cleared', (await txt(t, '.col-clear')).includes('Cleared'));

  // Parent
  const p = await signIn(browser, '3993330001');
  check('parent home', hash(p) === '/parent' && (await txt(p)).includes('Ali Raza'));
  check('parent sees cleared message', (await p.textContent('.wa')).includes('completed the missed lecture'));
  await p.click('a.subj-line'); await p.waitForTimeout(1200);
  check('child subject detail', (await txt(p)).includes('Passed'), await txt(p));
  await p.screenshot({ path: SP + '/shots/f1-parent-child.png', fullPage: true });

  // Admin: add a teacher, import, approve a request
  const a = await signIn(browser, '3994440001', { width: 1280, height: 820 });
  check('admin home', hash(a) === '/admin');
  await a.goto(APP + '#/people/teacher'); await a.waitForTimeout(1000);
  await a.click('h1 .primary'); await a.fill('#pn', 'Ms. Hira Saleem'); await a.fill('#pp', '3991119005'); await a.click('.sheet .primary'); await a.waitForTimeout(1200);
  check('admin added teacher', (await txt(a)).includes('Hira Saleem'));
  await a.goto(APP + '#/import/students'); await a.waitForTimeout(800);
  await a.fill('textarea', 'class_grade,class_stream,class_section,roll_number,student_name,student_gender,student_phone,parent_name,parent_phone\n11th,Pre-Medical,A,11A-21,Imran Ali,male,03992221021,Mr. Ali Khan,03993331021\n11th,Pre-Medical,A,11A-01,Dup,male,03992221023,Mr. X,03993331023\n');
  await a.click('text=Check file'); await a.waitForTimeout(1000);
  check('import reports bad row', (await txt(a)).includes('Roll number 11A-01 already exists'));
  await a.fill('textarea', 'class_grade,class_stream,class_section,roll_number,student_name,student_gender,student_phone,parent_name,parent_phone\n11th,Pre-Medical,A,11A-21,Imran Ali,male,03992221021,Mr. Ali Khan,03993331021\n');
  await a.click('text=Check file'); await a.waitForTimeout(1000); await a.click('text=Import 1 row'); await a.waitForTimeout(1200);
  check('import committed', (await txt(a)).includes('Imported'), await txt(a));
  await a.screenshot({ path: SP + '/shots/f1-admin-import.png' });

  // Urdu interface
  await s.goto(APP + '#/home'); await s.waitForTimeout(800);
  await s.click('.langbtn'); await s.waitForTimeout(1500);
  check('Urdu right to left', (await s.evaluate(() => document.documentElement.dir)) === 'rtl' && (await txt(s)).includes('السلام علیکم'));
  await s.screenshot({ path: SP + '/shots/f1-student-home-ur.png', fullPage: true });
  await s.click('.langbtn'); await s.waitForTimeout(800);

  // Gallery at three widths, light, dark and RTL; no horizontal overflow
  for (const [w, h] of [[360, 760], [768, 1024], [1440, 900]]) {
    const g = await (await browser.newContext({ viewport: { width: w, height: h } })).newPage();
    g.on('pageerror', (e) => errs.push(e.message));
    await g.goto(APP + '#/gallery'); await g.waitForTimeout(800);
    check(`gallery ${w}px no overflow`, !(await g.evaluate(() => document.documentElement.scrollWidth > innerWidth)));
    await g.screenshot({ path: `${SP}/shots/f1-gallery-${w}.png`, fullPage: true });
    if (w === 360) {
      await g.evaluate(() => document.documentElement.setAttribute('data-theme', 'dark')); await g.screenshot({ path: `${SP}/shots/f1-gallery-360-dark.png`, fullPage: true });
      await g.click('.langbtn'); await g.waitForTimeout(800);
      check('gallery RTL no overflow', !(await g.evaluate(() => document.documentElement.scrollWidth > innerWidth)));
    }
  }
  console.log(`\n${ok} passed, ${fail} failed; page errors: ${errs.length ? JSON.stringify(errs) : 'none'}`);
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

