"""Export a Claude Code session (.jsonl) to readable Markdown, and keep a copy of the raw file."""
import json
import re
import shutil
import sys
from datetime import datetime, timezone
from pathlib import Path

src = Path(sys.argv[1])
out_dir = Path(sys.argv[2])
stem = sys.argv[3]
out_dir.mkdir(parents=True, exist_ok=True)

HIDDEN = re.compile(r'<(system-reminder|ide_opened_file|ide_selection|local-command-caveat|local-command-stdout|command-name|'
                    r'command-message|command-args)>.*?</\1>', re.S)
TOOL_RESULT_LIMIT = 1500


def clean(text):
    return HIDDEN.sub('', text or '').strip()


def fence(text, lang=''):
    text = text.rstrip()
    ticks = '````' if '```' in text else '```'
    return f'{ticks}{lang}\n{text}\n{ticks}'


def trim(text, limit=TOOL_RESULT_LIMIT):
    return text if len(text) <= limit else text[:limit] + f'\n… ({len(text) - limit:,} more characters not shown)'


def stamp(o):
    ts = o.get('timestamp')
    if not ts:
        return ''
    d = datetime.fromisoformat(ts.replace('Z', '+00:00')).astimezone(timezone.utc)
    return d.strftime('%Y-%m-%d %H:%M UTC')


def tool_input_summary(name, inp):
    if name in ('Write',):
        body = inp.get('content', '')
        return f"`{inp.get('file_path', '')}` ({len(body.splitlines())} lines)\n\n" + fence(trim(body, 3000))
    if name == 'Edit':
        return f"`{inp.get('file_path', '')}`\n\nReplace:\n" + fence(trim(inp.get('old_string', ''), 800)) + \
               "\n\nWith:\n" + fence(trim(inp.get('new_string', ''), 1500))
    if name in ('Bash', 'PowerShell'):
        return (f"_{inp.get('description', '')}_\n\n" if inp.get('description') else '') + fence(trim(inp.get('command', ''), 4000), 'bash')
    if name == 'Read':
        return f"`{inp.get('file_path', '')}`"
    return fence(trim(json.dumps(inp, ensure_ascii=False, indent=1), 2000), 'json')


def result_text(block):
    c = block.get('content')
    if isinstance(c, str):
        return c
    parts = []
    for b in c or []:
        if b.get('type') == 'text':
            parts.append(b['text'])
        elif b.get('type') == 'image':
            parts.append('[image]')
    return '\n'.join(parts)


lines, title, model_seen = [], None, set()
counts = {'prompts': 0, 'replies': 0, 'tools': 0}
with open(src, encoding='utf-8') as f:
    entries = [json.loads(l) for l in f if l.strip()]
for o in entries:
    if o.get('type') == 'ai-title':
        title = o.get('aiTitle')
for o in entries:
    t = o.get('type')
    if t not in ('user', 'assistant') or o.get('isSidechain'):
        continue
    msg = o.get('message', {})
    content = msg.get('content')
    if isinstance(content, str):
        content = [{'type': 'text', 'text': content}]
    if t == 'user':
        texts, results = [], []
        for b in content or []:
            bt = b.get('type')
            if bt == 'text':
                txt = clean(b.get('text'))
                if txt and not o.get('isMeta'):
                    texts.append(txt)
            elif bt == 'document':
                texts.append('[attached PDF: AI-LMS-FBISE-Master-Blueprint-and-Team-Docs]')
            elif bt == 'image':
                texts.append('[attached image]')
            elif bt == 'tool_result':
                results.append(b)
        if texts:
            counts['prompts'] += 1
            lines.append(f"\n---\n\n## User · {stamp(o)}\n\n" + '\n\n'.join(texts) + '\n')
        for r in results:
            body = trim(clean(result_text(r)))
            label = 'Result (error)' if r.get('is_error') else 'Result'
            lines.append(f"<details><summary>{label}</summary>\n\n{fence(body)}\n\n</details>\n")
    else:
        model = msg.get('model')
        for b in content or []:
            bt = b.get('type')
            if bt == 'text' and b.get('text', '').strip():
                counts['replies'] += 1
                head = f"\n### Claude · {stamp(o)}" + (f" · {model}" if model and model not in model_seen else '')
                if model:
                    model_seen.add(model)
                lines.append(head + '\n\n' + b['text'].strip() + '\n')
            elif bt == 'tool_use':
                counts['tools'] += 1
                inp = b.get('input', {})
                desc = inp.get('description') or inp.get('file_path') or inp.get('pattern') or inp.get('query') or ''
                lines.append(f"<details><summary>Tool: {b.get('name')} · {str(desc)[:120]}</summary>\n\n"
                             f"{tool_input_summary(b.get('name'), inp)}\n\n</details>\n")

first = next((stamp(o) for o in entries if o.get('timestamp')), '')
last = next((stamp(o) for o in reversed(entries) if o.get('timestamp')), '')
header = f"""# Claude Code session: {title or 'EduSaas'}

Session `{src.stem}` · {first} to {last} · Project: `C:\\Users\\USER\\EduSaas`

Exported on {datetime.now(timezone.utc).strftime('%Y-%m-%d')} from the Claude Code transcript. It contains {counts['prompts']} messages
from you, {counts['replies']} replies from Claude and {counts['tools']} tool calls (shown folded; long outputs are trimmed).
Attached PDFs and screenshots are replaced by placeholders, and hidden system notes are removed. The complete raw
transcript is next to this file as `{stem}.jsonl`.

## What happened in this session

1. Analysed the AI LMS blueprint PDF and researched pricing, textbook rights, competitors, Urdu speech and data protection.
2. Wrote the change register, then built the clickable demo, the three Physics Unit 1 lessons and the Django backend (with a parallel session).
3. Researched popular LMSs and wrote the roadmap; recorded decisions D1–D8.
4. Built F20 (subjects), F21 (parent progress), F22 (college admin console), F3 (free alerts), F23 (Urdu screens) and F12 (Urdu narration).
5. Wrote the Stitch UI prompt pack and rebuilt the web app in React and TypeScript (F1), then switched it over to `/`.
"""
md = out_dir / f'{stem}.md'
md.write_text(header + ''.join(lines), encoding='utf-8')
raw = out_dir / f'{stem}.jsonl'
shutil.copyfile(src, raw)
print(md, f'{md.stat().st_size / 1e6:.1f} MB'); print(raw, f'{raw.stat().st_size / 1e6:.1f} MB'); print(counts)

